import type { BankQuestion } from "@/lib/bank";

/** Climate and Monsoon of India (Geography): 215 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"geo-climate-monsoon-1","question":"The climate of India is broadly described as:","options":["Tropical monsoon type","Cold temperate type","Equatorial rainforest type","Mediterranean type"],"answer":0,"explanation":"India has a tropical monsoon climate: a seasonal reversal of winds brings a wet summer and a largely dry winter.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"भारत की जलवायु को मोटे तौर पर किस प्रकार का कहा जाता है?","optionsHi":["उष्णकटिबंधीय मानसूनी प्रकार","शीत शीतोष्ण प्रकार","विषुवतीय वर्षावन प्रकार","भूमध्यसागरीय प्रकार"],"explanationHi":"भारत में उष्णकटिबंधीय मानसूनी जलवायु है: पवनों की दिशा में मौसमी उलटफेर से गर्मियाँ आर्द्र और सर्दियाँ काफी हद तक शुष्क रहती हैं।"},
  {"id":"geo-climate-monsoon-2","question":"The word “monsoon” is derived from an Arabic word meaning:","options":["Rainfall","Wind","Season","Storm"],"answer":2,"explanation":"“Monsoon” comes from the Arabic “mausim”, meaning season, because the winds reverse direction with the seasons.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"“मानसून” शब्द एक अरबी शब्द से बना है, जिसका अर्थ है:","optionsHi":["वर्षा","पवन","मौसम","तूफान"],"explanationHi":"“मानसून” अरबी शब्द “मौसिम” से आया है, जिसका अर्थ मौसम है, क्योंकि ऋतुओं के साथ पवनों की दिशा उलट जाती है।"},
  {"id":"geo-climate-monsoon-3","question":"According to the IMD's four-season division, the retreating (post-monsoon) season covers:","options":["October–November","December–February","March–May","June–September"],"answer":0,"explanation":"The IMD seasons are winter (Dec–Feb), hot weather (Mar–May), south-west monsoon (Jun–Sep) and retreating monsoon (Oct–Nov).","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"IMD (भारतीय मौसम विज्ञान विभाग) के चार ऋतुओं के विभाजन के अनुसार, निवर्तन (मानसून-पश्चात) ऋतु किस अवधि को कहते हैं?","optionsHi":["अक्टूबर–नवंबर","दिसंबर–फरवरी","मार्च–मई","जून–सितंबर"],"explanationHi":"IMD की ऋतुएँ हैं: शीत ऋतु (दिसंबर–फरवरी), ग्रीष्म ऋतु (मार्च–मई), दक्षिण-पश्चिम मानसून (जून–सितंबर) और निवर्तन मानसून (अक्टूबर–नवंबर)।"},
  {"id":"geo-climate-monsoon-4","question":"In most of north India, the coldest month of the year is:","options":["January","November","May","March"],"answer":0,"explanation":"January is the coldest month over the northern plains; mean temperatures then fall to about 10–15 °C.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"उत्तर भारत के अधिकांश भागों में वर्ष का सबसे ठंडा महीना कौन-सा होता है?","optionsHi":["जनवरी","नवंबर","मई","मार्च"],"explanationHi":"उत्तरी मैदानों में जनवरी सबसे ठंडा महीना होता है; तब औसत तापमान लगभग 10–15 °C तक गिर जाता है।"},
  {"id":"geo-climate-monsoon-5","question":"The normal date of onset of the south-west monsoon over Kerala is around:","options":["1 July","15 June","15 May","1 June"],"answer":3,"explanation":"The IMD's normal onset date over Kerala is 1 June (give or take about a week); by mid-June the monsoon normally reaches central India.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"केरल में दक्षिण-पश्चिम मानसून के आगमन की सामान्य तिथि लगभग कौन-सी है?","optionsHi":["1 जुलाई","15 जून","15 मई","1 जून"],"explanationHi":"IMD के अनुसार केरल में मानसून के आगमन की सामान्य तिथि 1 जून है (लगभग एक सप्ताह आगे-पीछे); मध्य जून तक मानसून सामान्यतः मध्य भारत पहुँच जाता है।"},
  {"id":"geo-climate-monsoon-6","question":"The winter rain brought to Punjab and Haryana by western disturbances is most useful for:","options":["Jute","Cotton","Wheat","Rice"],"answer":2,"explanation":"Light winter rain from western disturbances helps the rabi crops, especially wheat; rice, jute and cotton are kharif crops.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"पश्चिमी विक्षोभ से पंजाब और हरियाणा में होने वाली शीतकालीन वर्षा किस फसल के लिए सबसे अधिक उपयोगी है?","optionsHi":["जूट","कपास","गेहूँ","चावल"],"explanationHi":"पश्चिमी विक्षोभ से होने वाली हल्की शीतकालीन वर्षा रबी फसलों, विशेषकर गेहूँ के लिए लाभदायक है; चावल, जूट और कपास खरीफ फसलें हैं।"},
  {"id":"geo-climate-monsoon-7","question":"Pre-monsoon “mango showers”, which help the early ripening of mangoes, are a feature of:","options":["Rajasthan and Gujarat","Punjab and Haryana","Kerala and coastal Karnataka","Assam and the plains of West Bengal"],"answer":2,"explanation":"Mango showers fall in April–May along the Kerala and Karnataka coasts; the evening storms of Bengal and Assam are the Nor'westers (Kalbaisakhi).","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"मानसून-पूर्व “आम्र वर्षा” (मैंगो शावर), जो आमों के शीघ्र पकने में सहायक होती है, किन क्षेत्रों की विशेषता है?","optionsHi":["राजस्थान और गुजरात","पंजाब और हरियाणा","केरल और तटीय कर्नाटक","असम और पश्चिम बंगाल के मैदान"],"explanationHi":"आम्र वर्षा अप्रैल–मई में केरल और कर्नाटक के तटों पर होती है; बंगाल और असम की शाम की आँधियाँ नॉरवेस्टर (कालबैसाखी) कहलाती हैं।"},
  {"id":"geo-climate-monsoon-8","question":"Which of these places receives the lowest average annual rainfall?","options":["Shillong","Darjeeling","Jaisalmer","Kolkata"],"answer":2,"explanation":"Western Rajasthan, around Jaisalmer, gets well under 25 cm a year; Darjeeling, Kolkata and Shillong each receive well over 100 cm.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"इनमें से किस स्थान पर औसत वार्षिक वर्षा सबसे कम होती है?","optionsHi":["शिलांग","दार्जिलिंग","जैसलमेर","कोलकाता"],"explanationHi":"जैसलमेर के आसपास पश्चिमी राजस्थान में वर्ष भर में 25 सेमी से भी काफी कम वर्षा होती है; दार्जिलिंग, कोलकाता और शिलांग में प्रत्येक में 100 सेमी से काफी अधिक वर्षा होती है।"},
  {"id":"geo-climate-monsoon-9","question":"The south-east trade winds of the southern hemisphere turn into the south-west monsoon winds after crossing the equator because of:","options":["Western disturbances","Katabatic flow down the Himalaya","The Coriolis force","The Loo"],"answer":2,"explanation":"The Coriolis force deflects winds to the right in the northern hemisphere, so the south-easterlies become south-westerlies once they cross the equator.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"दक्षिणी गोलार्ध की दक्षिण-पूर्वी व्यापारिक पवनें विषुवत रेखा पार करने के बाद दक्षिण-पश्चिम मानसून पवनों में किसके कारण बदल जाती हैं?","optionsHi":["पश्चिमी विक्षोभ","हिमालय से नीचे उतरने वाला अवरोही प्रवाह","कोरिओलिस बल","लू"],"explanationHi":"कोरिओलिस बल उत्तरी गोलार्ध में पवनों को दाईं ओर विक्षेपित करता है, इसलिए दक्षिण-पूर्वी पवनें विषुवत रेखा पार करने पर दक्षिण-पश्चिमी पवनें बन जाती हैं।"},
  {"id":"geo-climate-monsoon-10","question":"Severe tropical cyclones hitting the Odisha and Andhra Pradesh coasts are most frequent in:","options":["October–November","July–August","January–February","December–January"],"answer":0,"explanation":"Cyclone activity in the Bay of Bengal peaks in the post-monsoon months of October–November, with a smaller peak in April–May; in July–August strong wind shear limits cyclone formation.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"ओडिशा और आंध्र प्रदेश के तटों से टकराने वाले प्रचंड उष्णकटिबंधीय चक्रवात सबसे अधिक किस समय आते हैं?","optionsHi":["अक्टूबर–नवंबर","जुलाई–अगस्त","जनवरी–फरवरी","दिसंबर–जनवरी"],"explanationHi":"बंगाल की खाड़ी में चक्रवातों की गतिविधि मानसून-पश्चात महीनों अक्टूबर–नवंबर में चरम पर होती है, और अप्रैल–मई में एक छोटा शिखर आता है; जुलाई–अगस्त में प्रबल पवन अपरूपण (विंड शियर) चक्रवातों के बनने को सीमित कर देता है।"},
  {"id":"geo-climate-monsoon-11","question":"In July, the Inter-Tropical Convergence Zone (the monsoon trough) over India lies roughly along:","options":["About 5°S over the Indian Ocean","About 35°N over Ladakh","The Ganga plain, about 20°–25°N","The equator"],"answer":2,"explanation":"In summer the ITCZ moves north and settles over the Ganga plain at about 20°–25°N, pulling in the monsoon winds; in winter it moves south of the equator.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"जुलाई में भारत के ऊपर अंतर-उष्णकटिबंधीय अभिसरण क्षेत्र (ITCZ) अर्थात मानसून द्रोणी लगभग कहाँ स्थित होता है?","optionsHi":["हिंद महासागर के ऊपर लगभग 5°S पर","लद्दाख के ऊपर लगभग 35°N पर","गंगा के मैदान के ऊपर, लगभग 20°–25°N पर","विषुवत रेखा पर"],"explanationHi":"गर्मियों में ITCZ उत्तर की ओर खिसककर गंगा के मैदान के ऊपर लगभग 20°–25°N पर स्थित हो जाता है और मानसूनी पवनों को खींचता है; सर्दियों में यह विषुवत रेखा के दक्षिण में चला जाता है।"},
  {"id":"geo-climate-monsoon-12","question":"The hot, humid spell over much of India after the monsoon withdraws, when skies clear but the ground is still wet, is called:","options":["October heat","Mango shower","Loo","Kalbaisakhi"],"answer":0,"explanation":"High temperatures plus high humidity after the monsoon retreats make the weather oppressive; this is known as “October heat”.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"मानसून की वापसी के बाद भारत के अधिकांश भागों में आसमान साफ होने पर भी भूमि के नम रहने से जो गर्म और उमस भरा मौसम रहता है, उसे क्या कहते हैं?","optionsHi":["क्वार की उमस (अक्टूबर की गर्मी)","आम्र वर्षा","लू","कालबैसाखी"],"explanationHi":"मानसून के लौटने के बाद ऊँचा तापमान और उच्च आर्द्रता मौसम को असहनीय बना देते हैं; इसे “अक्टूबर की गर्मी” (October heat) कहा जाता है।"},
  {"id":"geo-climate-monsoon-13","question":"The tropical easterly jet stream, which strengthens the south-west monsoon, blows:","options":["Over the Ganga plain in winter","Over peninsular India at about 14°N in summer","Near the surface over the Arabian Sea in winter","Over the Himalaya in winter"],"answer":1,"explanation":"In summer an upper-tropospheric easterly jet sets up over the peninsula at about 14°N; in winter it is the subtropical westerly jet that lies over north India.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उष्णकटिबंधीय पूर्वी जेट धारा, जो दक्षिण-पश्चिम मानसून को प्रबल बनाती है, कहाँ बहती है?","optionsHi":["सर्दियों में गंगा के मैदान के ऊपर","गर्मियों में लगभग 14°N पर प्रायद्वीपीय भारत के ऊपर","सर्दियों में अरब सागर के ऊपर धरातल के निकट","सर्दियों में हिमालय के ऊपर"],"explanationHi":"गर्मियों में ऊपरी क्षोभमंडल की एक पूर्वी जेट धारा प्रायद्वीप के ऊपर लगभग 14°N पर बनती है; सर्दियों में उत्तर भारत के ऊपर उपोष्णकटिबंधीय पछुआ जेट धारा स्थित होती है।"},
  {"id":"geo-climate-monsoon-14","question":"The sudden “burst” of the monsoon over north India in June is linked mainly to:","options":["The westerly jet shifting north of the Himalaya","The Loo intensifying over Rajasthan in May","Western disturbances entering India from Iran and Afghanistan","The winter high-pressure cell over the Thar"],"answer":0,"explanation":"As long as the westerly jet lies south of the Himalaya the monsoon cannot advance; when it jumps north of the Himalaya, the monsoon bursts over north India.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जून में उत्तर भारत में मानसून का अचानक “प्रस्फोट” (burst) मुख्य रूप से किससे जुड़ा है?","optionsHi":["पछुआ जेट धारा का हिमालय के उत्तर में खिसक जाना","मई में राजस्थान के ऊपर लू का तेज हो जाना","ईरान और अफगानिस्तान से भारत में पश्चिमी विक्षोभ का प्रवेश","थार के ऊपर शीतकालीन उच्च दाब कोष्ठ"],"explanationHi":"जब तक पछुआ जेट धारा हिमालय के दक्षिण में रहती है, मानसून आगे नहीं बढ़ सकता; जब यह हिमालय के उत्तर में चली जाती है, तो उत्तर भारत में मानसून का प्रस्फोट होता है।"},
  {"id":"geo-climate-monsoon-15","question":"El Niño, often associated with a weaker Indian monsoon, refers to:","options":["Warming of the western Indian Ocean relative to the east","Strengthening of the cold Somali current off East Africa","Abnormal cooling of surface waters of the central Pacific","Warming of the central and eastern equatorial Pacific"],"answer":3,"explanation":"El Niño is the warming of the eastern and central equatorial Pacific off Peru; cooling there is La Niña, and a warmer western Indian Ocean is a positive Indian Ocean Dipole.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अल नीनो, जो प्रायः कमजोर भारतीय मानसून से जुड़ा माना जाता है, क्या है?","optionsHi":["पश्चिमी हिंद महासागर का पूर्व की तुलना में गर्म होना","पूर्वी अफ्रीका के तट पर ठंडी सोमाली धारा का प्रबल होना","मध्य प्रशांत महासागर के सतही जल का असामान्य रूप से ठंडा होना","मध्य और पूर्वी विषुवतीय प्रशांत महासागर का गर्म होना"],"explanationHi":"अल नीनो पेरू के तट के निकट पूर्वी और मध्य विषुवतीय प्रशांत महासागर का गर्म होना है; वहाँ ठंडा होना ला नीना है, और पश्चिमी हिंद महासागर का अपेक्षाकृत गर्म होना धनात्मक हिंद महासागर द्विध्रुव (IOD) है।"},
  {"id":"geo-climate-monsoon-16","question":"In a positive Indian Ocean Dipole (IOD) event:","options":["The whole Indian Ocean cools uniformly, weakening the monsoon","The Pacific off Peru turns unusually cold, as in La Niña","The eastern Indian Ocean is warmer than the western, usually helping the monsoon","The western Indian Ocean is warmer than the eastern, usually helping the monsoon"],"answer":3,"explanation":"A positive IOD means warmer sea surface in the western Indian Ocean (near Africa) than in the east (near Sumatra); this generally favours good monsoon rain over India.","difficulty":"hard","source":"UPSC Prelims","questionHi":"धनात्मक हिंद महासागर द्विध्रुव (IOD) की घटना में:","optionsHi":["संपूर्ण हिंद महासागर एक समान रूप से ठंडा हो जाता है, जिससे मानसून कमजोर होता है","पेरू के निकट प्रशांत महासागर असामान्य रूप से ठंडा हो जाता है, जैसा ला नीना में होता है","पूर्वी हिंद महासागर पश्चिमी की तुलना में गर्म होता है, जिससे प्रायः मानसून को सहायता मिलती है","पश्चिमी हिंद महासागर पूर्वी की तुलना में गर्म होता है, जिससे प्रायः मानसून को सहायता मिलती है"],"explanationHi":"धनात्मक IOD का अर्थ है पश्चिमी हिंद महासागर (अफ्रीका के निकट) के समुद्री सतह का तापमान पूर्व (सुमात्रा के निकट) की तुलना में अधिक होना; यह सामान्यतः भारत में अच्छी मानसूनी वर्षा के अनुकूल होता है।"},
  {"id":"geo-climate-monsoon-17","question":"The Southern Oscillation Index is calculated from the difference in sea-level pressure between:","options":["Tahiti and Darwin","Mumbai and Chennai","Madagascar and Perth","Lima and Jakarta"],"answer":0,"explanation":"The Southern Oscillation is a see-saw of pressure across the Pacific, measured between Tahiti (central Pacific) and Darwin (northern Australia).","difficulty":"hard","source":"UPSC Prelims","questionHi":"दक्षिणी दोलन सूचकांक (Southern Oscillation Index) की गणना किन दो स्थानों के बीच समुद्र तल पर वायुदाब के अंतर से की जाती है?","optionsHi":["ताहिती और डार्विन","मुंबई और चेन्नई","मेडागास्कर और पर्थ","लीमा और जकार्ता"],"explanationHi":"दक्षिणी दोलन प्रशांत महासागर के आर-पार वायुदाब का एक उतार-चढ़ाव (see-saw) है, जिसे ताहिती (मध्य प्रशांत) और डार्विन (उत्तरी ऑस्ट्रेलिया) के बीच मापा जाता है।"},
  {"id":"geo-climate-monsoon-18","question":"The strong low-level cross-equatorial air current off the East African coast that carries moisture to India's west coast is the:","options":["Polar front jet","Kuroshio current","Tropical easterly jet stream","Somali (Findlater) jet"],"answer":3,"explanation":"The Somali or Findlater jet is a low-level jet along the East African highlands that feeds the Arabian Sea branch of the monsoon; the tropical easterly jet is an upper-level wind.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पूर्वी अफ्रीकी तट के निकट की वह प्रबल निम्न-स्तरीय अंतर-विषुवतीय वायु धारा, जो भारत के पश्चिमी तट तक नमी पहुँचाती है, कौन-सी है?","optionsHi":["ध्रुवीय वाताग्र जेट","कुरोशियो धारा","उष्णकटिबंधीय पूर्वी जेट धारा","सोमाली (फिंडलेटर) जेट"],"explanationHi":"सोमाली या फिंडलेटर जेट पूर्वी अफ्रीकी उच्चभूमि के साथ बहने वाली निम्न-स्तरीय जेट है, जो मानसून की अरब सागर शाखा को नमी देती है; उष्णकटिबंधीय पूर्वी जेट ऊपरी स्तर की पवन है।"},
  {"id":"geo-climate-monsoon-19","question":"The Tamil Nadu coast receives little rain during the south-west monsoon because:","options":["The monsoon never reaches south India in any year","Cold ocean currents flow along it and chill the summer winds","It lies on the windward side of the Western Ghats","It is in a rain shadow and parallel to the Bay branch's flow"],"answer":3,"explanation":"The Western Ghats block the Arabian Sea branch, and the Bay of Bengal branch blows parallel to the Coromandel coast instead of onto it, so the coast stays relatively dry until October.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"दक्षिण-पश्चिम मानसून के दौरान तमिलनाडु के तट पर कम वर्षा होती है, क्योंकि:","optionsHi":["मानसून किसी भी वर्ष दक्षिण भारत तक नहीं पहुँचता","ठंडी महासागरीय धाराएँ इसके साथ बहती हैं और गर्मी की पवनों को ठंडा कर देती हैं","यह पश्चिमी घाट के पवनाभिमुख ढाल पर स्थित है","यह वृष्टि छाया में है और खाड़ी शाखा के प्रवाह के समानांतर है"],"explanationHi":"पश्चिमी घाट अरब सागर शाखा को रोक लेते हैं, और बंगाल की खाड़ी की शाखा कोरोमंडल तट पर सीधे टकराने के बजाय उसके समानांतर बहती है, इसलिए अक्टूबर तक यह तट अपेक्षाकृत शुष्क रहता है।"},
  {"id":"geo-climate-monsoon-20","question":"The variability (coefficient of variation) of annual rainfall in India is highest in:","options":["The Konkan coast of Maharashtra","Coastal Kerala","Western Rajasthan","Meghalaya"],"answer":2,"explanation":"Variability is inversely related to the amount of rain: low-rainfall western Rajasthan shows variability above 50%, while the wet west coast and north-east are far more dependable.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत में वार्षिक वर्षा की परिवर्तिता (विचरण गुणांक) सबसे अधिक कहाँ है?","optionsHi":["महाराष्ट्र का कोंकण तट","तटीय केरल","पश्चिमी राजस्थान","मेघालय"],"explanationHi":"परिवर्तिता वर्षा की मात्रा के व्युत्क्रमानुपाती होती है: कम वर्षा वाले पश्चिमी राजस्थान में परिवर्तिता 50% से अधिक है, जबकि अधिक वर्षा वाले पश्चिमी तट और पूर्वोत्तर में वर्षा कहीं अधिक विश्वसनीय है।"},
  {"id":"geo-climate-monsoon-21","question":"The violent pre-monsoon evening thunderstorms called Kalbaisakhi in West Bengal are known in Assam as:","options":["Bardoli Chheerha","Coffee blossom showers","Mango showers","Loo"],"answer":0,"explanation":"In Assam the Nor'westers are called “Bardoli Chheerha”; they help tea, jute and rice. Blossom and mango showers belong to Karnataka and Kerala.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पश्चिम बंगाल में कालबैसाखी कहलाने वाली मानसून-पूर्व शाम की प्रचंड आँधी-तूफानी वर्षा को असम में क्या कहा जाता है?","optionsHi":["बारदोली छीड़ा","कॉफी पुष्प वर्षा","आम्र वर्षा","लू"],"explanationHi":"असम में नॉरवेस्टर को “बारदोली छीड़ा” कहा जाता है; ये चाय, जूट और चावल के लिए लाभदायक होती हैं। पुष्प वर्षा और आम्र वर्षा कर्नाटक और केरल की हैं।"},
  {"id":"geo-climate-monsoon-22","question":"A “break” in the monsoon over the northern plains usually occurs when:","options":["Western disturbances bring heavy rain to the plains","The monsoon trough shifts south to the equator","The monsoon trough moves to the Himalayan foothills","The tropical easterly jet strengthens over the peninsula"],"answer":2,"explanation":"When the axis of the monsoon trough moves to the foothills, rain stops over the plains but becomes heavy in the Himalayan foothills and the north-east.","difficulty":"hard","source":"UPSC Prelims","questionHi":"उत्तरी मैदानों में मानसून का “विच्छेद” (break) प्रायः कब होता है?","optionsHi":["जब पश्चिमी विक्षोभ से मैदानों में भारी वर्षा होती है","जब मानसून द्रोणी विषुवत रेखा तक दक्षिण में खिसक जाती है","जब मानसून द्रोणी हिमालय की तलहटी की ओर चली जाती है","जब प्रायद्वीप के ऊपर उष्णकटिबंधीय पूर्वी जेट धारा प्रबल हो जाती है"],"explanationHi":"जब मानसून द्रोणी की धुरी तलहटी की ओर खिसक जाती है, तो मैदानों में वर्षा रुक जाती है, परंतु हिमालय की तलहटी और पूर्वोत्तर में भारी वर्षा होती है।"},
  {"id":"geo-climate-monsoon-23","question":"Which is normally the wettest month at Chennai?","options":["July","September","November","August"],"answer":2,"explanation":"Chennai gets most of its rain from the north-east monsoon and Bay of Bengal depressions in October–December, with November the wettest month; July to September bring only moderate rain there.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"चेन्नई में सामान्यतः सबसे अधिक वर्षा वाला महीना कौन-सा है?","optionsHi":["जुलाई","सितंबर","नवंबर","अगस्त"],"explanationHi":"चेन्नई में अधिकांश वर्षा अक्टूबर–दिसंबर में उत्तर-पूर्वी मानसून और बंगाल की खाड़ी के अवदाबों से होती है, जिसमें नवंबर सबसे अधिक वर्षा वाला महीना है; जुलाई से सितंबर में वहाँ केवल मध्यम वर्षा होती है।"},
  {"id":"geo-climate-monsoon-24","question":"The withdrawal of the south-west monsoon normally begins from:","options":["Kerala and Karnataka in August","Assam and Meghalaya in July","Tamil Nadu and Andhra in October","North-west India in September"],"answer":3,"explanation":"The monsoon retreats in the reverse order of its arrival, starting from west Rajasthan in September; it leaves the southern peninsula last.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"दक्षिण-पश्चिम मानसून की वापसी सामान्यतः कहाँ से शुरू होती है?","optionsHi":["अगस्त में केरल और कर्नाटक से","जुलाई में असम और मेघालय से","अक्टूबर में तमिलनाडु और आंध्र प्रदेश से","सितंबर में उत्तर-पश्चिम भारत से"],"explanationHi":"मानसून अपने आगमन के उलटे क्रम में लौटता है, और सितंबर में पश्चिमी राजस्थान से शुरू होता है; दक्षिणी प्रायद्वीप को यह सबसे अंत में छोड़ता है।"},
  {"id":"geo-climate-monsoon-25","question":"How many of the following statements are correct? I. During La Niña, sea-surface temperatures in the eastern equatorial Pacific are below normal. II. Every El Niño year has produced a drought in India. III. The Walker circulation weakens during an El Niño. IV. A strong positive Indian Ocean Dipole can offset the effect of an El Niño on the Indian monsoon.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct; 1997 was a strong El Niño year with near-normal Indian rain, helped by a positive IOD. II is wrong: El Niño raises the risk of a weak monsoon but does not always cause drought.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कितने कथन सही हैं? I. ला नीना के दौरान पूर्वी विषुवतीय प्रशांत महासागर में समुद्री सतह का तापमान सामान्य से कम रहता है। II. प्रत्येक अल नीनो वर्ष में भारत में सूखा पड़ा है। III. अल नीनो के दौरान वॉकर परिसंचरण कमजोर हो जाता है। IV. एक प्रबल धनात्मक हिंद महासागर द्विध्रुव, भारतीय मानसून पर अल नीनो के प्रभाव को संतुलित कर सकता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, III और IV सही हैं; 1997 एक प्रबल अल नीनो वर्ष था, फिर भी धनात्मक IOD के सहारे भारत में लगभग सामान्य वर्षा हुई। II गलत है: अल नीनो से कमजोर मानसून का जोखिम बढ़ता है, किंतु इससे हमेशा सूखा नहीं पड़ता।"},
  {"id":"geo-climate-monsoon-26","question":"Match the local wind with its description. A. Chinook  B. Foehn  C. Sirocco  D. Harmattan; 1. Hot, dusty wind from the Sahara reaching Italy  2. Dry, dusty wind over West Africa, nicknamed “the doctor”  3. Warm wind descending the eastern slopes of the Rockies  4. Warm, dry wind on the leeward side of the Alps","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4"],"answer":1,"explanation":"The Chinook (“snow eater”) blows down the Rockies, the Foehn down the northern Alps, the Sirocco from the Sahara to southern Europe, and the Harmattan over the Guinea coast, where its dryness relieves the humid heat.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"स्थानीय पवन का उसके विवरण से मिलान कीजिए। A. चिनूक  B. फोहन  C. सिरोको  D. हरमट्टन; 1. सहारा से इटली पहुँचने वाली गर्म, धूलभरी पवन  2. पश्चिम अफ्रीका में बहने वाली शुष्क, धूलभरी पवन, जिसे “डॉक्टर” भी कहा जाता है  3. रॉकी पर्वत की पूर्वी ढालों से उतरने वाली गर्म पवन  4. आल्प्स के पवनविमुख ढाल पर बहने वाली गर्म, शुष्क पवन","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4"],"explanationHi":"चिनूक (“हिमभक्षी”) रॉकी पर्वत से नीचे उतरती है, फोहन आल्प्स के उत्तरी ढाल से, सिरोको सहारा से दक्षिणी यूरोप की ओर बहती है, और हरमट्टन गिनी तट पर बहती है, जहाँ इसकी शुष्कता आर्द्र गर्मी से राहत देती है।"},
  {"id":"geo-climate-monsoon-27","question":"Match the Indian weather phenomenon with its description. A. Loo  B. Kalbaisakhi  C. Mango showers  D. Blossom showers; 1. Pre-monsoon showers in Kerala and coastal Karnataka that help ripen mangoes  2. Hot, dry afternoon wind over the plains from Punjab to Bihar  3. Showers that make coffee flowers bloom in Kerala and nearby areas  4. Evening thunderstorms of West Bengal in the month of Baisakh","options":["A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-3, C-1, D-4"],"answer":0,"explanation":"Loo is the hot summer wind of the north-western plains; Kalbaisakhi is the Bengal Nor'wester; mango showers ripen mangoes on the south-west coast; blossom showers bring out coffee flowers.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारतीय मौसमी परिघटना का उसके विवरण से मिलान कीजिए। A. लू  B. कालबैसाखी  C. आम्र वर्षा  D. पुष्प वर्षा; 1. केरल और तटीय कर्नाटक की मानसून-पूर्व वर्षा, जो आम पकाने में सहायक होती है  2. पंजाब से बिहार तक मैदानों में दोपहर की गर्म, शुष्क पवन  3. वह वर्षा जिससे केरल और आसपास के क्षेत्रों में कॉफी के फूल खिलते हैं  4. बैसाख माह में पश्चिम बंगाल की शाम की आँधी-तूफान","optionsHi":["A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-3, C-1, D-4"],"explanationHi":"लू उत्तर-पश्चिमी मैदानों की गर्मियों की गर्म पवन है; कालबैसाखी बंगाल का नॉरवेस्टर है; आम्र वर्षा दक्षिण-पश्चिमी तट पर आमों को पकाती है; पुष्प वर्षा कॉफी के फूल खिलाती है।"},
  {"id":"geo-climate-monsoon-28","question":"How many of the following statements about jet streams are correct? I. The tropical easterly jet lies over peninsular India in summer. II. In winter the subtropical westerly jet lies south of the Himalaya. III. Jet streams blow in the upper troposphere, around 9–14 km up. IV. Western disturbances are steered towards India by the westerly jet.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: the tropical easterly jet lies over the peninsula in summer, the subtropical westerly jet lies south of the Himalaya in winter, jets blow in the upper troposphere, and the westerly jet steers western disturbances.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जेट धाराओं के बारे में निम्नलिखित में से कितने कथन सही हैं? I. गर्मियों में उष्णकटिबंधीय पूर्वी जेट धारा प्रायद्वीपीय भारत के ऊपर स्थित होती है। II. सर्दियों में उपोष्णकटिबंधीय पछुआ जेट धारा हिमालय के दक्षिण में स्थित होती है। III. जेट धाराएँ ऊपरी क्षोभमंडल में, लगभग 9–14 किमी की ऊँचाई पर बहती हैं। IV. पश्चिमी विक्षोभ पछुआ जेट धारा द्वारा भारत की ओर निर्देशित होते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: गर्मियों में उष्णकटिबंधीय पूर्वी जेट प्रायद्वीप के ऊपर होती है, सर्दियों में उपोष्णकटिबंधीय पछुआ जेट हिमालय के दक्षिण में होती है, जेट धाराएँ ऊपरी क्षोभमंडल में बहती हैं, और पछुआ जेट पश्चिमी विक्षोभों को आगे बढ़ाती है।"},
  {"id":"geo-climate-monsoon-29","question":"Which of the following is NOT one of the conditions that help the onset of the south-west monsoon?","options":["Differential heating of the Indian landmass and the surrounding seas","Northward shift of the ITCZ over the Ganga plain","The westerly jet staying south of the Himalaya through June","A high-pressure area east of Madagascar (the Mascarene High)"],"answer":2,"explanation":"The westerly jet must move north of the Himalaya for the monsoon to advance; if it stays south, the onset is held back. The other three are standard factors in the onset.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सी दक्षिण-पश्चिम मानसून के आगमन में सहायक स्थितियों में से एक नहीं है?","optionsHi":["भारतीय भूभाग और आसपास के समुद्रों का अलग-अलग गर्म होना","ITCZ का गंगा के मैदान के ऊपर उत्तर की ओर खिसकना","जून के दौरान पछुआ जेट धारा का हिमालय के दक्षिण में बने रहना","मेडागास्कर के पूर्व में एक उच्च दाब क्षेत्र (मस्कारिन उच्च)"],"explanationHi":"मानसून के आगे बढ़ने के लिए पछुआ जेट का हिमालय के उत्तर में जाना आवश्यक है; यदि यह दक्षिण में ही रहे तो मानसून का आगमन रुक जाता है। शेष तीन आगमन के मानक कारक हैं।"},
  {"id":"geo-climate-monsoon-30","question":"Arrange the following in the order in which the south-west monsoon normally reaches them: 1. Delhi  2. Thiruvananthapuram  3. Western Rajasthan (Jaisalmer)  4. Mumbai","options":["2-3-4-1","1-4-3-2","3-4-2-1","2-4-1-3"],"answer":3,"explanation":"Normal onset: Thiruvananthapuram about 1 June, Mumbai about 11 June, Delhi in late June, and west Rajasthan last, when the monsoon covers the whole country around 8 July.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित को उस क्रम में व्यवस्थित कीजिए जिसमें दक्षिण-पश्चिम मानसून सामान्यतः उन तक पहुँचता है: 1. दिल्ली  2. तिरुवनंतपुरम  3. पश्चिमी राजस्थान (जैसलमेर)  4. मुंबई","optionsHi":["2-3-4-1","1-4-3-2","3-4-2-1","2-4-1-3"],"explanationHi":"सामान्य आगमन: तिरुवनंतपुरम में लगभग 1 जून, मुंबई में लगभग 11 जून, दिल्ली में जून के अंत में, और पश्चिमी राजस्थान में सबसे अंत में, जब मानसून लगभग 8 जुलाई तक पूरे देश को ढक लेता है।"},
  {"id":"geo-climate-monsoon-31","question":"How many of the following statements about rainfall in India are correct? I. Roughly three-fourths of India's annual rainfall comes during June–September. II. Parts of the Khasi and Jaintia hills receive more than 1000 cm of rain a year. III. Across the northern plains, rainfall decreases from east to west. IV. Tamil Nadu receives most of its annual rainfall during June–September.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: Tamil Nadu gets most of its rain from October to December from the north-east monsoon and cyclones.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत में वर्षा के बारे में निम्नलिखित में से कितने कथन सही हैं? I. भारत की वार्षिक वर्षा का लगभग तीन-चौथाई भाग जून–सितंबर के दौरान प्राप्त होता है। II. खासी और जयंतिया पहाड़ियों के कुछ भागों में प्रतिवर्ष 1000 सेमी से अधिक वर्षा होती है। III. उत्तरी मैदानों में वर्षा पूर्व से पश्चिम की ओर घटती जाती है। IV. तमिलनाडु में अधिकांश वार्षिक वर्षा जून–सितंबर के दौरान होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: तमिलनाडु में अधिकांश वर्षा अक्टूबर से दिसंबर के बीच उत्तर-पूर्वी मानसून और चक्रवातों से होती है।"},
  {"id":"geo-climate-monsoon-32","question":"Assertion (A): The Coromandel coast receives heavy rainfall in October–November. Reason (R): In October–November the south-west monsoon winds blow directly onto the Tamil Nadu coast.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":0,"explanation":"A is true, but the rain comes from north-east winds and cyclonic depressions that pick up moisture over the Bay of Bengal, not from the south-west monsoon, which has withdrawn by then. So R is false.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): कोरोमंडल तट पर अक्टूबर–नवंबर में भारी वर्षा होती है। कारण (R): अक्टूबर–नवंबर में दक्षिण-पश्चिम मानसून पवनें सीधे तमिलनाडु तट पर बहती हैं।","optionsHi":["A सही है, किंतु R गलत है","A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A गलत है, किंतु R सही है"],"explanationHi":"A सही है, परंतु वर्षा उत्तर-पूर्वी पवनों और चक्रवाती अवदाबों से होती है, जो बंगाल की खाड़ी से नमी ग्रहण करते हैं, न कि दक्षिण-पश्चिम मानसून से, जो तब तक लौट चुका होता है। अतः R गलत है।"},
  {"id":"geo-climate-monsoon-33","question":"Which of these places is NOT on the windward side of the Western Ghats?","options":["Mangaluru","Bengaluru","Mumbai","Kozhikode"],"answer":1,"explanation":"Mangaluru, Mumbai and Kozhikode lie on the coast facing the Arabian Sea branch and get heavy rain; Bengaluru sits on the plateau in the rain shadow, with much lower rainfall.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कौन-सा स्थान पश्चिमी घाट के पवनाभिमुख ढाल पर नहीं है?","optionsHi":["मंगलुरु","बेंगलुरु","मुंबई","कोझीकोड"],"explanationHi":"मंगलुरु, मुंबई और कोझीकोड अरब सागर शाखा के सामने वाले तट पर हैं और यहाँ भारी वर्षा होती है; बेंगलुरु पठार पर वृष्टि छाया में स्थित है, जहाँ वर्षा बहुत कम होती है।"},
  {"id":"geo-climate-monsoon-34","question":"How many of the following statements about tropical cyclones are correct? I. In the northern hemisphere, winds around a cyclone rotate anticlockwise. II. The strongest winds of a cyclone are found inside its eye. III. Cyclones usually intensify after landfall because of friction with land. IV. Storm surge is a major cause of deaths when a cyclone strikes a coast.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and IV are correct. The eye is calm with the lowest pressure; the strongest winds are in the eyewall (II wrong). Cyclones weaken after landfall as they lose their moisture supply and face friction (III wrong).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उष्णकटिबंधीय चक्रवातों के बारे में निम्नलिखित में से कितने कथन सही हैं? I. उत्तरी गोलार्ध में चक्रवात के चारों ओर पवनें वामावर्त (anticlockwise) घूमती हैं। II. चक्रवात की सबसे तेज पवनें उसकी आँख के भीतर पाई जाती हैं। III. भूमि से घर्षण के कारण चक्रवात स्थलगमन (landfall) के बाद प्रायः और प्रबल हो जाते हैं। IV. जब चक्रवात किसी तट से टकराता है तो तूफानी लहर (storm surge) मृत्यु का एक प्रमुख कारण होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और IV सही हैं। आँख शांत होती है और वहाँ दाब सबसे कम होता है; सबसे तेज पवनें आँख की दीवार (eyewall) में होती हैं (II गलत)। नमी की आपूर्ति कटने और घर्षण के कारण चक्रवात स्थलगमन के बाद कमजोर पड़ते हैं (III गलत)।"},
  {"id":"geo-climate-monsoon-35","question":"Which of the following pairs is NOT correctly matched?","options":["Tropical easterly jet — upper-level wind over the peninsula in summer","Western disturbance — winter rain in Punjab","Loo — humid evening thunderstorms in Assam","Mascarene High — high pressure near Madagascar"],"answer":2,"explanation":"The Loo is a hot, dry afternoon wind of the north-western plains in May–June; humid evening storms in Assam are the Nor'westers (Bardoli Chheerha).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["उष्णकटिबंधीय पूर्वी जेट — गर्मियों में प्रायद्वीप के ऊपर ऊपरी स्तर की पवन","पश्चिमी विक्षोभ — पंजाब में शीतकालीन वर्षा","लू — असम में शाम की आर्द्र आँधी-तूफान","मस्कारिन उच्च — मेडागास्कर के निकट उच्च दाब"],"explanationHi":"लू मई–जून में उत्तर-पश्चिमी मैदानों की दोपहर की गर्म, शुष्क पवन है; असम में शाम की आर्द्र आँधियाँ नॉरवेस्टर (बारदोली छीड़ा) हैं।"},
  {"id":"geo-climate-monsoon-36","question":"Match the Köppen climate type with the region of India where it is found. A. Amw  B. As  C. BWhw  D. Dfc; 1. Coromandel coast of Tamil Nadu  2. Arunachal Pradesh  3. West coast south of Goa  4. Extreme western Rajasthan","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-4, B-1, C-3, D-2","A-3, B-2, C-4, D-1"],"answer":0,"explanation":"Amw (monsoon with a short dry season) covers the west coast south of Goa; As (dry summer) the Coromandel coast; BWhw (hot desert) extreme west Rajasthan; Dfc (cold humid winter, short summer) Arunachal Pradesh.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कोपेन के जलवायु प्रकार का उस भारतीय क्षेत्र से मिलान कीजिए जहाँ वह पाया जाता है। A. Amw  B. As  C. BWhw  D. Dfc; 1. तमिलनाडु का कोरोमंडल तट  2. अरुणाचल प्रदेश  3. गोवा के दक्षिण में पश्चिमी तट  4. अत्यंत पश्चिमी राजस्थान","optionsHi":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-4, B-1, C-3, D-2","A-3, B-2, C-4, D-1"],"explanationHi":"Amw (लघु शुष्क ऋतु वाला मानसून) गोवा के दक्षिण में पश्चिमी तट पर है; As (शुष्क ग्रीष्म) कोरोमंडल तट पर; BWhw (उष्ण मरुस्थल) अत्यंत पश्चिमी राजस्थान में; Dfc (ठंडी आर्द्र सर्दी, छोटी गर्मी) अरुणाचल प्रदेश में।"},
  {"id":"geo-climate-monsoon-37","question":"Which of these pairs of storm name and region is NOT correct?","options":["Tornado — tropical cyclone of the Indian Ocean","Willy-willy — north-western Australia","Hurricane — Caribbean and North Atlantic","Typhoon — north-west Pacific and South China Sea"],"answer":0,"explanation":"Indian Ocean storms are simply called cyclones. A tornado is a small, very intense funnel of wind over land, best known in the central USA, not a tropical cyclone.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"तूफान के नाम और क्षेत्र का इनमें से कौन-सा युग्म सही नहीं है?","optionsHi":["टॉरनेडो — हिंद महासागर का उष्णकटिबंधीय चक्रवात","विली-विली — उत्तर-पश्चिमी ऑस्ट्रेलिया","हरिकेन — कैरिबियन और उत्तरी अटलांटिक","टाइफून — उत्तर-पश्चिमी प्रशांत और दक्षिण चीन सागर"],"explanationHi":"हिंद महासागर के तूफानों को केवल चक्रवात कहा जाता है। टॉरनेडो भूमि के ऊपर पवन की एक छोटी, अत्यंत तीव्र कीप है, जो संयुक्त राज्य अमेरिका के मध्य भाग में सबसे अधिक प्रसिद्ध है; यह उष्णकटिबंधीय चक्रवात नहीं है।"},
  {"id":"geo-climate-monsoon-38","question":"Which of these stations has the lowest annual range of temperature?","options":["Delhi","Leh","Sri Ganganagar","Thiruvananthapuram"],"answer":3,"explanation":"Thiruvananthapuram is near the equator and the sea, so maritime influence keeps its annual range to a few degrees; Delhi, Sri Ganganagar and Leh are continental with large ranges.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से किस स्टेशन पर तापमान का वार्षिक परिसर सबसे कम है?","optionsHi":["दिल्ली","लेह","श्रीगंगानगर","तिरुवनंतपुरम"],"explanationHi":"तिरुवनंतपुरम विषुवत रेखा और समुद्र के निकट है, इसलिए सामुद्रिक प्रभाव से इसका वार्षिक परिसर कुछ ही अंश रहता है; दिल्ली, श्रीगंगानगर और लेह महाद्वीपीय हैं और इनका परिसर बड़ा होता है।"},
  {"id":"geo-climate-monsoon-39","question":"How many of the following statements about the retreating monsoon are correct? I. The monsoon withdraws from north-west India first. II. During the retreat the monsoon trough weakens and shifts south. III. Cyclones that form over the Andaman Sea in October–November often cross the eastern coast. IV. The retreating monsoon gives the Coromandel coast of Tamil Nadu much of its annual rainfall.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: withdrawal starts in the north-west, the trough weakens and moves south, Andaman Sea cyclones cross the east coast, and October–December rain gives the Tamil Nadu coast much of its annual total.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निवर्ती (लौटते) मानसून के बारे में निम्नलिखित में से कितने कथन सही हैं? I. मानसून सबसे पहले उत्तर-पश्चिम भारत से लौटता है। II. वापसी के दौरान मानसून द्रोणी कमजोर पड़ जाती है और दक्षिण की ओर खिसक जाती है। III. अक्टूबर–नवंबर में अंडमान सागर में बनने वाले चक्रवात प्रायः पूर्वी तट को पार करते हैं। IV. निवर्ती मानसून तमिलनाडु के कोरोमंडल तट को उसकी वार्षिक वर्षा का बड़ा भाग देता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: वापसी उत्तर-पश्चिम से शुरू होती है, द्रोणी कमजोर होकर दक्षिण की ओर खिसकती है, अंडमान सागर के चक्रवात पूर्वी तट को पार करते हैं, और अक्टूबर–दिसंबर की वर्षा तमिलनाडु तट को उसकी वार्षिक वर्षा का बड़ा भाग देती है।"},
  {"id":"geo-climate-monsoon-40","question":"How many of the following pairs of place and its main rainy period are correctly matched? I. Chennai — October to December  II. Srinagar — July to August, from the south-west monsoon  III. Mumbai — June to September","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Chennai gets its rain in Oct–Dec and Mumbai in Jun–Sep. Srinagar, shielded by the Pir Panjal, gets most of its precipitation in late winter and spring (peaking around March) from western disturbances, so II is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"स्थान और उसके मुख्य वर्षा काल के निम्नलिखित में से कितने युग्म सही सुमेलित हैं? I. चेन्नई — अक्टूबर से दिसंबर  II. श्रीनगर — जुलाई से अगस्त, दक्षिण-पश्चिम मानसून से  III. मुंबई — जून से सितंबर","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"चेन्नई में वर्षा अक्टूबर–दिसंबर में और मुंबई में जून–सितंबर में होती है। पीर पंजाल से सुरक्षित श्रीनगर में अधिकांश वर्षण पश्चिमी विक्षोभों से शीत ऋतु के अंत और वसंत में (मार्च के आसपास चरम पर) होता है, अतः II गलत है।"},
  {"id":"geo-climate-monsoon-41","question":"A line on a map joining places that receive the same amount of rainfall is called an:","options":["Isotherm","Isobar","Isohyet","Isohel"],"answer":2,"explanation":"An isohyet joins points of equal rainfall. Isotherms join equal temperature, isobars equal pressure and isohels equal sunshine.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"मानचित्र पर समान वर्षा प्राप्त करने वाले स्थानों को मिलाने वाली रेखा क्या कहलाती है?","optionsHi":["समताप रेखा (आइसोथर्म)","समदाब रेखा (आइसोबार)","समवर्षा रेखा (आइसोहाइट)","समसूर्यातप रेखा (आइसोहेल)"],"explanationHi":"समवर्षा रेखा (आइसोहाइट) समान वर्षा वाले बिंदुओं को जोड़ती है। समताप रेखा समान तापमान को, समदाब रेखा समान दाब को और आइसोहेल समान धूप को जोड़ती है।"},
  {"id":"geo-climate-monsoon-42","question":"Mumbai receives its heavy June–September rain mainly from the:","options":["Bay of Bengal branch of the south-west monsoon","Arabian Sea branch of the south-west monsoon","North-east monsoon","Western disturbances"],"answer":1,"explanation":"The Arabian Sea branch strikes the west coast and the Western Ghats, drenching Mumbai and the Konkan. The Bay of Bengal branch serves the north-east and the Ganga plain.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"जून–सितंबर में मुंबई में भारी वर्षा मुख्य रूप से किससे होती है?","optionsHi":["दक्षिण-पश्चिम मानसून की बंगाल की खाड़ी शाखा","दक्षिण-पश्चिम मानसून की अरब सागर शाखा","उत्तर-पूर्वी मानसून","पश्चिमी विक्षोभ"],"explanationHi":"अरब सागर शाखा पश्चिमी तट और पश्चिमी घाट से टकराकर मुंबई और कोंकण में भारी वर्षा करती है। बंगाल की खाड़ी शाखा पूर्वोत्तर और गंगा के मैदान को वर्षा देती है।"},
  {"id":"geo-climate-monsoon-43","question":"According to the IMD, the south-west monsoon season covers the months of:","options":["March–May","October–December","January–February","June–September"],"answer":3,"explanation":"The IMD's four seasons are winter (Jan–Feb), pre-monsoon (Mar–May), south-west monsoon (Jun–Sep) and post-monsoon (Oct–Dec).","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"IMD के अनुसार, दक्षिण-पश्चिम मानसून ऋतु किन महीनों को कहते हैं?","optionsHi":["मार्च–मई","अक्टूबर–दिसंबर","जनवरी–फरवरी","जून–सितंबर"],"explanationHi":"IMD की चार ऋतुएँ हैं: शीत ऋतु (जनवरी–फरवरी), मानसून-पूर्व (मार्च–मई), दक्षिण-पश्चिम मानसून (जून–सितंबर) और मानसून-पश्चात (अक्टूबर–दिसंबर)।"},
  {"id":"geo-climate-monsoon-44","question":"In winter, the prevailing monsoon winds over most of India blow from the:","options":["North-east","South-west","South-east","West"],"answer":0,"explanation":"In winter a high-pressure area over north-west India and Central Asia sends cold, dry winds outward from land to sea; over India they blow from the north-east.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"सर्दियों में भारत के अधिकांश भागों में प्रचलित मानसूनी पवनें किस दिशा से बहती हैं?","optionsHi":["उत्तर-पूर्व","दक्षिण-पश्चिम","दक्षिण-पूर्व","पश्चिम"],"explanationHi":"सर्दियों में उत्तर-पश्चिम भारत और मध्य एशिया के ऊपर उच्च दाब क्षेत्र बनता है, जो ठंडी, शुष्क पवनों को स्थल से समुद्र की ओर भेजता है; भारत में ये उत्तर-पूर्व से बहती हैं।"},
  {"id":"geo-climate-monsoon-45","question":"In May, the highest day temperatures in India are usually recorded in:","options":["The Nilgiri hills of Tamil Nadu","Coastal Kerala and Konkan","Rajasthan and the north-west","Meghalaya and the north-east"],"answer":2,"explanation":"With the sun high and dry, clear skies, the Thar region of Rajasthan records 45 °C or more in May–June; coasts and hills stay much cooler.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"मई में भारत में दिन का सबसे अधिक तापमान प्रायः कहाँ दर्ज किया जाता है?","optionsHi":["तमिलनाडु की नीलगिरि पहाड़ियाँ","तटीय केरल और कोंकण","राजस्थान और उत्तर-पश्चिम","मेघालय और पूर्वोत्तर"],"explanationHi":"सूर्य के ऊँचा होने और शुष्क, साफ आसमान के कारण राजस्थान के थार क्षेत्र में मई–जून में 45 °C या उससे अधिक तापमान दर्ज होता है; तट और पहाड़ी क्षेत्र कहीं अधिक ठंडे रहते हैं।"},
  {"id":"geo-climate-monsoon-46","question":"Mawsynram and Cherrapunji receive extremely heavy rainfall mainly because:","options":["They lie on the leeward side of the Khasi hills","Western disturbances bring them heavy winter snow and rain","The north-east monsoon strikes them head-on in December","The funnel-shaped Khasi hills force the Bay branch to rise"],"answer":3,"explanation":"The southern face of the Khasi hills forms a funnel that catches the moisture-laden Bay of Bengal branch; forced ascent gives very heavy orographic rain. Their rain comes from the south-west monsoon, not winter systems.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"मॉसिनराम और चेरापूँजी में अत्यंत भारी वर्षा मुख्य रूप से इसलिए होती है, क्योंकि:","optionsHi":["वे खासी पहाड़ियों के पवनविमुख ढाल पर स्थित हैं","पश्चिमी विक्षोभ उन्हें भारी शीतकालीन हिमपात और वर्षा देते हैं","उत्तर-पूर्वी मानसून दिसंबर में उनसे सीधे टकराता है","कीप के आकार की खासी पहाड़ियाँ खाड़ी शाखा को ऊपर उठने के लिए बाध्य करती हैं"],"explanationHi":"खासी पहाड़ियों का दक्षिणी ढाल एक कीप जैसा बनाता है, जो नमी से लदी बंगाल की खाड़ी शाखा को रोक लेता है; बलपूर्वक ऊपर उठने से अत्यंत भारी पर्वतीय वर्षा होती है। इनकी वर्षा दक्षिण-पश्चिम मानसून से होती है, शीतकालीन तंत्रों से नहीं।"},
  {"id":"geo-climate-monsoon-47","question":"Leh in Ladakh is a cold desert mainly because it:","options":["Lies in the Himalayan rain shadow at high altitude","Is far north of the Tropic of Cancer","Receives only the dry north-east monsoon in winter","Lies on the windward side of the Pir Panjal"],"answer":0,"explanation":"The Great Himalaya blocks the monsoon, so Leh gets only about 10 cm of precipitation a year, and its height of about 3,500 m keeps it cold.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"लद्दाख में लेह मुख्य रूप से शीत मरुस्थल इसलिए है, क्योंकि वह:","optionsHi":["अधिक ऊँचाई पर हिमालय की वृष्टि छाया में स्थित है","कर्क रेखा से बहुत उत्तर में है","सर्दियों में केवल शुष्क उत्तर-पूर्वी मानसून प्राप्त करता है","पीर पंजाल के पवनाभिमुख ढाल पर स्थित है"],"explanationHi":"महान हिमालय मानसून को रोक देता है, इसलिए लेह में वर्ष भर में केवल लगभग 10 सेमी वर्षण होता है, और लगभग 3,500 मी की ऊँचाई उसे ठंडा रखती है।"},
  {"id":"geo-climate-monsoon-48","question":"The distribution of south-west monsoon rainfall over India is governed to a large extent by:","options":["Temperature: hotter places always get more rain","Relief: windward slopes wet, leeward slopes dry","Latitude: rain increases steadily northward","The Coriolis force acting on the winds"],"answer":1,"explanation":"NCERT notes that monsoon rainfall is largely relief-governed: the Western Ghats and north-eastern hills get heavy rain on their windward sides while the Deccan interior and Ladakh lie in rain shadow.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"भारत में दक्षिण-पश्चिम मानसूनी वर्षा का वितरण काफी हद तक किससे निर्धारित होता है?","optionsHi":["तापमान: अधिक गर्म स्थानों में हमेशा अधिक वर्षा होती है","उच्चावच: पवनाभिमुख ढाल आर्द्र, पवनविमुख ढाल शुष्क","अक्षांश: वर्षा उत्तर की ओर लगातार बढ़ती है","पवनों पर कार्यरत कोरिओलिस बल"],"explanationHi":"NCERT के अनुसार मानसूनी वर्षा काफी हद तक उच्चावच द्वारा नियंत्रित होती है: पश्चिमी घाट और पूर्वोत्तर की पहाड़ियों के पवनाभिमुख ढालों पर भारी वर्षा होती है, जबकि दक्कन का आंतरिक भाग और लद्दाख वृष्टि छाया में स्थित हैं।"},
  {"id":"geo-climate-monsoon-49","question":"As per the IMD's revised normal dates (2020), by about which date does the south-west monsoon normally cover the whole of India?","options":["1 June","15 September","8 July","15 October"],"answer":2,"explanation":"The revised normal date for the monsoon to cover the entire country is 8 July. 1 June is the onset over Kerala, and 15 October is the normal date of complete withdrawal.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"IMD की संशोधित सामान्य तिथियों (2020) के अनुसार, दक्षिण-पश्चिम मानसून सामान्यतः किस तिथि तक पूरे भारत को ढक लेता है?","optionsHi":["1 जून","15 सितंबर","8 जुलाई","15 अक्टूबर"],"explanationHi":"मानसून के पूरे देश को ढकने की संशोधित सामान्य तिथि 8 जुलाई है। 1 जून केरल में आगमन की तिथि है, और 15 अक्टूबर पूर्ण वापसी की सामान्य तिथि है।"},
  {"id":"geo-climate-monsoon-50","question":"Which of these regions does NOT normally receive more than 200 cm of rainfall a year?","options":["The Konkan and Malabar coast","The Andaman and Nicobar Islands","The southern slopes of the Meghalaya plateau","Interior Marathwada in Maharashtra"],"answer":3,"explanation":"Marathwada lies in the rain shadow of the Western Ghats and gets roughly 50–100 cm. The west coast, Andamans and Meghalaya slopes all exceed 200 cm.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"इनमें से किस क्षेत्र में सामान्यतः प्रतिवर्ष 200 सेमी से अधिक वर्षा नहीं होती?","optionsHi":["कोंकण और मालाबार तट","अंडमान और निकोबार द्वीप समूह","मेघालय पठार के दक्षिणी ढाल","महाराष्ट्र का आंतरिक मराठवाड़ा"],"explanationHi":"मराठवाड़ा पश्चिमी घाट की वृष्टि छाया में स्थित है और यहाँ लगभग 50–100 सेमी वर्षा होती है। पश्चिमी तट, अंडमान और मेघालय के ढालों में 200 सेमी से अधिक वर्षा होती है।"},
  {"id":"geo-climate-monsoon-51","question":"The diurnal (day–night) range of temperature in India is greatest in:","options":["The Thar desert","Coastal Kerala","The Sundarbans delta","The Lakshadweep islands"],"answer":0,"explanation":"Dry air and clear skies let desert sand heat strongly by day and lose heat fast at night, so the Thar can swing by 20 °C or more in a day. Coasts and islands are moderated by the sea.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"भारत में तापमान का दैनिक (दिन–रात) परिसर सबसे अधिक कहाँ है?","optionsHi":["थार मरुस्थल","तटीय केरल","सुंदरबन डेल्टा","लक्षद्वीप द्वीप समूह"],"explanationHi":"शुष्क वायु और साफ आसमान के कारण मरुस्थल की रेत दिन में तेजी से गर्म होती है और रात में तेजी से ऊष्मा खो देती है, इसलिए थार में एक दिन में तापमान 20 °C या उससे अधिक तक बदल सकता है। तट और द्वीप समुद्र के कारण संतुलित रहते हैं।"},
  {"id":"geo-climate-monsoon-52","question":"The centre of a large city is often several degrees warmer than the surrounding countryside, especially at night. This is called:","options":["A temperature inversion layer","The urban heat island effect","Advection fog over the city","Föhn (chinook) effect"],"answer":1,"explanation":"Concrete and asphalt store heat by day and release it at night, and traffic and buildings add waste heat, creating an urban heat island. An inversion is temperature rising with height.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"किसी बड़े शहर का केंद्र प्रायः आसपास के ग्रामीण क्षेत्र की तुलना में कई डिग्री अधिक गर्म होता है, विशेषकर रात में। इसे क्या कहते हैं?","optionsHi":["तापमान व्युत्क्रमण परत","नगरीय ऊष्मा द्वीप प्रभाव","शहर के ऊपर अभिवहन कोहरा","फोहन (चिनूक) प्रभाव"],"explanationHi":"कंक्रीट और डामर दिन में ऊष्मा संग्रहीत करते हैं और रात में छोड़ते हैं, तथा यातायात और इमारतें अतिरिक्त ऊष्मा जोड़ते हैं, जिससे नगरीय ऊष्मा द्वीप बनता है। व्युत्क्रमण में ऊँचाई के साथ तापमान बढ़ता है।"},
  {"id":"geo-climate-monsoon-53","question":"Clear, cold nights with ground frost in north India in December–January are mainly due to:","options":["Heavy cloud cover left over from the retreating monsoon","Warm, moist easterly winds blowing in from the Bay of Bengal","Dry, clear, high-pressure air letting the ground cool fast","The tropical easterly jet descending over the plains"],"answer":2,"explanation":"In winter, high pressure brings calm, dry air and cloudless skies, so the ground radiates heat away at night and temperatures can fall below freezing in Punjab and Haryana.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"दिसंबर–जनवरी में उत्तर भारत में साफ, ठंडी रातें और पाला मुख्य रूप से किस कारण होता है?","optionsHi":["लौटते मानसून से बचे घने बादलों का आवरण","बंगाल की खाड़ी से आने वाली गर्म, नम पूर्वी पवनें","शुष्क, साफ, उच्च दाब वाली वायु, जिससे धरातल तेजी से ठंडा हो जाता है","मैदानों पर उतरती उष्णकटिबंधीय पूर्वी जेट धारा"],"explanationHi":"सर्दियों में उच्च दाब के कारण शांत, शुष्क वायु और बादलरहित आसमान रहता है, इसलिए रात में धरातल ऊष्मा का विकिरण कर देता है और पंजाब तथा हरियाणा में तापमान हिमांक से नीचे गिर सकता है।"},
  {"id":"geo-climate-monsoon-54","question":"On average, the temperature in the troposphere falls with height at about:","options":["1 °C per 100 km","6.5 °C per 1,000 m","10 °C per 100 m","0.5 °C per 1,000 m"],"answer":1,"explanation":"The normal lapse rate is about 6.5 °C per 1,000 m, which is why hill stations like Shimla and Ooty are much cooler than the plains below them.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"औसतन, क्षोभमंडल में ऊँचाई के साथ तापमान लगभग कितना घटता है?","optionsHi":["1 °C प्रति 100 किमी","6.5 °C प्रति 1,000 मी","10 °C प्रति 100 मी","0.5 °C प्रति 1,000 मी"],"explanationHi":"सामान्य ह्रास दर लगभग 6.5 °C प्रति 1,000 मी है, इसीलिए शिमला और ऊटी जैसे पर्वतीय स्थल अपने नीचे के मैदानों से कहीं अधिक ठंडे होते हैं।"},
  {"id":"geo-climate-monsoon-55","question":"The IMD uses all of the following criteria when it declares the onset of the monsoon over Kerala EXCEPT:","options":["Rainfall at a set of 14 stations in Kerala and nearby for two consecutive days","The depth and strength of the westerly winds","Outgoing longwave radiation, a measure of cloudiness","A rise in the sea level at Kochi harbour"],"answer":3,"explanation":"Since 2006 the IMD checks rainfall at 14 listed stations (after 10 May), the westerly wind field and outgoing longwave radiation. Sea level at a harbour is not a criterion.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"केरल में मानसून के आगमन की घोषणा करते समय IMD निम्नलिखित सभी मानदंडों का उपयोग करता है, सिवाय:","optionsHi":["केरल और आसपास के 14 केंद्रों पर लगातार दो दिन वर्षा","पछुआ पवनों की गहराई और प्रबलता","बहिर्गामी दीर्घतरंग विकिरण (OLR), जो बादलों की मात्रा का मापक है","कोच्चि बंदरगाह पर समुद्र तल में वृद्धि"],"explanationHi":"2006 से IMD सूचीबद्ध 14 केंद्रों की वर्षा (10 मई के बाद), पछुआ पवन क्षेत्र और बहिर्गामी दीर्घतरंग विकिरण की जाँच करता है। किसी बंदरगाह पर समुद्र तल कोई मानदंड नहीं है।"},
  {"id":"geo-climate-monsoon-56","question":"After being deflected by the Himalaya, the Bay of Bengal branch of the monsoon moves over the Ganga plain:","options":["From north-west towards the south-east","From south-west towards the north-east","Westward, from the south-east","From north to south, off the Himalaya"],"answer":2,"explanation":"Turned by the Arakan hills and the Himalaya, the Bay branch flows westward up the Ganga plain, which is why its rain weakens from Kolkata towards Punjab. It does not blow from the south-west there.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"हिमालय द्वारा मोड़े जाने के बाद मानसून की बंगाल की खाड़ी शाखा गंगा के मैदान के ऊपर किस दिशा में बढ़ती है?","optionsHi":["उत्तर-पश्चिम से दक्षिण-पूर्व की ओर","दक्षिण-पश्चिम से उत्तर-पूर्व की ओर","पश्चिम की ओर, दक्षिण-पूर्व से","उत्तर से दक्षिण की ओर, हिमालय से नीचे"],"explanationHi":"अराकान पहाड़ियों और हिमालय द्वारा मोड़ी जाने पर खाड़ी शाखा गंगा के मैदान में पश्चिम की ओर बहती है, इसीलिए कोलकाता से पंजाब की ओर इसकी वर्षा घटती जाती है। वहाँ यह दक्षिण-पश्चिम से नहीं बहती।"},
  {"id":"geo-climate-monsoon-57","question":"The Bay of Bengal sees many more tropical cyclones than the Arabian Sea mainly because the Bay has:","options":["Colder surface waters, due to strong coastal upwelling","Warmer water and remnants of western Pacific lows","Stronger vertical wind shear throughout the year","A weaker Coriolis force, as it lies nearer the equator"],"answer":1,"explanation":"The Bay is warmer and is regularly seeded by the remnants of western Pacific systems crossing South-East Asia. The Arabian Sea is cooler, partly because of upwelling off Somalia and Oman.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"बंगाल की खाड़ी में अरब सागर की तुलना में कहीं अधिक उष्णकटिबंधीय चक्रवात आते हैं, मुख्यतः इसलिए कि खाड़ी में:","optionsHi":["प्रबल तटीय उत्स्रवण के कारण सतही जल अधिक ठंडा है","जल अधिक गर्म है और पश्चिमी प्रशांत के निम्न दाब के अवशेष आते हैं","पूरे वर्ष प्रबल ऊर्ध्वाधर पवन अपरूपण रहता है","कोरिओलिस बल कमजोर है, क्योंकि यह विषुवत रेखा के निकट है"],"explanationHi":"खाड़ी अधिक गर्म है और दक्षिण-पूर्व एशिया को पार करने वाले पश्चिमी प्रशांत तंत्रों के अवशेष नियमित रूप से उसमें पहुँचते हैं। अरब सागर आंशिक रूप से सोमालिया और ओमान के निकट उत्स्रवण के कारण अधिक ठंडा है।"},
  {"id":"geo-climate-monsoon-58","question":"For a station in the plains, the IMD does not consider a heat wave unless the station's maximum temperature reaches at least:","options":["35 °C","45 °C","47 °C","40 °C"],"answer":3,"explanation":"The IMD's thresholds are 40 °C for plains, 37 °C for coastal stations and 30 °C for hill stations, together with a departure of at least 4.5 °C from normal (or an actual 45 °C or more).","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"मैदानी क्षेत्र के किसी स्टेशन के लिए, IMD तब तक उष्ण लहर (heat wave) नहीं मानता जब तक स्टेशन का अधिकतम तापमान कम से कम कितना न हो जाए?","optionsHi":["35 °C","45 °C","47 °C","40 °C"],"explanationHi":"IMD की सीमाएँ मैदानों के लिए 40 °C, तटीय स्टेशनों के लिए 37 °C और पर्वतीय स्टेशनों के लिए 30 °C हैं, साथ ही सामान्य से कम से कम 4.5 °C का विचलन (या वास्तविक 45 °C या अधिक) भी होना चाहिए।"},
  {"id":"geo-climate-monsoon-59","question":"Before setting in over Kerala, the south-west monsoon normally first advances over:","options":["The Andaman Sea and Andaman Islands","The Gujarat coast in late May","The Lakshadweep islands in July","Sri Lanka's northern tip in early August"],"answer":0,"explanation":"The monsoon normally reaches the south Andaman Sea around 20–22 May, about ten days before its onset over Kerala around 1 June.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"केरल में प्रवेश करने से पहले, दक्षिण-पश्चिम मानसून सामान्यतः सबसे पहले कहाँ आगे बढ़ता है?","optionsHi":["अंडमान सागर और अंडमान द्वीप समूह","मई के अंत में गुजरात तट","जुलाई में लक्षद्वीप द्वीप समूह","अगस्त के आरंभ में श्रीलंका का उत्तरी छोर"],"explanationHi":"मानसून सामान्यतः लगभग 20–22 मई को दक्षिणी अंडमान सागर में पहुँचता है, जो केरल में लगभग 1 जून को उसके आगमन से करीब दस दिन पहले होता है।"},
  {"id":"geo-climate-monsoon-60","question":"Thiruvananthapuram gets rain in June–July and then a second rainfall peak in October–November. The second peak is due mainly to:","options":["Western disturbances crossing the peninsula","The north-east monsoon and Bay depressions","The Loo blowing in from the north-west","Convection over the heated Deccan interior"],"answer":1,"explanation":"The southern tip of Kerala gets the south-west monsoon first and then rain from the retreating/north-east monsoon and Bay of Bengal depressions in October–November, giving two maxima.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"तिरुवनंतपुरम में जून–जुलाई में वर्षा होती है और फिर अक्टूबर–नवंबर में वर्षा का दूसरा शिखर आता है। यह दूसरा शिखर मुख्यतः किसके कारण है?","optionsHi":["प्रायद्वीप को पार करने वाले पश्चिमी विक्षोभ","उत्तर-पूर्वी मानसून और खाड़ी के अवदाब","उत्तर-पश्चिम से बहने वाली लू","गर्म हुए दक्कन के आंतरिक भाग पर संवहन"],"explanationHi":"केरल के दक्षिणी छोर को पहले दक्षिण-पश्चिम मानसून से और फिर अक्टूबर–नवंबर में निवर्ती/उत्तर-पूर्वी मानसून तथा बंगाल की खाड़ी के अवदाबों से वर्षा मिलती है, जिससे दो उच्चतम बिंदु बनते हैं।"},
  {"id":"geo-climate-monsoon-61","question":"Cold waves in north India often follow the passage of a western disturbance because:","options":["Warm air from the Arabian Sea follows the disturbance","The disturbance raises surface pressure over the Bay of Bengal","Cold north-westerlies from snowy mountains flow in behind it","The monsoon trough moves over Delhi"],"answer":2,"explanation":"As a western disturbance moves east, cold, dry north-westerly winds flow in behind it, often over freshly snow-covered Himalaya, so temperatures plunge.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पश्चिमी विक्षोभ के गुजरने के बाद उत्तर भारत में प्रायः शीत लहर आती है, क्योंकि:","optionsHi":["अरब सागर की गर्म वायु विक्षोभ के पीछे-पीछे आती है","विक्षोभ से बंगाल की खाड़ी के ऊपर सतही दाब बढ़ जाता है","बर्फ से ढके पर्वतों की ठंडी उत्तर-पश्चिमी पवनें उसके पीछे बहकर आती हैं","मानसून द्रोणी दिल्ली के ऊपर आ जाती है"],"explanationHi":"जैसे ही पश्चिमी विक्षोभ पूर्व की ओर बढ़ता है, उसके पीछे ठंडी, शुष्क उत्तर-पश्चिमी पवनें बहने लगती हैं, प्रायः ताजा हिमाच्छादित हिमालय के ऊपर से, जिससे तापमान तेजी से गिर जाता है।"},
  {"id":"geo-climate-monsoon-62","question":"In hilly regions, orchards and tea gardens are usually planted on the slopes rather than on the valley floor mainly because:","options":["Valley floors always receive less rain than the slopes","Cold air drains into valleys at night, causing frost","Valley soils are always saline and waterlogged","Slopes are shielded from all monsoon winds"],"answer":1,"explanation":"On calm, clear nights dense cold air sinks into valleys, so the valley floor can be colder than the slopes above. That inversion brings frost that damages crops.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"पहाड़ी क्षेत्रों में बाग और चाय बागान प्रायः घाटी के तल के बजाय ढालों पर लगाए जाते हैं, मुख्यतः क्योंकि:","optionsHi":["घाटी के तल में ढालों की तुलना में हमेशा कम वर्षा होती है","रात में ठंडी वायु घाटियों में उतर आती है, जिससे पाला पड़ता है","घाटी की मिट्टी हमेशा लवणीय और जलमग्न रहती है","ढाल सभी मानसूनी पवनों से सुरक्षित रहते हैं"],"explanationHi":"शांत, साफ रातों में सघन ठंडी वायु घाटियों में नीचे बैठ जाती है, इसलिए घाटी का तल ऊपर के ढालों से अधिक ठंडा हो सकता है। यह व्युत्क्रमण पाला लाता है, जो फसलों को नुकसान पहुँचाता है।"},
  {"id":"geo-climate-monsoon-63","question":"All of the following give Tamil Nadu rain in October–December EXCEPT:","options":["The north-east monsoon winds after crossing the Bay of Bengal","Depressions and cyclones from the Bay of Bengal","Western disturbances","The retreating monsoon"],"answer":2,"explanation":"Western disturbances affect north and north-west India, mainly Jammu and Kashmir, Himachal, Punjab and Haryana. Tamil Nadu's winter rain comes from Bay of Bengal systems and the north-east monsoon.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित सभी अक्टूबर–दिसंबर में तमिलनाडु को वर्षा देते हैं, सिवाय:","optionsHi":["बंगाल की खाड़ी पार करने के बाद की उत्तर-पूर्वी मानसूनी पवनें","बंगाल की खाड़ी के अवदाब और चक्रवात","पश्चिमी विक्षोभ","निवर्ती मानसून"],"explanationHi":"पश्चिमी विक्षोभ उत्तर और उत्तर-पश्चिम भारत, मुख्यतः जम्मू-कश्मीर, हिमाचल, पंजाब और हरियाणा को प्रभावित करते हैं। तमिलनाडु की शीतकालीन वर्षा बंगाल की खाड़ी के तंत्रों और उत्तर-पूर्वी मानसून से होती है।"},
  {"id":"geo-climate-monsoon-64","question":"Very few severe cyclones form over the north Indian Ocean during July–August mainly because:","options":["Sea-surface temperatures fall below 15 °C across the region","Strong vertical wind shear from the upper easterly jet","The Coriolis force vanishes over the sea in summer","The ITCZ moves south of the equator in July"],"answer":1,"explanation":"During the peak monsoon, low-level westerlies sit beneath the upper easterly jet. This strong shear stops storms from building vertically, so monsoon depressions form instead of severe cyclones.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"जुलाई–अगस्त के दौरान उत्तरी हिंद महासागर में बहुत कम प्रचंड चक्रवात बनते हैं, मुख्यतः क्योंकि:","optionsHi":["पूरे क्षेत्र में समुद्र की सतह का तापमान 15 °C से नीचे गिर जाता है","ऊपरी पूर्वी जेट धारा से प्रबल ऊर्ध्वाधर पवन अपरूपण होता है","गर्मियों में समुद्र के ऊपर कोरिओलिस बल शून्य हो जाता है","जुलाई में ITCZ विषुवत रेखा के दक्षिण में चला जाता है"],"explanationHi":"चरम मानसून के दौरान निम्न-स्तरीय पछुआ पवनें ऊपरी पूर्वी जेट के नीचे रहती हैं। यह प्रबल अपरूपण तूफानों को ऊर्ध्वाधर रूप से बढ़ने से रोकता है, इसलिए प्रचंड चक्रवातों के बजाय मानसून अवदाब बनते हैं।"},
  {"id":"geo-climate-monsoon-65","question":"As per the IMD's revised normal dates, the monsoon normally reaches Mumbai around:","options":["11 June","1 June","1 July","15 July"],"answer":0,"explanation":"The revised normal onset date for Mumbai is 11 June (earlier 10 June). 1 June is Kerala, around the end of June is Delhi, and 8 July is the date for covering the whole country.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"IMD की संशोधित सामान्य तिथियों के अनुसार, मानसून सामान्यतः मुंबई में लगभग कब पहुँचता है?","optionsHi":["11 जून","1 जून","1 जुलाई","15 जुलाई"],"explanationHi":"मुंबई के लिए संशोधित सामान्य आगमन तिथि 11 जून है (पहले 10 जून)। 1 जून केरल की तिथि है, जून के अंत के आसपास दिल्ली की, और 8 जुलाई पूरे देश को ढकने की तिथि है।"},
  {"id":"geo-climate-monsoon-66","question":"According to the IMD's normal dates, the south-west monsoon withdraws completely from the country by about:","options":["1 September","15 October","30 November","31 December"],"answer":1,"explanation":"Withdrawal begins from west Rajasthan around 17 September and is normally complete by about 15 October. The post-monsoon (north-east monsoon) season then follows.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"IMD की सामान्य तिथियों के अनुसार, दक्षिण-पश्चिम मानसून देश से पूरी तरह लगभग कब तक लौट जाता है?","optionsHi":["1 सितंबर","15 अक्टूबर","30 नवंबर","31 दिसंबर"],"explanationHi":"वापसी लगभग 17 सितंबर को पश्चिमी राजस्थान से शुरू होती है और सामान्यतः लगभग 15 अक्टूबर तक पूरी हो जाती है। इसके बाद मानसून-पश्चात (उत्तर-पूर्वी मानसून) ऋतु आती है।"},
  {"id":"geo-climate-monsoon-67","question":"Shillong receives much less rain than Cherrapunji although the two are close to each other, because Shillong:","options":["Is at a much lower altitude than nearby Cherrapunji","Gets no south-west monsoon rain at all","Lies in the rain shadow of the southern Khasi ridge","Is affected mainly by western disturbances"],"answer":2,"explanation":"Moist winds dump most of their rain on the southern edge of the Khasi hills around Cherrapunji; Shillong, beyond the crest, gets only a fraction of it.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"शिलांग में चेरापूँजी की तुलना में बहुत कम वर्षा होती है, जबकि दोनों एक-दूसरे के निकट हैं, क्योंकि शिलांग:","optionsHi":["चेरापूँजी की तुलना में बहुत कम ऊँचाई पर है","दक्षिण-पश्चिम मानसून की वर्षा बिल्कुल प्राप्त नहीं करता","दक्षिणी खासी कटक की वृष्टि छाया में स्थित है","मुख्यतः पश्चिमी विक्षोभों से प्रभावित होता है"],"explanationHi":"नमी से लदी पवनें अपनी अधिकांश वर्षा खासी पहाड़ियों के दक्षिणी किनारे पर, चेरापूँजी के आसपास, कर देती हैं; शिखर के पार स्थित शिलांग को उसका केवल एक अंश ही मिलता है।"},
  {"id":"geo-climate-monsoon-68","question":"How many of the following statements about the IMD's classification of all-India south-west monsoon rainfall are correct? I. Rainfall between 90% and 96% of the Long Period Average (LPA) is 'normal'. II. Rainfall below 90% of the LPA is 'deficient'. III. Seasonal rainfall of 107% of the LPA is classed as 'excess'. IV. The LPA is an average of June–September rainfall over a 30-year period.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only II is correct. 90–96% of the LPA is 'below normal' while 96–104% is 'normal' (I wrong); only above 110% is 'excess' (III wrong); and the IMD's LPA is a 50-year average, not 30 years (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"IMD द्वारा अखिल भारतीय दक्षिण-पश्चिम मानसून वर्षा के वर्गीकरण के बारे में निम्नलिखित में से कितने कथन सही हैं? I. दीर्घावधि औसत (LPA) के 90% और 96% के बीच की वर्षा ‘सामान्य’ है। II. LPA के 90% से कम वर्षा ‘अपर्याप्त’ (deficient) है। III. LPA की 107% मौसमी वर्षा ‘अधिक’ (excess) श्रेणी में आती है। IV. LPA जून–सितंबर की वर्षा का 30 वर्षों की अवधि का औसत है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल II सही है। LPA का 90–96% ‘सामान्य से कम’ है, जबकि 96–104% ‘सामान्य’ है (I गलत); केवल 110% से अधिक ही ‘अधिक’ है (III गलत); और IMD का LPA 50 वर्षों का औसत है, 30 वर्षों का नहीं (IV गलत)।"},
  {"id":"geo-climate-monsoon-69","question":"Match the air current or pressure system with its description. A. Somali jet  B. Tropical easterly jet  C. Subtropical westerly jet  D. Mascarene High; 1. Upper-level wind over the peninsula at about 14°N in summer  2. Low-level cross-equatorial flow off the East African coast  3. High-pressure cell in the southern Indian Ocean east of Madagascar  4. Upper-level wind that lies south of the Himalaya in winter and steers western disturbances","options":["A-1, B-2, C-4, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-3, B-1, C-4, D-2"],"answer":1,"explanation":"The Somali (Findlater) jet is the low-level flow off East Africa, the tropical easterly jet blows over the peninsula at about 14°N in summer, the subtropical westerly jet sits south of the Himalaya in winter and steers western disturbances, and the Mascarene High lies east of Madagascar. Swapping the two jets is the usual trap.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"वायुधारा या दाब तंत्र को उसके विवरण से सुमेलित कीजिए। A. सोमाली जेट  B. उष्णकटिबंधीय पूर्वी जेट  C. उपोष्ण पश्चिमी जेट  D. मस्करीन उच्च दाब; 1. ग्रीष्म में लगभग 14°N पर प्रायद्वीप के ऊपर ऊपरी स्तर की पवन  2. पूर्वी अफ्रीकी तट के पास निचले स्तर की भूमध्यरेखा-पार वायुधारा  3. मेडागास्कर के पूर्व में दक्षिणी हिंद महासागर का उच्च दाब क्षेत्र  4. ऊपरी स्तर की पवन जो सर्दियों में हिमालय के दक्षिण में रहती है और पश्चिमी विक्षोभों को दिशा देती है","optionsHi":["A-1, B-2, C-4, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-3, B-1, C-4, D-2"],"explanationHi":"सोमाली (फाइंडलेटर) जेट पूर्वी अफ्रीका के पास निचले स्तर की धारा है, उष्णकटिबंधीय पूर्वी जेट ग्रीष्म में लगभग 14°N पर प्रायद्वीप के ऊपर बहती है, उपोष्ण पश्चिमी जेट सर्दियों में हिमालय के दक्षिण में रहकर पश्चिमी विक्षोभों को दिशा देती है, और मस्करीन उच्च दाब मेडागास्कर के पूर्व में है। दोनों जेटों को आपस में बदल देना सामान्य भूल है।"},
  {"id":"geo-climate-monsoon-70","question":"How many of the following statements are correct? I. The Madden–Julian Oscillation (MJO) is an eastward-moving belt of enhanced cloud and rain along the tropics. II. An active MJO phase over the Indian Ocean tends to strengthen monsoon rainfall over India. III. The Tibetan plateau acts as a cold source in summer and weakens the monsoon circulation. IV. The IMD counts a day as a 'rainy day' when it records 2.5 mm of rain or more.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. In summer the Tibetan plateau is a strong elevated heat source that builds an upper-level high and helps the easterly jet and the monsoon, so III is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कितने कथन सही हैं? I. मैडेन–जूलियन दोलन (MJO) उष्णकटिबंध के साथ पूर्व की ओर बढ़ने वाली बादलों और वर्षा की प्रबलित पट्टी है। II. हिंद महासागर के ऊपर MJO का सक्रिय चरण भारत में मानसूनी वर्षा को प्रबल करता है। III. तिब्बत का पठार गर्मियों में शीत स्रोत के रूप में कार्य करता है और मानसून परिसंचरण को कमजोर करता है। IV. IMD किसी दिन को ‘वर्षा दिवस’ तब गिनता है जब 2.5 मिमी या उससे अधिक वर्षा दर्ज हो।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। गर्मियों में तिब्बत का पठार एक प्रबल उन्नत ऊष्मा स्रोत है, जो ऊपरी स्तर का उच्च दाब बनाता है और पूर्वी जेट तथा मानसून की सहायता करता है, अतः III गलत है।"},
  {"id":"geo-climate-monsoon-71","question":"Match the term with its description. A. Elephanta  B. Cloudburst  C. Monsoon break  D. Radiation fog; 1. A spell of days in July–August when rain largely stops over the plains and central India  2. Fog formed on clear, calm winter nights as the ground loses heat  3. Strong winds on the Malabar coast that mark the end of the south-west monsoon  4. About 100 mm or more of rain in an hour over a small area","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"],"answer":0,"explanation":"Elephanta winds blow on the Malabar coast in September–October; the IMD calls 100 mm/hour or more over about 20–30 km² a cloudburst; breaks are dry spells within the monsoon; radiation fog blankets the Indo-Gangetic plain on calm winter nights.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"शब्द का उसके विवरण से मिलान कीजिए। A. एलिफेंटा  B. बादल फटना (क्लाउडबर्स्ट)  C. मानसून विच्छेद  D. विकिरण कोहरा; 1. जुलाई–अगस्त में कुछ दिनों की वह अवधि जब मैदानों और मध्य भारत में वर्षा लगभग रुक जाती है  2. साफ, शांत सर्दी की रातों में धरातल के ऊष्मा खोने पर बनने वाला कोहरा  3. मालाबार तट की प्रबल पवनें, जो दक्षिण-पश्चिम मानसून की समाप्ति का संकेत देती हैं  4. किसी छोटे क्षेत्र में एक घंटे में लगभग 100 मिमी या अधिक वर्षा","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"],"explanationHi":"एलिफेंटा पवनें सितंबर–अक्टूबर में मालाबार तट पर चलती हैं; IMD लगभग 20–30 वर्ग किमी में 100 मिमी/घंटा या अधिक वर्षा को बादल फटना कहता है; विच्छेद मानसून के भीतर शुष्क अवधियाँ हैं; विकिरण कोहरा शांत सर्दी की रातों में सिंधु-गंगा के मैदान को ढक लेता है।"},
  {"id":"geo-climate-monsoon-72","question":"Assertion (A): Western Rajasthan receives scanty rainfall. Reason (R): The year-to-year variability of rainfall in western Rajasthan is very high.","options":["Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A"],"answer":3,"explanation":"Both are true, but high variability is a result of low, unreliable rain, not its cause. The rain is scanty because the Aravallis run parallel to the Arabian Sea branch and the Bay branch arrives exhausted.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): पश्चिमी राजस्थान में अल्प वर्षा होती है। कारण (R): पश्चिमी राजस्थान में वर्षा की वार्षिक परिवर्तिता बहुत अधिक है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है"],"explanationHi":"दोनों सही हैं, परंतु उच्च परिवर्तिता कम और अविश्वसनीय वर्षा का परिणाम है, कारण नहीं। वर्षा इसलिए अल्प है क्योंकि अरावली अरब सागर शाखा के समानांतर है और खाड़ी शाखा यहाँ तक पहुँचते-पहुँचते नमी खो चुकी होती है।"},
  {"id":"geo-climate-monsoon-73","question":"Arrange these places in decreasing order of average annual rainfall: 1. Delhi  2. Mumbai  3. Leh  4. Kolkata","options":["2-1-4-3","4-2-1-3","2-4-1-3","2-4-3-1"],"answer":2,"explanation":"Mumbai gets roughly 220–250 cm, Kolkata about 160–180 cm, Delhi about 75 cm and Leh only about 10 cm. So 2-4-1-3.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन स्थानों को औसत वार्षिक वर्षा के घटते क्रम में व्यवस्थित कीजिए: 1. दिल्ली  2. मुंबई  3. लेह  4. कोलकाता","optionsHi":["2-1-4-3","4-2-1-3","2-4-1-3","2-4-3-1"],"explanationHi":"मुंबई में लगभग 220–250 सेमी, कोलकाता में लगभग 160–180 सेमी, दिल्ली में लगभग 75 सेमी और लेह में केवल लगभग 10 सेमी वर्षा होती है। अतः क्रम 2-4-1-3 है।"},
  {"id":"geo-climate-monsoon-74","question":"Arrange these weather events in the order they normally occur in a calendar year at Delhi: 1. Onset of the south-west monsoon  2. Peak of the Loo  3. Western disturbance rain that helps the rabi crop  4. October heat","options":["3-2-1-4","2-3-1-4","3-1-2-4","3-2-4-1"],"answer":0,"explanation":"Western disturbances bring winter rain in January–February, the Loo peaks in May–early June, the monsoon reaches Delhi around the end of June, and October heat follows its withdrawal.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"दिल्ली में एक कैलेंडर वर्ष में इन मौसमी घटनाओं के सामान्यतः घटित होने का क्रम व्यवस्थित कीजिए: 1. दक्षिण-पश्चिम मानसून का आगमन  2. लू का चरम  3. पश्चिमी विक्षोभ की वर्षा, जो रबी फसल के लिए लाभदायक है  4. अक्टूबर की गर्मी","optionsHi":["3-2-1-4","2-3-1-4","3-1-2-4","3-2-4-1"],"explanationHi":"पश्चिमी विक्षोभ जनवरी–फरवरी में शीतकालीन वर्षा लाते हैं, लू मई से जून के आरंभ में चरम पर होती है, मानसून दिल्ली में जून के अंत के आसपास पहुँचता है, और उसकी वापसी के बाद अक्टूबर की गर्मी आती है।"},
  {"id":"geo-climate-monsoon-75","question":"Which of the following statements about western disturbances is NOT correct?","options":["They originate over the Mediterranean and West Asian region","They move eastward towards India","They are tropical cyclones that form over the Bay of Bengal","They bring snowfall to the western Himalaya"],"answer":2,"explanation":"Western disturbances are extra-tropical low-pressure systems that travel east from the Mediterranean region, bringing winter rain and snow to north-west India. They are not tropical cyclones.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पश्चिमी विक्षोभों के बारे में निम्नलिखित में से कौन-सा कथन सही नहीं है?","optionsHi":["इनका उद्भव भूमध्यसागर और पश्चिम एशिया क्षेत्र के ऊपर होता है","ये भारत की ओर पूर्व दिशा में बढ़ते हैं","ये बंगाल की खाड़ी के ऊपर बनने वाले उष्णकटिबंधीय चक्रवात हैं","ये पश्चिमी हिमालय में हिमपात लाते हैं"],"explanationHi":"पश्चिमी विक्षोभ बहिरुष्णकटिबंधीय निम्न दाब तंत्र हैं जो भूमध्यसागरीय क्षेत्र से पूर्व की ओर चलते हैं और उत्तर-पश्चिम भारत में शीतकालीन वर्षा और हिमपात लाते हैं। ये उष्णकटिबंधीय चक्रवात नहीं हैं।"},
  {"id":"geo-climate-monsoon-76","question":"How many of the following statements help explain why the Thar region receives little rain? I. The Aravallis run parallel to the Arabian Sea branch and do not force it to rise. II. The Bay of Bengal branch has shed most of its moisture by the time it reaches western Rajasthan. III. Hot, dry, subsiding air above the region discourages cloud formation. IV. The region lies in the rain shadow of the Western Ghats.","options":["Only one","Only two","All four","Only three"],"answer":3,"explanation":"I, II and III are valid. The Western Ghats shadow the Deccan interior, not Rajasthan, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कितने कथन यह समझाने में सहायक हैं कि थार क्षेत्र में कम वर्षा क्यों होती है? I. अरावली अरब सागर शाखा के समानांतर है और उसे ऊपर उठने के लिए बाध्य नहीं करती। II. बंगाल की खाड़ी शाखा पश्चिमी राजस्थान पहुँचने तक अपनी अधिकांश नमी खो चुकी होती है। III. क्षेत्र के ऊपर गर्म, शुष्क, अवतलित वायु बादल बनने को हतोत्साहित करती है। IV. यह क्षेत्र पश्चिमी घाट की वृष्टि छाया में स्थित है।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"I, II और III मान्य हैं। पश्चिमी घाट की वृष्टि छाया दक्कन के आंतरिक भाग पर पड़ती है, राजस्थान पर नहीं, अतः IV गलत है।"},
  {"id":"geo-climate-monsoon-77","question":"Which of the following pairs of place and climatic feature is NOT correct?","options":["Leh — cold arid climate","Mumbai — most rain falls in June–September","Thiruvananthapuram — rain from both the south-west and the retreating monsoon","Amritsar — very small annual range of temperature"],"answer":3,"explanation":"Amritsar, far from the sea, has a continental climate with a large annual range: cold winters and summers above 40 °C. The other pairs are correct.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"स्थान और जलवायवीय विशेषता के निम्नलिखित में से कौन-सा युग्म सही नहीं है?","optionsHi":["लेह — शीत शुष्क जलवायु","मुंबई — अधिकांश वर्षा जून–सितंबर में","तिरुवनंतपुरम — दक्षिण-पश्चिम और निवर्ती दोनों मानसूनों से वर्षा","अमृतसर — तापमान का बहुत छोटा वार्षिक परिसर"],"explanationHi":"समुद्र से दूर स्थित अमृतसर में महाद्वीपीय जलवायु है, जिसमें वार्षिक परिसर बड़ा है: ठंडी सर्दियाँ और 40 °C से अधिक की गर्मियाँ। शेष युग्म सही हैं।"},
  {"id":"geo-climate-monsoon-78","question":"How many of the following statements about naming tropical cyclones in the north Indian Ocean are correct? I. Names are assigned by RSMC Tokyo from a list prepared by member countries of the WMO/ESCAP Panel on Tropical Cyclones. II. The panel now has 8 member countries. III. A name once used is not used again. IV. Names alternate between male and female, as in the Atlantic.","options":["Only three","Only two","Only one","All four"],"answer":2,"explanation":"Only III is correct. North Indian Ocean names are assigned by RSMC New Delhi (I wrong); the panel has 13 members, up from the original 8 (II wrong); and the list does not alternate male and female names (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"उत्तरी हिंद महासागर में उष्णकटिबंधीय चक्रवातों के नामकरण के बारे में निम्नलिखित में से कितने कथन सही हैं? I. नाम RSMC टोक्यो द्वारा, WMO/ESCAP उष्णकटिबंधीय चक्रवात पैनल के सदस्य देशों की तैयार की गई सूची से दिए जाते हैं। II. पैनल में अब 8 सदस्य देश हैं। III. एक बार प्रयुक्त नाम दोबारा प्रयोग नहीं किया जाता। IV. अटलांटिक की तरह नाम पुरुष और महिला के बीच बारी-बारी से आते हैं।","optionsHi":["केवल तीन","केवल दो","केवल एक","सभी चार"],"explanationHi":"केवल III सही है। उत्तरी हिंद महासागर के नाम RSMC नई दिल्ली द्वारा दिए जाते हैं (I गलत); पैनल में मूल 8 से बढ़कर 13 सदस्य हैं (II गलत); और सूची में नाम पुरुष-महिला के बीच बारी-बारी से नहीं आते (IV गलत)।"},
  {"id":"geo-climate-monsoon-79","question":"Match the cyclone with the state where it made landfall. A. Fani (2019)  B. Amphan (2020)  C. Hudhud (2014)  D. Biparjoy (2023); 1. Gujarat  2. Andhra Pradesh  3. West Bengal  4. Odisha","options":["A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Fani hit Puri (Odisha), Amphan crossed near the Sundarbans (West Bengal), Hudhud struck Visakhapatnam (Andhra Pradesh) and Biparjoy, an Arabian Sea storm, hit Kutch (Gujarat).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"चक्रवात का उस राज्य से मिलान कीजिए जहाँ उसने स्थलगमन (landfall) किया। A. फेनी (2019)  B. अम्फान (2020)  C. हुदहुद (2014)  D. बिपरजॉय (2023); 1. गुजरात  2. आंध्र प्रदेश  3. पश्चिम बंगाल  4. ओडिशा","optionsHi":["A-4, B-2, C-3, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"explanationHi":"फेनी पुरी (ओडिशा) से टकराया, अम्फान सुंदरबन (पश्चिम बंगाल) के निकट पहुँचा, हुदहुद विशाखापत्तनम (आंध्र प्रदेश) से टकराया और अरब सागर का तूफान बिपरजॉय कच्छ (गुजरात) से टकराया।"},
  {"id":"geo-climate-monsoon-80","question":"Arrange these stations in increasing order of annual range of temperature: 1. Delhi  2. Mumbai  3. Kolkata  4. Thiruvananthapuram","options":["4-3-2-1","4-2-3-1","2-4-3-1","4-2-1-3"],"answer":1,"explanation":"Thiruvananthapuram's range is only about 3 °C, Mumbai about 6 °C, Kolkata about 11 °C and Delhi nearly 19 °C. The range grows with latitude and distance from the sea.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इन स्टेशनों को तापमान के वार्षिक परिसर के बढ़ते क्रम में व्यवस्थित कीजिए: 1. दिल्ली  2. मुंबई  3. कोलकाता  4. तिरुवनंतपुरम","optionsHi":["4-3-2-1","4-2-3-1","2-4-3-1","4-2-1-3"],"explanationHi":"तिरुवनंतपुरम का परिसर केवल लगभग 3 °C, मुंबई का लगभग 6 °C, कोलकाता का लगभग 11 °C और दिल्ली का लगभग 19 °C है। परिसर अक्षांश और समुद्र से दूरी के साथ बढ़ता है।"},
  {"id":"geo-climate-monsoon-81","question":"Storm surges are exceptionally high along the coasts of West Bengal and Bangladesh mainly because:","options":["The coast there is rocky and steep, reflecting waves back","Cyclones there rotate clockwise and push water ashore","The shallow, funnel-shaped head of the Bay piles up water","The Arabian Sea pushes water eastward across the peninsula"],"answer":2,"explanation":"Wind-driven water cannot spread sideways in the narrowing, shallow head of the Bay, so it piles up into very high surges. Northern-hemisphere cyclones rotate anticlockwise, not clockwise.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"पश्चिम बंगाल और बांग्लादेश के तटों पर तूफानी लहरें असाधारण रूप से ऊँची होती हैं, मुख्यतः क्योंकि:","optionsHi":["वहाँ का तट चट्टानी और खड़ी ढाल वाला है, जो लहरों को वापस लौटा देता है","वहाँ चक्रवात दक्षिणावर्त घूमते हैं और जल को तट की ओर धकेलते हैं","खाड़ी का उथला, कीप के आकार का शीर्ष जल को जमा कर देता है","अरब सागर जल को प्रायद्वीप के आर-पार पूर्व की ओर धकेलता है"],"explanationHi":"पवन से चलने वाला जल खाड़ी के संकरे, उथले शीर्ष में बगल की ओर फैल नहीं पाता, इसलिए वह जमा होकर बहुत ऊँची तूफानी लहरें बनाता है। उत्तरी गोलार्ध के चक्रवात वामावर्त घूमते हैं, दक्षिणावर्त नहीं।"},
  {"id":"geo-climate-monsoon-82","question":"How many of the following statements about the factors controlling India's climate are correct? I. The Tropic of Cancer passes through the middle of India, dividing it into roughly equal halves. II. The Himalaya shields India from cold winds from Central Asia. III. Places far from the sea have a larger range of temperature. IV. Temperature rises with altitude, so hill stations are warmer in summer.","options":["Only two","Only three","Only one","All four"],"answer":1,"explanation":"I, II and III are correct. Temperature falls with height (about 6.5 °C per km), which is why hill stations are cooler, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"भारत की जलवायु को नियंत्रित करने वाले कारकों के बारे में निम्नलिखित में से कितने कथन सही हैं? I. कर्क रेखा भारत के मध्य से गुजरती है और उसे लगभग बराबर दो भागों में बाँटती है। II. हिमालय भारत को मध्य एशिया की ठंडी पवनों से बचाता है। III. समुद्र से दूर स्थित स्थानों में तापमान का परिसर अधिक होता है। IV. ऊँचाई के साथ तापमान बढ़ता है, इसलिए पर्वतीय स्थल गर्मियों में अधिक गर्म होते हैं।","optionsHi":["केवल दो","केवल तीन","केवल एक","सभी चार"],"explanationHi":"I, II और III सही हैं। ऊँचाई के साथ तापमान घटता है (लगभग 6.5 °C प्रति किमी), इसीलिए पर्वतीय स्थल अधिक ठंडे होते हैं, अतः IV गलत है।"},
  {"id":"geo-climate-monsoon-83","question":"Which of the following is NOT a condition for a tropical cyclone to form?","options":["Sea-surface temperature above about 27 °C","Enough Coriolis force to start rotation","Low vertical wind shear","A location right on the equator"],"answer":3,"explanation":"The Coriolis force is almost zero on the equator, so cyclones rarely form within about 5° of it. Warm water and low shear are both needed.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन-सी उष्णकटिबंधीय चक्रवात के बनने की शर्त नहीं है?","optionsHi":["समुद्री सतह का तापमान लगभग 27 °C से अधिक","घूर्णन आरंभ करने के लिए पर्याप्त कोरिओलिस बल","निम्न ऊर्ध्वाधर पवन अपरूपण","ठीक विषुवत रेखा पर स्थित होना"],"explanationHi":"विषुवत रेखा पर कोरिओलिस बल लगभग शून्य होता है, इसलिए उसके लगभग 5° के भीतर चक्रवात बहुत कम बनते हैं। गर्म जल और निम्न अपरूपण दोनों आवश्यक हैं।"},
  {"id":"geo-climate-monsoon-84","question":"Which pair of monsoon branch and the area it rains on is NOT correct?","options":["Arabian Sea branch — Konkan coast in July","Bay of Bengal branch — Meghalaya in July","Bay of Bengal branch — the Ganga plain in July","Arabian Sea branch — Coromandel coast in July"],"answer":3,"explanation":"The Coromandel coast lies in the rain shadow in July and gets little rain from the Arabian Sea branch; its main rain comes in October–December. The other pairs are correct.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"मानसून शाखा और उसके द्वारा वर्षा किए जाने वाले क्षेत्र का कौन-सा युग्म सही नहीं है?","optionsHi":["अरब सागर शाखा — जुलाई में कोंकण तट","बंगाल की खाड़ी शाखा — जुलाई में मेघालय","बंगाल की खाड़ी शाखा — जुलाई में गंगा का मैदान","अरब सागर शाखा — जुलाई में कोरोमंडल तट"],"explanationHi":"कोरोमंडल तट जुलाई में वृष्टि छाया में रहता है और अरब सागर शाखा से बहुत कम वर्षा पाता है; उसकी मुख्य वर्षा अक्टूबर–दिसंबर में होती है। शेष युग्म सही हैं।"},
  {"id":"geo-climate-monsoon-85","question":"Assertion (A): Monsoon depressions bring much of the rainfall of the Ganga plain. Reason (R): Monsoon depressions form over the head of the Bay of Bengal and move north-westward along the monsoon trough.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Depressions born over the north Bay travel west-north-west along the trough over Odisha, Madhya Pradesh and the Ganga plain, dropping heavy rain on their way. So R explains A.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): मानसून अवदाब गंगा के मैदान की अधिकांश वर्षा लाते हैं। कारण (R): मानसून अवदाब बंगाल की खाड़ी के शीर्ष पर बनते हैं और मानसून द्रोणी के साथ उत्तर-पश्चिम की ओर बढ़ते हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"उत्तरी खाड़ी के ऊपर बने अवदाब द्रोणी के साथ पश्चिम-उत्तर-पश्चिम दिशा में ओडिशा, मध्य प्रदेश और गंगा के मैदान के ऊपर से गुजरते हैं और रास्ते में भारी वर्षा करते हैं। अतः R, A की व्याख्या करता है।"},
  {"id":"geo-climate-monsoon-86","question":"A weather station uses which instrument to measure the relative humidity of the air?","options":["Barometer","Hygrometer","Anemometer","Rain gauge"],"answer":1,"explanation":"A hygrometer (for example the wet-and-dry-bulb psychrometer) measures humidity. A barometer measures pressure and an anemometer wind speed.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"मौसम केंद्र वायु की सापेक्ष आर्द्रता मापने के लिए किस उपकरण का उपयोग करता है?","optionsHi":["वायुदाबमापी (बैरोमीटर)","आर्द्रतामापी (हाइग्रोमीटर)","पवनवेगमापी (एनीमोमीटर)","वर्षामापी (रेन गेज)"],"explanationHi":"आर्द्रतामापी (उदाहरणार्थ, गीले और सूखे बल्ब वाला साइक्रोमीटर) आर्द्रता मापता है। वायुदाबमापी दाब और पवनवेगमापी पवन की गति मापता है।"},
  {"id":"geo-climate-monsoon-87","question":"Almost all clouds, rain, storms and other weather events occur in which layer of the atmosphere?","options":["Stratosphere","Mesosphere","Troposphere","Thermosphere"],"answer":2,"explanation":"The troposphere, the lowest layer, holds nearly all the water vapour and dust, so weather happens there. The stratosphere above is stable and nearly cloud-free, which suits jet aircraft.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"लगभग सभी बादल, वर्षा, तूफान और अन्य मौसमी घटनाएँ वायुमंडल की किस परत में होती हैं?","optionsHi":["समतापमंडल","मध्यमंडल","क्षोभमंडल","तापमंडल"],"explanationHi":"सबसे निचली परत क्षोभमंडल में लगभग सारी जलवाष्प और धूल होती है, इसीलिए मौसम वहीं बनता है। ऊपर का समतापमंडल स्थिर और लगभग बादलरहित है, जो जेट विमानों के लिए उपयुक्त है।"},
  {"id":"geo-climate-monsoon-88","question":"The troposphere is thickest over the:","options":["Poles","Tropic of Cancer only in winter","Mid-latitudes","Equator"],"answer":3,"explanation":"Strong heating and convection push the tropopause to about 16–18 km over the equator, against roughly 8 km over the poles.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"क्षोभमंडल की मोटाई सबसे अधिक कहाँ होती है?","optionsHi":["ध्रुवों पर","केवल सर्दियों में कर्क रेखा पर","मध्य अक्षांशों में","विषुवत रेखा पर"],"explanationHi":"प्रबल तापन और संवहन विषुवत रेखा के ऊपर क्षोभसीमा को लगभग 16–18 किमी तक धकेल देते हैं, जबकि ध्रुवों पर यह लगभग 8 किमी है।"},
  {"id":"geo-climate-monsoon-89","question":"Dew forms on grass on a clear night when:","options":["The grass cools below the dew point of the air","Warm, moist air rises from the ground at night","The relative humidity of the air falls sharply","Wind speed increases after midnight and mixes the air"],"answer":0,"explanation":"Clear skies let the ground lose heat; once a surface is colder than the dew point, water vapour condenses on it. Wind and cloud cover hinder dew by keeping the surface warmer.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"साफ रात में घास पर ओस तब बनती है जब:","optionsHi":["घास वायु के ओसांक से नीचे ठंडी हो जाती है","गर्म, नम वायु रात में भूमि से ऊपर उठती है","वायु की सापेक्ष आर्द्रता तेजी से गिर जाती है","आधी रात के बाद पवन की गति बढ़ जाती है और वायु मिल जाती है"],"explanationHi":"साफ आसमान में धरातल ऊष्मा खो देता है; जब कोई सतह ओसांक से अधिक ठंडी हो जाती है, तो उस पर जलवाष्प संघनित हो जाती है। पवन और बादलों का आवरण सतह को गर्म रखकर ओस बनने में बाधा डालते हैं।"},
  {"id":"geo-climate-monsoon-90","question":"Which of these surfaces reflects the largest share of the sunlight falling on it (has the highest albedo)?","options":["Dark asphalt road","Dense evergreen forest","Fresh snow","Open ocean water"],"answer":2,"explanation":"Fresh snow reflects roughly 80–90% of incoming sunlight. Forests, open water and asphalt absorb most of it, which is why melting snow cover speeds up warming.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"इनमें से कौन-सी सतह अपने ऊपर पड़ने वाले सूर्य के प्रकाश का सबसे अधिक भाग परावर्तित करती है (जिसका एल्बिडो सबसे अधिक है)?","optionsHi":["काली डामर की सड़क","घना सदाबहार वन","ताजा हिम","खुला समुद्री जल"],"explanationHi":"ताजा हिम आने वाले सूर्य के प्रकाश का लगभग 80–90% परावर्तित करता है। वन, खुला जल और डामर उसका अधिकांश भाग अवशोषित कर लेते हैं, इसीलिए हिमावरण के पिघलने से तापन की गति बढ़ जाती है।"},
  {"id":"geo-climate-monsoon-91","question":"On a sunny afternoon at a coastal town, a breeze blows from the sea towards the land because:","options":["The sea heats faster than the land during the day","The land heats faster, so pressure over it drops","The Coriolis force is strongest in the afternoon","Cold ocean currents push the cooler air inland"],"answer":1,"explanation":"Land has a lower specific heat than water, so it warms faster by day; air over it rises and cooler air from the sea moves in. At night the pattern reverses into a land breeze.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"किसी तटीय शहर में धूप वाली दोपहर में समुद्र से स्थल की ओर समीर क्यों बहती है?","optionsHi":["दिन में समुद्र स्थल की तुलना में तेजी से गर्म होता है","स्थल तेजी से गर्म होता है, इसलिए उसके ऊपर दाब घट जाता है","कोरिओलिस बल दोपहर में सबसे प्रबल होता है","ठंडी महासागरीय धाराएँ ठंडी वायु को भीतर की ओर धकेलती हैं"],"explanationHi":"स्थल की विशिष्ट ऊष्मा जल से कम होती है, इसलिए वह दिन में तेजी से गर्म होता है; उसके ऊपर की वायु ऊपर उठती है और समुद्र से ठंडी वायु आ जाती है। रात में यह प्रतिरूप उलटकर स्थल समीर बन जाता है।"},
  {"id":"geo-climate-monsoon-92","question":"If a parcel of air is warmed without any moisture being added to it, what happens to its humidity?","options":["Both absolute and relative humidity rise together","Absolute humidity falls and relative humidity rises","Relative humidity falls; absolute stays the same","Both stay the same, as no vapour is added"],"answer":2,"explanation":"The actual amount of vapour (absolute humidity) is unchanged, but warmer air can hold more vapour, so relative humidity drops. That is why relative humidity is usually lowest in the afternoon.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"यदि किसी वायु पुंज को उसमें नमी मिलाए बिना गर्म किया जाए, तो उसकी आर्द्रता का क्या होगा?","optionsHi":["निरपेक्ष और सापेक्ष आर्द्रता दोनों साथ-साथ बढ़ती हैं","निरपेक्ष आर्द्रता घटती है और सापेक्ष आर्द्रता बढ़ती है","सापेक्ष आर्द्रता घटती है; निरपेक्ष वही रहती है","दोनों वही रहती हैं, क्योंकि कोई वाष्प नहीं जोड़ी गई"],"explanationHi":"वाष्प की वास्तविक मात्रा (निरपेक्ष आर्द्रता) अपरिवर्तित रहती है, परंतु गर्म वायु अधिक वाष्प धारण कर सकती है, इसलिए सापेक्ष आर्द्रता घट जाती है। इसीलिए सापेक्ष आर्द्रता प्रायः दोपहर में सबसे कम होती है।"},
  {"id":"geo-climate-monsoon-93","question":"Which of these districts of Maharashtra lies in the rain shadow of the Western Ghats and is drought-prone?","options":["Ratnagiri","Sindhudurg","Raigad","Solapur"],"answer":3,"explanation":"Solapur, on the Deccan plateau east of the Ghats, gets only about 50–75 cm of rain. Ratnagiri, Sindhudurg and Raigad are Konkan districts on the windward side and get well over 250 cm.","difficulty":"hard","source":"State PSC · UPSC Prelims","questionHi":"महाराष्ट्र का इनमें से कौन-सा जिला पश्चिमी घाट की वृष्टि छाया में स्थित है और सूखा-प्रवण है?","optionsHi":["रत्नागिरि","सिंधुदुर्ग","रायगढ़","सोलापुर"],"explanationHi":"घाट के पूर्व में दक्कन के पठार पर स्थित सोलापुर में केवल लगभग 50–75 सेमी वर्षा होती है। रत्नागिरि, सिंधुदुर्ग और रायगढ़ पवनाभिमुख ढाल पर स्थित कोंकण के जिले हैं और यहाँ 250 सेमी से कहीं अधिक वर्षा होती है।"},
  {"id":"geo-climate-monsoon-94","question":"Temperature rises with height in the stratosphere mainly because:","options":["Ozone absorbs the sun's ultraviolet radiation there","Heat from the earth's surface is trapped by high clouds","The air is denser there than in the troposphere","Jet streams generate friction that heats the air"],"answer":0,"explanation":"The ozone layer absorbs solar ultraviolet radiation and warms the upper stratosphere. In the troposphere, by contrast, air is heated from the ground, so temperature falls with height.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"समतापमंडल में ऊँचाई के साथ तापमान मुख्यतः क्यों बढ़ता है?","optionsHi":["वहाँ ओजोन सूर्य की पराबैंगनी विकिरण को अवशोषित करती है","ऊँचे बादलों द्वारा पृथ्वी की सतह की ऊष्मा रोक ली जाती है","वहाँ वायु क्षोभमंडल की तुलना में सघन होती है","जेट धाराएँ घर्षण उत्पन्न करती हैं, जो वायु को गर्म करता है"],"explanationHi":"ओजोन परत सौर पराबैंगनी विकिरण को अवशोषित करके ऊपरी समतापमंडल को गर्म करती है। इसके विपरीत, क्षोभमंडल में वायु धरातल से गर्म होती है, इसलिए ऊँचाई के साथ तापमान घटता है।"},
  {"id":"geo-climate-monsoon-95","question":"The “horse latitudes”, known for calm winds and dry sinking air, correspond to the:","options":["Equatorial low-pressure belt (doldrums)","Subtropical high-pressure belts near 30°–35° N and S","Subpolar low-pressure belts at about 60° N and 60° S","Polar high-pressure belts near the poles"],"answer":1,"explanation":"Air that rose at the equator sinks around 30°–35° latitude, forming the subtropical highs with light winds; most hot deserts lie here. The calm equatorial belt is the doldrums.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"शांत पवनों और शुष्क अवतलित वायु के लिए प्रसिद्ध “अश्व अक्षांश” (horse latitudes) किससे संबंधित हैं?","optionsHi":["विषुवतीय निम्न दाब पेटी (शांत कटिबंध/डोलड्रम)","उत्तरी और दक्षिणी 30°–35° के निकट उपोष्णकटिबंधीय उच्च दाब पेटियाँ","लगभग 60° उत्तर और 60° दक्षिण की उपध्रुवीय निम्न दाब पेटियाँ","ध्रुवों के निकट की ध्रुवीय उच्च दाब पेटियाँ"],"explanationHi":"विषुवत रेखा पर ऊपर उठी वायु लगभग 30°–35° अक्षांश पर नीचे उतरती है और हल्की पवनों वाले उपोष्णकटिबंधीय उच्च दाब बनाती है; अधिकांश उष्ण मरुस्थल यहीं स्थित हैं। शांत विषुवतीय पेटी डोलड्रम है।"},
  {"id":"geo-climate-monsoon-96","question":"A wet-bulb temperature of about 35 °C is widely cited as the theoretical upper limit for human survival over several hours because:","options":["Sweat can no longer evaporate to cool the body","Blood proteins begin to break down at that temperature","Oxygen in the air falls sharply at high humidity","Ultraviolet radiation peaks at that temperature"],"answer":0,"explanation":"Wet-bulb temperature combines heat and humidity. When it nears skin temperature, evaporation of sweat stops cooling the body, so even a resting, shaded person overheats. Dry-bulb heat alone is far less dangerous.","difficulty":"hard","source":"UPSC Prelims","questionHi":"लगभग 35 °C का आर्द्र-बल्ब तापमान कई घंटों तक मानव जीवित रहने की सैद्धांतिक ऊपरी सीमा क्यों माना जाता है?","optionsHi":["पसीना अब वाष्पित होकर शरीर को ठंडा नहीं कर पाता","उस तापमान पर रक्त के प्रोटीन टूटने लगते हैं","अधिक आर्द्रता पर वायु में ऑक्सीजन तेजी से घट जाती है","उस तापमान पर पराबैंगनी विकिरण चरम पर होता है"],"explanationHi":"आर्द्र-बल्ब तापमान ऊष्मा और आर्द्रता को जोड़ता है। जब यह त्वचा के तापमान के निकट पहुँचता है, तो पसीने का वाष्पन शरीर को ठंडा करना बंद कर देता है, इसलिए छाया में आराम कर रहा व्यक्ति भी अत्यधिक गर्म हो जाता है। केवल शुष्क-बल्ब की गर्मी कहीं कम खतरनाक होती है।"},
  {"id":"geo-climate-monsoon-97","question":"On calm nights in hilly areas, cool dense air flowing down the slopes into the valley is called a:","options":["Valley (anabatic) breeze","Sea breeze","Mountain (katabatic) wind","Föhn (chinook) downslope wind"],"answer":2,"explanation":"At night the slopes cool quickly and the chilled air drains downhill as a katabatic or mountain wind. By day warm air moves up the slopes as a valley (anabatic) breeze; a föhn is warm, dry air descending a leeward slope.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"पहाड़ी क्षेत्रों में शांत रातों में ढालों से घाटी की ओर नीचे बहने वाली ठंडी, सघन वायु क्या कहलाती है?","optionsHi":["घाटी समीर (एनाबैटिक)","सागर समीर","पर्वतीय (अवरोही/कैटाबैटिक) पवन","फोहन (चिनूक) अधोढाल पवन"],"explanationHi":"रात में ढाल तेजी से ठंडे हो जाते हैं और ठंडी हुई वायु कैटाबैटिक या पर्वतीय पवन के रूप में नीचे की ओर बह जाती है। दिन में गर्म वायु घाटी (एनाबैटिक) समीर के रूप में ढालों पर ऊपर चढ़ती है; फोहन पवनविमुख ढाल से उतरने वाली गर्म, शुष्क वायु है।"},
  {"id":"geo-climate-monsoon-98","question":"Large hailstones grow mainly because:","options":["Raindrops freeze while falling through warm air near the ground","Cumulonimbus updrafts cycle ice through supercooled water","Fog particles stick together and freeze on cold nights","Snowflakes melt and refreeze repeatedly in cirrus clouds"],"answer":1,"explanation":"In a towering cumulonimbus, updrafts toss ice pellets up and down; each trip adds a coat of frozen supercooled water, building layered hailstones until they are too heavy to hold up.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"बड़े ओले (हेलस्टोन) मुख्यतः किस कारण बनते हैं?","optionsHi":["भूमि के निकट गर्म वायु से गिरते समय वर्षा की बूँदें जम जाती हैं","कपासी-वर्षी बादल (क्यूम्यलोनिम्बस) की ऊर्ध्वगामी धाराएँ अतिशीतित जल के बीच बर्फ को चक्कर लगवाती हैं","ठंडी रातों में कोहरे के कण आपस में चिपककर जम जाते हैं","पक्षाभ बादलों में हिमकण बार-बार पिघलते और जमते हैं"],"explanationHi":"ऊँचे उठे कपासी-वर्षी बादल में ऊर्ध्वगामी धाराएँ बर्फ के कणों को ऊपर-नीचे उछालती हैं; हर चक्कर में जमे हुए अतिशीतित जल की एक परत चढ़ती है, जिससे परतदार ओले बनते हैं, जब तक कि वे इतने भारी न हो जाएँ कि हवा में टिके न रह सकें।"},
  {"id":"geo-climate-monsoon-99","question":"The Coriolis force, which deflects moving air, is:","options":["Greatest at the equator and zero at the poles","Equal at all latitudes","Present only in the southern hemisphere","Zero at the equator and greatest at the poles"],"answer":3,"explanation":"The Coriolis effect is proportional to the sine of latitude: zero at the equator and maximum at the poles. That is why cyclones rarely form within about 5° of the equator.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"कोरिओलिस बल, जो गतिमान वायु को विक्षेपित करता है:","optionsHi":["विषुवत रेखा पर सबसे अधिक और ध्रुवों पर शून्य होता है","सभी अक्षांशों पर समान होता है","केवल दक्षिणी गोलार्ध में होता है","विषुवत रेखा पर शून्य और ध्रुवों पर सबसे अधिक होता है"],"explanationHi":"कोरिओलिस प्रभाव अक्षांश की ज्या (sine) के समानुपाती होता है: विषुवत रेखा पर शून्य और ध्रुवों पर अधिकतम। इसीलिए विषुवत रेखा के लगभग 5° के भीतर चक्रवात बहुत कम बनते हैं।"},
  {"id":"geo-climate-monsoon-100","question":"How many of the following statements are correct? I. Rising air cools because it expands under lower pressure. II. Saturated rising air cools faster than dry air because condensation releases latent heat. III. Air descending the leeward slope of a range warms by compression. IV. In an adiabatic process the air loses heat to its surroundings.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: latent heat from condensation makes saturated air cool more slowly (about 5–6 °C per km against 9.8 °C for dry air). IV is wrong: adiabatic means no heat is exchanged with the surroundings.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कितने कथन सही हैं? I. ऊपर उठती वायु कम दाब में प्रसारित होने के कारण ठंडी होती है। II. संतृप्त ऊपर उठती वायु शुष्क वायु की तुलना में तेजी से ठंडी होती है, क्योंकि संघनन से गुप्त ऊष्मा निकलती है। III. किसी पर्वतमाला के पवनविमुख ढाल से उतरती वायु संपीडन से गर्म होती है। IV. रुद्धोष्म (adiabatic) प्रक्रिया में वायु अपने परिवेश को ऊष्मा खोती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। II गलत है: संघनन से निकली गुप्त ऊष्मा के कारण संतृप्त वायु अधिक धीरे ठंडी होती है (लगभग 5–6 °C प्रति किमी, जबकि शुष्क वायु के लिए 9.8 °C)। IV गलत है: रुद्धोष्म का अर्थ है कि परिवेश के साथ कोई ऊष्मा विनिमय नहीं होता।"},
  {"id":"geo-climate-monsoon-101","question":"Match the cloud type with its description. A. Cirrus  B. Cumulonimbus  C. Stratus  D. Nimbostratus; 1. Low, grey, uniform sheet that may give drizzle  2. Thick, dark layer giving steady, prolonged rain or snow  3. High, thin, feathery cloud of ice crystals  4. Towering cloud bringing thunder, lightning and hail","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Cirrus are high ice-crystal wisps; cumulonimbus are the thunderstorm clouds; stratus form a low grey sheet; nimbostratus bring long spells of steady rain. Mixing up stratus and nimbostratus is the usual trap.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"बादल के प्रकार का उसके विवरण से मिलान कीजिए। A. पक्षाभ (सिरस)  B. कपासी-वर्षी (क्यूम्यलोनिम्बस)  C. स्तरी (स्ट्रेटस)  D. वर्षा-स्तरी (निम्बोस्ट्रेटस); 1. निम्न, धूसर, एकसमान परत, जिससे फुहार हो सकती है  2. मोटी, गहरी परत, जो लगातार, लंबे समय तक वर्षा या हिमपात देती है  3. ऊँचे, पतले, पंख जैसे बादल, जो हिमकणों के बने होते हैं  4. ऊँचे उठे बादल, जो गर्जन, बिजली और ओले लाते हैं","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"पक्षाभ ऊँचे हिमकणों के रेशे हैं; कपासी-वर्षी गरज वाले बादल हैं; स्तरी निम्न धूसर परत बनाते हैं; वर्षा-स्तरी लंबे समय तक लगातार वर्षा लाते हैं। स्तरी और वर्षा-स्तरी को मिला देना सामान्य भूल है।"},
  {"id":"geo-climate-monsoon-102","question":"Assertion (A): Coastal towns have a smaller daily range of temperature than towns deep in the interior. Reason (R): Water has a higher specific heat than land, so the sea warms and cools slowly.","options":["A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"The sea's slow heating and cooling, together with sea and land breezes, moderates coastal temperatures; this is the maritime influence that keeps Mumbai's range far below Delhi's.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): तटीय शहरों में आंतरिक भागों के शहरों की तुलना में तापमान का दैनिक परिसर कम होता है। कारण (R): जल की विशिष्ट ऊष्मा स्थल से अधिक होती है, इसलिए समुद्र धीरे-धीरे गर्म और ठंडा होता है।","optionsHi":["A सही है, किंतु R गलत है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A गलत है, किंतु R सही है","A और R दोनों सही हैं और R, A की सही व्याख्या है"],"explanationHi":"समुद्र का धीरे-धीरे गर्म और ठंडा होना, सागर और स्थल समीरों के साथ मिलकर, तटीय तापमान को संतुलित करता है; यही सामुद्रिक प्रभाव मुंबई के परिसर को दिल्ली से कहीं कम रखता है।"},
  {"id":"geo-climate-monsoon-103","question":"Arrange the following in increasing order of their typical height above the ground: 1. Peak concentration of the ozone layer  2. Tropopause over the equator  3. Mesopause  4. Kármán line","options":["1-2-3-4","2-1-3-4","2-1-4-3","1-2-4-3"],"answer":1,"explanation":"The equatorial tropopause is about 16–18 km up, ozone peaks at roughly 20–25 km in the stratosphere, the mesopause lies near 85 km and the Kármán line, a conventional edge of space, at 100 km.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित को भूमि से उनकी सामान्य ऊँचाई के बढ़ते क्रम में व्यवस्थित कीजिए: 1. ओजोन परत की चरम सांद्रता  2. विषुवत रेखा के ऊपर क्षोभसीमा  3. मध्यसीमा (मेसोपॉज़)  4. कार्मन रेखा","optionsHi":["1-2-3-4","2-1-3-4","2-1-4-3","1-2-4-3"],"explanationHi":"विषुवतीय क्षोभसीमा लगभग 16–18 किमी ऊपर है, ओजोन समतापमंडल में लगभग 20–25 किमी पर चरम पर होती है, मध्यसीमा लगभग 85 किमी के निकट है और कार्मन रेखा, जो अंतरिक्ष की परंपरागत सीमा है, 100 किमी पर है।"},
  {"id":"geo-climate-monsoon-104","question":"How many of the following generally favour a strong south-west monsoon over India? I. Strong summer heating of the Tibetan plateau. II. A positive Indian Ocean Dipole. III. La Niña conditions in the Pacific. IV. Unusually heavy Eurasian snow cover in the preceding winter and spring.","options":["All four","Only one","Only two","Only three"],"answer":3,"explanation":"I, II and III favour a good monsoon. Heavy Eurasian snow cover uses up spring heat in melting and delays land warming, so it is linked to a weaker monsoon (an idea going back to Blanford); IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कितने भारत के ऊपर प्रबल दक्षिण-पश्चिम मानसून के सामान्यतः अनुकूल हैं? I. तिब्बत के पठार का प्रबल ग्रीष्मकालीन तापन। II. धनात्मक हिंद महासागर द्विध्रुव। III. प्रशांत महासागर में ला नीना की स्थितियाँ। IV. पिछली सर्दी और वसंत में यूरेशिया में असामान्य रूप से भारी हिमावरण।","optionsHi":["सभी चार","केवल एक","केवल दो","केवल तीन"],"explanationHi":"I, II और III अच्छे मानसून के अनुकूल हैं। यूरेशिया का भारी हिमावरण पिघलने में वसंत की ऊष्मा खर्च कर देता है और स्थल के गर्म होने में देरी करता है, इसलिए यह कमजोर मानसून से जुड़ा है (ब्लैनफोर्ड के समय से चला आ रहा विचार); अतः IV गलत है।"},
  {"id":"geo-climate-monsoon-105","question":"In the Köppen scheme, match the small letter with what it indicates. A. f  B. m  C. w  D. s; 1. Dry season in winter  2. Dry season in summer  3. No dry season, rain in all months  4. Monsoon type, with a short dry season","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"],"answer":0,"explanation":"f = rain all year, m = monsoon with a short dry spell, w = dry winter, s = dry summer. So Aw is tropical savanna with dry winters and As (Coromandel) has its dry season in summer.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कोपेन योजना में छोटे अक्षर का उसके द्वारा इंगित तथ्य से मिलान कीजिए। A. f  B. m  C. w  D. s; 1. सर्दियों में शुष्क ऋतु  2. गर्मियों में शुष्क ऋतु  3. कोई शुष्क ऋतु नहीं, सभी महीनों में वर्षा  4. मानसून प्रकार, लघु शुष्क ऋतु सहित","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"],"explanationHi":"f = वर्ष भर वर्षा, m = लघु शुष्क अवधि वाला मानसून, w = शुष्क शीत ऋतु, s = शुष्क ग्रीष्म ऋतु। अतः Aw शुष्क सर्दियों वाला उष्णकटिबंधीय सवाना है और As (कोरोमंडल) में शुष्क ऋतु गर्मियों में होती है।"},
  {"id":"geo-climate-monsoon-106","question":"How many of the following statements about the Inter-Tropical Convergence Zone (ITCZ) are correct? I. It is where the westerlies of the two hemispheres meet. II. It shifts east and west with the apparent movement of the sun. III. Over the Indian region its northward shift in summer is unusually large. IV. It is a belt of high pressure and sinking air.","options":["Only three","Only one","Only two","All four"],"answer":1,"explanation":"Only III is correct; over India the ITCZ reaches about 20°–25°N in July. It is where the trade winds meet (I wrong), it shifts north and south with the sun (II wrong), and it is a low-pressure zone of rising air (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अंतर-उष्णकटिबंधीय अभिसरण क्षेत्र (ITCZ) के बारे में निम्नलिखित में से कितने कथन सही हैं? I. यह वह स्थान है जहाँ दोनों गोलार्धों की पछुआ पवनें मिलती हैं। II. यह सूर्य की आभासी गति के साथ पूर्व और पश्चिम की ओर खिसकता है। III. भारतीय क्षेत्र के ऊपर गर्मियों में इसका उत्तर की ओर खिसकाव असामान्य रूप से बड़ा होता है। IV. यह उच्च दाब और अवतलित वायु की पेटी है।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"केवल III सही है; भारत के ऊपर जुलाई में ITCZ लगभग 20°–25°N तक पहुँच जाता है। यह वह स्थान है जहाँ व्यापारिक पवनें मिलती हैं (I गलत), यह सूर्य के साथ उत्तर और दक्षिण की ओर खिसकता है (II गलत), और यह ऊपर उठती वायु का निम्न दाब क्षेत्र है (IV गलत)।"},
  {"id":"geo-climate-monsoon-107","question":"Moist air at 26 °C at sea level is forced over a 3,000 m mountain range. It cools at the dry adiabatic rate of 10 °C/km until it becomes saturated at 1,000 m, then at the saturated rate of 6 °C/km up to the crest, where it has shed most of its moisture as rain. It then descends the leeward slope to sea level, unsaturated all the way. Its temperature at the leeward foot will be about:","options":["26 °C","22 °C","34 °C","23.5 °C"],"answer":2,"explanation":"Windward: 26 − 10 = 16 °C at 1 km, then 16 − 2 × 6 = 4 °C at the crest. Descending 3 km unsaturated warms it at 10 °C/km to 34 °C. The latent heat released as rain on the windward side is why foehn/chinook winds arrive warm and dry; 26 °C wrongly assumes a symmetric journey.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"समुद्र तल पर 26 °C की नम वायु को 3,000 मी ऊँची पर्वतमाला के ऊपर चढ़ने के लिए बाध्य किया जाता है। वह 1,000 मी पर संतृप्त होने तक 10 °C/किमी की शुष्क रुद्धोष्म दर से ठंडी होती है, फिर शिखर तक 6 °C/किमी की संतृप्त दर से, जहाँ वह अपनी अधिकांश नमी वर्षा के रूप में गिरा चुकी होती है। फिर वह पूरे रास्ते असंतृप्त रहते हुए पवनविमुख ढाल से समुद्र तल तक उतरती है। पवनविमुख ढाल के तल पर उसका तापमान लगभग कितना होगा?","optionsHi":["26 °C","22 °C","34 °C","23.5 °C"],"explanationHi":"पवनाभिमुख ओर: 1 किमी पर 26 − 10 = 16 °C, फिर शिखर पर 16 − 2 × 6 = 4 °C। 3 किमी असंतृप्त उतरने पर 10 °C/किमी की दर से गर्म होकर 34 °C हो जाती है। पवनाभिमुख ओर वर्षा के रूप में निकली गुप्त ऊष्मा के कारण ही फोहन/चिनूक पवनें गर्म और शुष्क पहुँचती हैं; 26 °C यह गलत मानने पर आता है कि यात्रा सममित है।"},
  {"id":"geo-climate-monsoon-108","question":"In the Köppen symbol 'Cwg', used for much of the Ganga plain, the letter 'g' indicates that:","options":["the hottest month comes before the solstice and the rains","the winter season is dry while summer is wet","the warmest month has a mean temperature above 22 °C (hot summer)","rain falls mainly in winter and the summer is dry"],"answer":0,"explanation":"'w' already marks the dry winter; 'g' (Ganges type) means the temperature peak comes before the June solstice, in May–June, because monsoon clouds and rain cool the later summer. 'a' denotes a warmest month above 22 °C and 's' a dry summer.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कोपेन प्रतीक ‘Cwg’ में, जो गंगा के मैदान के बड़े भाग के लिए प्रयुक्त होता है, अक्षर ‘g’ इंगित करता है कि:","optionsHi":["सबसे गर्म महीना अयनांत और वर्षा से पहले आता है","शीत ऋतु शुष्क और ग्रीष्म ऋतु आर्द्र होती है","सबसे गर्म महीने का औसत तापमान 22 °C से अधिक है (गर्म ग्रीष्म)","वर्षा मुख्यतः सर्दियों में होती है और ग्रीष्म ऋतु शुष्क होती है"],"explanationHi":"‘w’ पहले ही शुष्क शीत ऋतु को दर्शाता है; ‘g’ (गंगा प्रकार) का अर्थ है कि तापमान का शिखर जून अयनांत से पहले, मई–जून में आता है, क्योंकि मानसूनी बादल और वर्षा बाद की गर्मी को ठंडा कर देते हैं। ‘a’ 22 °C से अधिक सबसे गर्म महीने को और ‘s’ शुष्क ग्रीष्म को दर्शाता है।"},
  {"id":"geo-climate-monsoon-109","question":"Consider the following statements about explanations of the Indian monsoon: I. The classical thermal concept treats the monsoon as a giant land-and-sea breeze caused by the differential heating of the continent and the ocean. II. Flohn's dynamic concept links the monsoon to the seasonal northward shift of the ITCZ, which draws the equatorial westerlies over South Asia. III. The thermal concept by itself cannot easily account for breaks in the monsoon or its year-to-year variability. Which of the statements given above is/are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":3,"explanation":"All three are correct. A pure land–sea heating contrast would give a steady monsoon every year, so it cannot explain breaks, sudden onset or inter-annual swings, which modern views tie to the ITCZ, jet streams, ENSO and the IOD.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारतीय मानसून की व्याख्याओं के बारे में निम्नलिखित कथनों पर विचार कीजिए: I. परंपरागत तापीय संकल्पना मानसून को महाद्वीप और महासागर के अलग-अलग गर्म होने से उत्पन्न एक विशाल स्थल-और-सागर समीर मानती है। II. फ्लोन की गतिक संकल्पना मानसून को ITCZ के मौसमी उत्तरी खिसकाव से जोड़ती है, जो विषुवतीय पछुआ पवनों को दक्षिण एशिया के ऊपर खींच लाता है। III. केवल तापीय संकल्पना मानसून के विच्छेद या उसकी वर्ष-दर-वर्ष परिवर्तिता की आसानी से व्याख्या नहीं कर सकती। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल I","केवल I और II","केवल II और III","I, II और III"],"explanationHi":"तीनों सही हैं। केवल स्थल-सागर तापन का अंतर हर वर्ष एक स्थिर मानसून देता, इसलिए वह विच्छेद, अचानक आगमन या अंतर-वार्षिक उतार-चढ़ाव की व्याख्या नहीं कर सकता; आधुनिक विचार इन्हें ITCZ, जेट धाराओं, ENSO और IOD से जोड़ते हैं।"},
  {"id":"geo-climate-monsoon-110","question":"The 'Mascarene High', often cited as a driver of the strength of the south-west monsoon, is:","options":["a semi-permanent high in the upper troposphere over the Tibetan plateau","a subtropical high east of Madagascar, feeding cross-equatorial flow","a winter anticyclone over north-west India that gives rise to the north-east monsoon","a ridge of high pressure over the Arabian Sea that causes breaks in the monsoon"],"answer":1,"explanation":"The Mascarene High lies in the southern subtropical Indian Ocean near the Mascarene Islands; a stronger high pushes more south-east trades across the equator, where they turn into the south-west monsoon. The upper-level high over Tibet is a separate feature.","difficulty":"hard","source":"UPSC Prelims","questionHi":"‘मस्कारिन उच्च’, जिसे प्रायः दक्षिण-पश्चिम मानसून की प्रबलता के एक कारक के रूप में बताया जाता है, क्या है?","optionsHi":["तिब्बत के पठार के ऊपर ऊपरी क्षोभमंडल में एक अर्ध-स्थायी उच्च दाब","मेडागास्कर के पूर्व में एक उपोष्णकटिबंधीय उच्च दाब, जो अंतर-विषुवतीय प्रवाह को पोषित करता है","उत्तर-पश्चिम भारत के ऊपर शीतकालीन प्रतिचक्रवात, जो उत्तर-पूर्वी मानसून को जन्म देता है","अरब सागर के ऊपर उच्च दाब का एक कटक, जो मानसून में विच्छेद का कारण बनती है"],"explanationHi":"मस्कारिन उच्च दक्षिणी उपोष्णकटिबंधीय हिंद महासागर में मस्कारिन द्वीपों के निकट स्थित है; अधिक प्रबल उच्च दाब अधिक दक्षिण-पूर्वी व्यापारिक पवनों को विषुवत रेखा के पार धकेलता है, जहाँ वे दक्षिण-पश्चिम मानसून में बदल जाती हैं। तिब्बत के ऊपर ऊपरी स्तर का उच्च दाब एक अलग विशेषता है।"},
  {"id":"geo-climate-monsoon-111","question":"Arrange these IMD categories of low-pressure systems in increasing order of maximum sustained wind speed: 1. Severe cyclonic storm  2. Deep depression  3. Extremely severe cyclonic storm  4. Very severe cyclonic storm","options":["2, 1, 4, 3","2, 4, 1, 3","1, 2, 4, 3","2, 1, 3, 4"],"answer":0,"explanation":"IMD scale: deep depression 28–33 knots, severe cyclonic storm 48–63, very severe 64–89, extremely severe 90–119 and super cyclonic storm 120 knots or more. 'Very severe' is stronger than 'severe', a frequent slip.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"निम्न दाब तंत्रों की IMD श्रेणियों को अधिकतम सतत पवन गति के बढ़ते क्रम में व्यवस्थित कीजिए: 1. प्रचंड चक्रवाती तूफान  2. गहरा अवदाब  3. अत्यंत प्रचंड चक्रवाती तूफान  4. अति प्रचंड चक्रवाती तूफान","optionsHi":["2, 1, 4, 3","2, 4, 1, 3","1, 2, 4, 3","2, 1, 3, 4"],"explanationHi":"IMD पैमाना: गहरा अवदाब 28–33 नॉट, प्रचंड चक्रवाती तूफान 48–63, अति प्रचंड 64–89, अत्यंत प्रचंड 90–119 और सुपर चक्रवाती तूफान 120 नॉट या अधिक। ‘अति प्रचंड’ (very severe) ‘प्रचंड’ (severe) से अधिक तीव्र है; यहाँ प्रायः चूक हो जाती है।"},
  {"id":"geo-climate-monsoon-112","question":"Assertion (A): Places on the leeward side of the Western Ghats, such as Pune, receive far less monsoon rain than the Konkan coast. Reason (R): Air descending the leeward slopes is warmed adiabatically, which lowers its relative humidity.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Having dropped its moisture on the windward slopes, the air sinks and warms by compression on the eastern side, so its relative humidity falls and clouds dissolve, creating the rain-shadow of the Deccan.","difficulty":"moderate","source":"SSC CGL Tier 2 · State PSC","questionHi":"अभिकथन (A): पुणे जैसे पश्चिमी घाट के पवनविमुख ढाल पर स्थित स्थानों में कोंकण तट की तुलना में मानसूनी वर्षा बहुत कम होती है। कारण (R): पवनविमुख ढालों से उतरती वायु रुद्धोष्म रूप से गर्म हो जाती है, जिससे उसकी सापेक्ष आर्द्रता घट जाती है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"पवनाभिमुख ढालों पर अपनी नमी गिरा देने के बाद वायु पूर्वी ओर नीचे उतरती है और संपीडन से गर्म हो जाती है, जिससे उसकी सापेक्ष आर्द्रता घट जाती है और बादल विलीन हो जाते हैं, और दक्कन की वृष्टि छाया बनती है।"},
  {"id":"geo-climate-monsoon-113","question":"Assertion (A): Tropical cyclones almost never form within about 5° of the equator. Reason (R): Sea-surface temperatures close to the equator are usually below the 26.5–27 °C needed for cyclone formation.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Equatorial seas are among the warmest, so R is false. Cyclones cannot form there because the Coriolis force is nearly zero close to the equator and cannot set up the rotating circulation.","difficulty":"hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): उष्णकटिबंधीय चक्रवात विषुवत रेखा के लगभग 5° के भीतर लगभग कभी नहीं बनते। कारण (R): विषुवत रेखा के निकट समुद्री सतह का तापमान प्रायः चक्रवात निर्माण के लिए आवश्यक 26.5–27 °C से कम रहता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"विषुवतीय सागर सबसे गर्म सागरों में हैं, इसलिए R गलत है। चक्रवात वहाँ इसलिए नहीं बन सकते क्योंकि विषुवत रेखा के निकट कोरिओलिस बल लगभग शून्य होता है और घूर्णी परिसंचरण स्थापित नहीं कर पाता।"},
  {"id":"geo-climate-monsoon-114","question":"Assertion (A): Mumbai receives several times more annual rainfall than Pune. Reason (R): Being on the coast, Mumbai has a smaller annual range of temperature than Pune.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but the rainfall contrast is due to Mumbai lying on the windward side of the Western Ghats and Pune in their rain shadow; the sea's moderating effect explains the temperature range, not the rain.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"अभिकथन (A): मुंबई में पुणे की तुलना में वार्षिक वर्षा कई गुना अधिक होती है। कारण (R): तट पर स्थित होने के कारण मुंबई में पुणे की तुलना में तापमान का वार्षिक परिसर कम है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"दोनों सही हैं, परंतु वर्षा का अंतर इसलिए है कि मुंबई पश्चिमी घाट के पवनाभिमुख ढाल पर और पुणे उनकी वृष्टि छाया में स्थित है; समुद्र का संतुलनकारी प्रभाव तापमान के परिसर की व्याख्या करता है, वर्षा की नहीं।"},
  {"id":"geo-climate-monsoon-115","question":"Assertion (A): Kerala receives most of its annual rainfall from the north-east monsoon. Reason (R): Over most of India the north-east (winter) monsoon winds blow from the land towards the sea.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Kerala gets the bulk of its rain from the south-west monsoon in June–September, with only a secondary Oct–Nov peak, so A is false. R is true: the winter monsoon is an offshore land wind except where it crosses the Bay to reach the Coromandel coast.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"अभिकथन (A): केरल को अपनी अधिकांश वार्षिक वर्षा उत्तर-पूर्वी मानसून से प्राप्त होती है। कारण (R): भारत के अधिकांश भागों में उत्तर-पूर्वी (शीतकालीन) मानसूनी पवनें स्थल से समुद्र की ओर बहती हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"केरल को अपनी अधिकांश वर्षा जून–सितंबर के दक्षिण-पश्चिम मानसून से मिलती है, और अक्टूबर–नवंबर में केवल एक गौण शिखर आता है, अतः A गलत है। R सही है: शीतकालीन मानसून स्थल से समुद्र की ओर बहने वाली पवन है, सिवाय वहाँ के जहाँ वह खाड़ी पार करके कोरोमंडल तट तक पहुँचती है।"},
  {"id":"geo-climate-monsoon-116","question":"In summer the upper troposphere over the Tibetan plateau develops a strong anticyclone (high), whose southern flank feeds the tropical easterly jet. This upper-level high forms mainly because:","options":["snow cover on the plateau chills the air above it","western disturbances pile up air over the plateau","the elevated plateau heats the air, which rises and spreads out aloft","the subtropical westerly jet sinks over the plateau and compresses the air"],"answer":2,"explanation":"At 4–5 km height the plateau acts as an elevated heat source: heated air rises, giving low pressure near the surface but outflow and high pressure aloft, and easterlies on its southern side form the TEJ. Snow cover would weaken, not create, this high.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"गर्मियों में तिब्बत के पठार के ऊपर ऊपरी क्षोभमंडल में एक प्रबल प्रतिचक्रवात (उच्च दाब) बनता है, जिसका दक्षिणी पार्श्व उष्णकटिबंधीय पूर्वी जेट को पोषित करता है। यह ऊपरी स्तर का उच्च दाब मुख्यतः क्यों बनता है?","optionsHi":["पठार पर हिमावरण उसके ऊपर की वायु को ठंडा कर देता है","पश्चिमी विक्षोभ पठार के ऊपर वायु को एकत्र कर देते हैं","उन्नत पठार वायु को गर्म करता है, जो ऊपर उठकर ऊँचाई पर फैल जाती है","उपोष्णकटिबंधीय पछुआ जेट पठार के ऊपर नीचे उतरती है और वायु को संपीडित करती है"],"explanationHi":"4–5 किमी की ऊँचाई पर पठार एक उन्नत ऊष्मा स्रोत की तरह कार्य करता है: गर्म वायु ऊपर उठती है, जिससे सतह के निकट निम्न दाब बनता है, परंतु ऊपर बहिर्वाह और उच्च दाब बनता है, और उसके दक्षिणी पार्श्व की पूर्वी पवनें TEJ बनाती हैं। हिमावरण इस उच्च दाब को बनाता नहीं, कमजोर करता।"},
  {"id":"geo-climate-monsoon-117","question":"Which of the following is NOT one of the IMD's criteria for declaring the withdrawal of the south-west monsoon from north-west India?","options":["No rainfall over the area for five consecutive days","An anticyclone established in the lower troposphere, around the 850 hPa level","A marked fall in moisture seen in water-vapour satellite imagery and tephigrams","Outgoing longwave radiation over the area falling below 200 W/m²"],"answer":3,"explanation":"Withdrawal is declared on the first three conditions. Low outgoing longwave radiation (below 200 W/m²) signals deep convective cloud and is used for declaring the onset over Kerala, not the withdrawal.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"उत्तर-पश्चिम भारत से दक्षिण-पश्चिम मानसून की वापसी की घोषणा के लिए IMD के मानदंडों में से निम्नलिखित में से कौन-सा एक नहीं है?","optionsHi":["क्षेत्र में लगातार पाँच दिन तक वर्षा न होना","निम्न क्षोभमंडल में, लगभग 850 hPa स्तर पर, प्रतिचक्रवात की स्थापना","जलवाष्प उपग्रह चित्रों और टेफिग्रामों में नमी में स्पष्ट गिरावट","क्षेत्र के ऊपर बहिर्गामी दीर्घतरंग विकिरण का 200 W/m² से नीचे गिरना"],"explanationHi":"वापसी की घोषणा पहली तीन शर्तों पर की जाती है। निम्न बहिर्गामी दीर्घतरंग विकिरण (200 W/m² से नीचे) गहरे संवहनी बादलों का संकेत है और इसका उपयोग केरल में आगमन की घोषणा के लिए होता है, वापसी के लिए नहीं।"},
  {"id":"geo-climate-monsoon-118","question":"During a prolonged 'break' in the south-west monsoon, when central India stays largely dry, which region usually receives above-normal rainfall?","options":["The Konkan and Malabar coasts of the west","The sub-Himalayan belt and north-east","Gujarat and the Saurashtra peninsula","The Chhattisgarh basin and Odisha"],"answer":1,"explanation":"In a break the monsoon trough shifts north to the Himalayan foothills, so rain concentrates along the foothills and over the north-east, often flooding the Brahmaputra and north Bihar rivers, while the plains and the west coast get little.","difficulty":"hard","source":"UPSC Prelims","questionHi":"दक्षिण-पश्चिम मानसून में लंबे ‘विच्छेद’ के दौरान, जब मध्य भारत लगभग शुष्क रहता है, किस क्षेत्र में प्रायः सामान्य से अधिक वर्षा होती है?","optionsHi":["पश्चिम के कोंकण और मालाबार तट","उप-हिमालयी पट्टी और पूर्वोत्तर","गुजरात और सौराष्ट्र प्रायद्वीप","छत्तीसगढ़ बेसिन और ओडिशा"],"explanationHi":"विच्छेद में मानसून द्रोणी उत्तर की ओर हिमालय की तलहटी में खिसक जाती है, इसलिए वर्षा तलहटी और पूर्वोत्तर में केंद्रित हो जाती है, जिससे प्रायः ब्रह्मपुत्र और उत्तरी बिहार की नदियों में बाढ़ आ जाती है, जबकि मैदानों और पश्चिमी तट पर बहुत कम वर्षा होती है।"},
  {"id":"geo-climate-monsoon-119","question":"Spells of very heavy rain along the Konkan and Malabar coasts during the monsoon are usually associated with:","options":["an offshore trough with strong low-level westerlies","the shift of the monsoon trough to the Himalayan foothills","the passage of a western disturbance over north India","a weakening of the low-level jet over the Arabian Sea"],"answer":0,"explanation":"An offshore trough with embedded vortices, fed by a strong cross-equatorial low-level jet, sharply increases moisture convergence and orographic lifting on the coast. A foothill position of the trough or a weak low-level jet reduces west-coast rain.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मानसून के दौरान कोंकण और मालाबार तटों पर अत्यंत भारी वर्षा की अवधियाँ प्रायः किससे जुड़ी होती हैं?","optionsHi":["प्रबल निम्न-स्तरीय पछुआ पवनों वाली अपतटीय द्रोणी","मानसून द्रोणी का हिमालय की तलहटी में खिसक जाना","उत्तर भारत के ऊपर से पश्चिमी विक्षोभ का गुजरना","अरब सागर के ऊपर निम्न-स्तरीय जेट का कमजोर पड़ना"],"explanationHi":"भंवरों से युक्त अपतटीय द्रोणी, जो प्रबल अंतर-विषुवतीय निम्न-स्तरीय जेट से पोषित होती है, तट पर नमी अभिसरण और पर्वतीय उत्थान को तेजी से बढ़ा देती है। द्रोणी की तलहटी की स्थिति या कमजोर निम्न-स्तरीय जेट पश्चिमी तट की वर्षा घटा देते हैं।"},
  {"id":"geo-climate-monsoon-120","question":"In July, the lowest surface pressure over the Indian subcontinent is normally found over:","options":["the head of the Bay of Bengal","the Kerala and coastal Karnataka belt","the central Deccan plateau","north-western India and Pakistan"],"answer":3,"explanation":"Intense heating of the arid north-west creates a heat low (around 994 hPa) at the western end of the monsoon trough; the trough extends from there to the head of the Bay, where pressure is a little higher.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"जुलाई में भारतीय उपमहाद्वीप में सतह का सबसे कम दाब सामान्यतः कहाँ पाया जाता है?","optionsHi":["बंगाल की खाड़ी के शीर्ष पर","केरल और तटीय कर्नाटक पट्टी में","मध्य दक्कन के पठार पर","उत्तर-पश्चिमी भारत और पाकिस्तान में"],"explanationHi":"शुष्क उत्तर-पश्चिम का तीव्र तापन मानसून द्रोणी के पश्चिमी छोर पर एक ऊष्मीय निम्न दाब (लगभग 994 hPa) बनाता है; द्रोणी वहाँ से खाड़ी के शीर्ष तक फैली होती है, जहाँ दाब कुछ अधिक होता है।"},
  {"id":"geo-climate-monsoon-121","question":"Arrange these stations in decreasing order of average annual rainfall: 1. Bengaluru  2. Mangaluru  3. Jaisalmer  4. Chennai","options":["2, 1, 4, 3","2, 4, 1, 3","4, 2, 1, 3","2, 4, 3, 1"],"answer":1,"explanation":"Mangaluru on the windward coast gets about 3,500 mm, Chennai about 1,400 mm (mostly in Oct–Dec), Bengaluru on the plateau under 1,000 mm and Jaisalmer under 200 mm. Green Bengaluru is often wrongly assumed to be wetter than Chennai.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"इन स्टेशनों को औसत वार्षिक वर्षा के घटते क्रम में व्यवस्थित कीजिए: 1. बेंगलुरु  2. मंगलुरु  3. जैसलमेर  4. चेन्नई","optionsHi":["2, 1, 4, 3","2, 4, 1, 3","4, 2, 1, 3","2, 4, 3, 1"],"explanationHi":"पवनाभिमुख तट पर मंगलुरु में लगभग 3,500 मिमी, चेन्नई में लगभग 1,400 मिमी (अधिकांश अक्टूबर–दिसंबर में), पठार पर बेंगलुरु में 1,000 मिमी से कम और जैसलमेर में 200 मिमी से कम वर्षा होती है। हरे-भरे बेंगलुरु को प्रायः चेन्नई से अधिक आर्द्र समझ लिया जाता है, जो गलत है।"},
  {"id":"geo-climate-monsoon-122","question":"Dense winter fog over the Indo-Gangetic plain in December–January is favoured by all of the following EXCEPT:","options":["moist ground and air left behind by a passing western disturbance","long, clear nights that allow strong radiative cooling of the ground","calm or very light winds under a high-pressure system","strong surface winds that mix the lower layers of the air"],"answer":3,"explanation":"Radiation fog needs moisture, clear long nights and calm air so that a shallow surface layer cools to its dew point under an inversion. Strong winds mix warmer air downward and break up the inversion, preventing fog.","difficulty":"hard","source":"SSC CGL Tier 2 · State PSC","questionHi":"दिसंबर–जनवरी में सिंधु-गंगा के मैदान पर घना शीतकालीन कोहरा निम्नलिखित सभी से अनुकूल होता है, सिवाय:","optionsHi":["गुजरते पश्चिमी विक्षोभ द्वारा छोड़ी गई नम भूमि और वायु","लंबी, साफ रातें, जिनमें धरातल का प्रबल विकिरणी शीतलन होता है","उच्च दाब तंत्र के अंतर्गत शांत या बहुत हल्की पवनें","प्रबल सतही पवनें, जो वायु की निचली परतों को मिला देती हैं"],"explanationHi":"विकिरण कोहरे के लिए नमी, लंबी साफ रातें और शांत वायु आवश्यक हैं, ताकि व्युत्क्रमण के अंतर्गत एक उथली सतही परत अपने ओसांक तक ठंडी हो जाए। प्रबल पवनें गर्म वायु को नीचे मिला देती हैं और व्युत्क्रमण को तोड़ देती हैं, जिससे कोहरा नहीं बनता।"},
  {"id":"geo-climate-monsoon-123","question":"El Niño years tend to bring a weak monsoon to India. The mechanism most widely accepted for this link is that during an El Niño:","options":["warm water off Peru evaporates extra moisture that is carried to India","the Walker circulation's rising limb shifts east, so air sinks over India","the trade winds over the Pacific strengthen and drag moisture away from the Indian Ocean","cold water upwells along the west coast of India and cools the Arabian Sea"],"answer":1,"explanation":"With the warm pool and rising air displaced eastward, the compensating descending limb of the Walker circulation moves over the Indian Ocean and South Asia, suppressing convection. Trade winds weaken, not strengthen, in an El Niño.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अल नीनो वर्षों में भारत में मानसून कमजोर रहने की प्रवृत्ति होती है। इस संबंध की सबसे व्यापक रूप से स्वीकृत क्रियाविधि यह है कि अल नीनो के दौरान:","optionsHi":["पेरू के निकट का गर्म जल अतिरिक्त नमी का वाष्पन करता है, जो भारत तक पहुँचती है","वॉकर परिसंचरण की ऊर्ध्वगामी शाखा पूर्व की ओर खिसक जाती है, इसलिए भारत के ऊपर वायु नीचे उतरती है","प्रशांत महासागर पर व्यापारिक पवनें प्रबल हो जाती हैं और नमी को हिंद महासागर से दूर खींच ले जाती हैं","भारत के पश्चिमी तट पर ठंडा जल ऊपर उठता है और अरब सागर को ठंडा कर देता है"],"explanationHi":"गर्म जल कुंड और ऊपर उठती वायु के पूर्व की ओर विस्थापित हो जाने से वॉकर परिसंचरण की क्षतिपूरक अवरोही शाखा हिंद महासागर और दक्षिण एशिया के ऊपर आ जाती है, जिससे संवहन दब जाता है। अल नीनो में व्यापारिक पवनें कमजोर होती हैं, प्रबल नहीं।"},
  {"id":"geo-climate-monsoon-124","question":"A severe cyclone in the Bay of Bengal is moving north-west and is about to cross the Andhra Pradesh coast, which runs roughly south-west to north-east. Along the coast, the highest storm surge is usually expected:","options":["to the right of the track, north-east of landfall","to the left of the track, south-west of the landfall point","exactly at the landfall point, under the calm eye","equally on both sides, since the winds are symmetric"],"answer":0,"explanation":"Northern-hemisphere cyclones spin anticlockwise; on the right of the track the storm's forward motion adds to the wind speed and the winds blow onshore, piling water against the coast. On the left side the winds blow offshore.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"बंगाल की खाड़ी में एक प्रचंड चक्रवात उत्तर-पश्चिम की ओर बढ़ रहा है और आंध्र प्रदेश के तट को पार करने वाला है, जो लगभग दक्षिण-पश्चिम से उत्तर-पूर्व की ओर फैला है। तट के साथ सबसे ऊँची तूफानी लहर सामान्यतः कहाँ अपेक्षित होती है?","optionsHi":["मार्ग के दाईं ओर, स्थलगमन के उत्तर-पूर्व में","मार्ग के बाईं ओर, स्थलगमन बिंदु के दक्षिण-पश्चिम में","ठीक स्थलगमन बिंदु पर, शांत आँख के नीचे","दोनों ओर समान रूप से, क्योंकि पवनें सममित होती हैं"],"explanationHi":"उत्तरी गोलार्ध के चक्रवात वामावर्त घूमते हैं; मार्ग के दाईं ओर तूफान की अग्रगामी गति पवन की गति में जुड़ जाती है और पवनें तट की ओर बहती हैं, जिससे जल तट के विरुद्ध जमा हो जाता है। बाईं ओर पवनें तट से दूर समुद्र की ओर बहती हैं।"},
  {"id":"geo-climate-monsoon-125","question":"Match the Köppen climate type with the region where NCERT places it. A. Aw  B. BShw  C. Cwg  D. E; 1. Ganga plain, eastern Rajasthan and most of north-east India  2. Most of the peninsular plateau south of the Tropic of Cancer  3. High mountain areas of Jammu and Kashmir, Himachal Pradesh and Uttarakhand  4. Rain-shadow belt east of the Western Ghats and parts of Rajasthan, Haryana and Gujarat","options":["A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"answer":2,"explanation":"Aw (tropical savanna) covers most of the plateau; BShw (semi-arid steppe) the rain-shadow interior and the margins of the Thar; Cwg (monsoon with dry winter) the Ganga plain; E (polar/highland) the high Himalaya.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कोपेन के जलवायु प्रकार का उस क्षेत्र से मिलान कीजिए जहाँ NCERT उसे रखता है। A. Aw  B. BShw  C. Cwg  D. E; 1. गंगा का मैदान, पूर्वी राजस्थान और अधिकांश पूर्वोत्तर भारत  2. कर्क रेखा के दक्षिण में प्रायद्वीपीय पठार का अधिकांश भाग  3. जम्मू-कश्मीर, हिमाचल प्रदेश और उत्तराखंड के ऊँचे पर्वतीय क्षेत्र  4. पश्चिमी घाट के पूर्व की वृष्टि छाया पट्टी और राजस्थान, हरियाणा तथा गुजरात के कुछ भाग","optionsHi":["A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"explanationHi":"Aw (उष्णकटिबंधीय सवाना) पठार के अधिकांश भाग को ढकता है; BShw (अर्ध-शुष्क स्टेपी) वृष्टि छाया वाले आंतरिक भाग और थार के किनारों को; Cwg (शुष्क शीत ऋतु वाला मानसून) गंगा के मैदान को; E (ध्रुवीय/उच्चभूमि) ऊँचे हिमालय को।"},
  {"id":"geo-climate-monsoon-126","question":"An unsaturated air parcel at the surface has a temperature of 30 °C and a dew point of 22 °C. As it rises, its temperature falls at 10 °C per km and its dew point at about 2 °C per km. Clouds will begin to form at a height of about:","options":["800 m","1,333 m","4,000 m","1,000 m"],"answer":3,"explanation":"The gap of 8 °C closes at 10 − 2 = 8 °C per km, so condensation begins at about 1 km. 800 m wrongly assumes the dew point stays fixed; 1,333 m uses the saturated lapse rate before saturation.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"धरातल पर एक असंतृप्त वायु पुंज का तापमान 30 °C और ओसांक 22 °C है। जैसे-जैसे वह ऊपर उठती है, उसका तापमान 10 °C प्रति किमी की दर से और ओसांक लगभग 2 °C प्रति किमी की दर से घटता है। बादल लगभग कितनी ऊँचाई पर बनना शुरू होंगे?","optionsHi":["800 मी","1,333 मी","4,000 मी","1,000 मी"],"explanationHi":"8 °C का अंतर 10 − 2 = 8 °C प्रति किमी की दर से समाप्त होता है, इसलिए संघनन लगभग 1 किमी पर शुरू होता है। 800 मी यह गलत मानने पर आता है कि ओसांक स्थिर रहता है; 1,333 मी संतृप्त होने से पहले संतृप्त ह्रास दर का उपयोग करने पर आता है।"},
  {"id":"geo-climate-monsoon-127","question":"How many of these correctly distinguish tropical cyclones from temperate (extra-tropical) cyclones? I. Tropical cyclones have no fronts. II. Tropical cyclones draw their energy mainly from the latent heat released by condensation. III. Tropical cyclones usually cover a smaller area than temperate cyclones but are more intense. IV. Tropical cyclones weaken quickly after moving over land.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: tropical cyclones have no fronts, draw energy from latent heat, are more compact but more intense than temperate cyclones (which can be 1,000–2,000 km across), and weaken quickly over land.","difficulty":"hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन उष्णकटिबंधीय चक्रवातों को शीतोष्ण (बहिरुष्णकटिबंधीय) चक्रवातों से सही ढंग से अलग करते हैं? I. उष्णकटिबंधीय चक्रवातों में वाताग्र (फ्रंट) नहीं होते। II. उष्णकटिबंधीय चक्रवात अपनी ऊर्जा मुख्यतः संघनन से निकली गुप्त ऊष्मा से प्राप्त करते हैं। III. उष्णकटिबंधीय चक्रवात सामान्यतः शीतोष्ण चक्रवातों से छोटे क्षेत्र को ढकते हैं, किंतु अधिक तीव्र होते हैं। IV. उष्णकटिबंधीय चक्रवात स्थल पर पहुँचने के बाद शीघ्र कमजोर हो जाते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं: उष्णकटिबंधीय चक्रवातों में वाताग्र नहीं होते, वे गुप्त ऊष्मा से ऊर्जा लेते हैं, शीतोष्ण चक्रवातों (जो 1,000–2,000 किमी तक चौड़े हो सकते हैं) की तुलना में अधिक सघन किंतु अधिक तीव्र होते हैं, और स्थल पर शीघ्र कमजोर हो जाते हैं।"},
  {"id":"geo-climate-monsoon-128","question":"A ship in the Bay of Bengal finds the wind blowing steadily from the south-west. By Buys Ballot's law, the centre of low pressure lies roughly towards the:","options":["north-west","south-east","north-east","south-west"],"answer":0,"explanation":"Stand with your back to the wind, facing north-east: in the northern hemisphere low pressure lies to the left, i.e. the north-west. North-east confuses where the wind is going with where the low lies; south-east applies the southern-hemisphere rule.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"बंगाल की खाड़ी में एक जहाज को पवन लगातार दक्षिण-पश्चिम से बहती मिलती है। बाइस बैलट के नियम के अनुसार, निम्न दाब का केंद्र लगभग किस दिशा में है?","optionsHi":["उत्तर-पश्चिम","दक्षिण-पूर्व","उत्तर-पूर्व","दक्षिण-पश्चिम"],"explanationHi":"पवन की ओर पीठ करके, उत्तर-पूर्व की ओर मुख करके खड़े होइए: उत्तरी गोलार्ध में निम्न दाब बाईं ओर, अर्थात उत्तर-पश्चिम में होता है। उत्तर-पूर्व कहना इस भ्रम से आता है कि पवन कहाँ जा रही है और निम्न दाब कहाँ है; दक्षिण-पूर्व दक्षिणी गोलार्ध का नियम लगाने से आता है।"},
  {"id":"geo-climate-monsoon-129","question":"Match the rainfall event with the main type of precipitation. A. Afternoon thunderstorm rain over Kerala in April  B. July rain on the windward slopes of the Western Ghats  C. Winter rain over Punjab from a western disturbance  D. Heavy rain over coastal Odisha from a Bay of Bengal depression; 1. Orographic  2. Convectional  3. Extra-tropical cyclonic  4. Tropical cyclonic","options":["A-2, B-1, C-4, D-3","A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-3, B-1, C-2, D-4"],"answer":2,"explanation":"Pre-monsoon afternoon storms come from surface heating (convectional), Western Ghats rain from forced ascent (orographic), western disturbances are mid-latitude (extra-tropical) lows, and Bay depressions are tropical cyclonic systems.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"वर्षा की घटना का उसके मुख्य वर्षण प्रकार से मिलान कीजिए। A. अप्रैल में केरल में दोपहर की गरज के साथ वर्षा  B. पश्चिमी घाट के पवनाभिमुख ढालों पर जुलाई की वर्षा  C. पश्चिमी विक्षोभ से पंजाब में शीतकालीन वर्षा  D. बंगाल की खाड़ी के अवदाब से तटीय ओडिशा में भारी वर्षा; 1. पर्वतीय  2. संवहनीय  3. बहिरुष्णकटिबंधीय चक्रवातीय  4. उष्णकटिबंधीय चक्रवातीय","optionsHi":["A-2, B-1, C-4, D-3","A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-3, B-1, C-2, D-4"],"explanationHi":"मानसून-पूर्व की दोपहर की आँधियाँ सतही तापन (संवहनीय) से आती हैं, पश्चिमी घाट की वर्षा बलपूर्वक ऊपर उठने (पर्वतीय) से, पश्चिमी विक्षोभ मध्य-अक्षांशीय (बहिरुष्णकटिबंधीय) निम्न दाब हैं, और खाड़ी के अवदाब उष्णकटिबंधीय चक्रवातीय तंत्र हैं।"},
  {"id":"geo-climate-monsoon-130","question":"Consider the following statements: I. Along the Ganga plain, average annual rainfall decreases from east to west. II. Across the peninsula, rainfall decreases from the west coast towards the interior east of the Western Ghats. III. Along the west coast, rainfall increases steadily northwards from Kerala to Gujarat. Which of the statements given above is/are correct?","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"The Bay branch loses moisture as it moves up the plain, and the Ghats leave the interior in rain shadow. III is wrong: the Gujarat coast is far drier than the Konkan and Malabar coasts.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: I. गंगा के मैदान के साथ औसत वार्षिक वर्षा पूर्व से पश्चिम की ओर घटती है। II. प्रायद्वीप में वर्षा पश्चिमी तट से पश्चिमी घाट के पूर्व के आंतरिक भाग की ओर घटती है। III. पश्चिमी तट के साथ केरल से गुजरात की ओर उत्तर में वर्षा लगातार बढ़ती है। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल I","केवल I और II","केवल II और III","I, II और III"],"explanationHi":"खाड़ी शाखा मैदान में आगे बढ़ते हुए नमी खोती जाती है, और घाट आंतरिक भाग को वृष्टि छाया में छोड़ देते हैं। III गलत है: गुजरात का तट कोंकण और मालाबार तटों की तुलना में कहीं अधिक शुष्क है।"},
  {"id":"geo-climate-monsoon-131","question":"Assertion (A): Around the June solstice, the daily solar radiation received at the top of the atmosphere over north India is greater than that over the equator. Reason (R): In June the noon Sun stands higher in the sky over the equator than over north India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"In June the Sun is overhead near 23.5° N, so at about 28° N the noon Sun is roughly 85° high against about 67° at the equator, and days are longer too; hence A is true and R false. This is why the heat low develops over north-west India.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): जून अयनांत के आसपास, उत्तर भारत के ऊपर वायुमंडल के शीर्ष पर प्राप्त दैनिक सौर विकिरण विषुवत रेखा के ऊपर की तुलना में अधिक होता है। कारण (R): जून में दोपहर का सूर्य आकाश में उत्तर भारत की तुलना में विषुवत रेखा पर अधिक ऊँचा होता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"जून में सूर्य लगभग 23.5° N पर सिर के ऊपर होता है, इसलिए लगभग 28° N पर दोपहर का सूर्य लगभग 85° ऊँचाई पर होता है, जबकि विषुवत रेखा पर लगभग 67° पर, और दिन भी लंबे होते हैं; अतः A सही और R गलत है। इसीलिए उत्तर-पश्चिम भारत के ऊपर ऊष्मीय निम्न दाब बनता है।"},
  {"id":"geo-climate-monsoon-132","question":"Arrange these places in the order in which the south-west monsoon normally withdraws from them: 1. Patna  2. Jaisalmer  3. Thiruvananthapuram  4. Delhi","options":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","3, 1, 4, 2"],"answer":0,"explanation":"Withdrawal begins from west Rajasthan in September, reaches Delhi in late September, Bihar in early October and the far south last, by mid-October. 3, 1, 4, 2 is roughly the order of onset, not withdrawal.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"इन स्थानों को उस क्रम में व्यवस्थित कीजिए जिसमें दक्षिण-पश्चिम मानसून सामान्यतः उनसे लौटता है: 1. पटना  2. जैसलमेर  3. तिरुवनंतपुरम  4. दिल्ली","optionsHi":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","3, 1, 4, 2"],"explanationHi":"वापसी सितंबर में पश्चिमी राजस्थान से शुरू होती है, सितंबर के अंत में दिल्ली पहुँचती है, अक्टूबर के आरंभ में बिहार और सुदूर दक्षिण में सबसे अंत में, मध्य अक्टूबर तक। 3, 1, 4, 2 लगभग आगमन का क्रम है, वापसी का नहीं।"},
  {"id":"geo-climate-monsoon-133","question":"On a cloudless summer day Chandigarh (about 350 m above sea level) records 38 °C. Using the normal lapse rate of temperature, the expected temperature at a hill station at about 2,350 m in the same air mass is roughly:","options":["18 °C","25 °C","31.5 °C","22.7 °C"],"answer":1,"explanation":"The height difference is 2,000 m, so 38 − 2 × 6.5 = 25 °C. 22.7 °C wrongly uses the full 2,350 m altitude, and 18 °C uses the dry adiabatic rate meant for rising air parcels.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"एक बादलरहित गर्मी के दिन चंडीगढ़ (समुद्र तल से लगभग 350 मी ऊपर) में 38 °C दर्ज होता है। तापमान की सामान्य ह्रास दर का उपयोग करते हुए, उसी वायु राशि में लगभग 2,350 मी की ऊँचाई पर स्थित पर्वतीय स्थल का अपेक्षित तापमान लगभग कितना होगा?","optionsHi":["18 °C","25 °C","31.5 °C","22.7 °C"],"explanationHi":"ऊँचाई का अंतर 2,000 मी है, इसलिए 38 − 2 × 6.5 = 25 °C। 22.7 °C पूरी 2,350 मी की ऊँचाई का गलत उपयोग करने पर आता है, और 18 °C ऊपर उठती वायु पुंजों के लिए बनी शुष्क रुद्धोष्म दर के उपयोग से आता है।"},
  {"id":"geo-climate-monsoon-134","question":"How many of these statements about the two branches of the south-west monsoon are correct? I. The Arabian Sea branch is stronger than the Bay of Bengal branch. II. Part of the Arabian Sea branch crosses central India and mingles with the Bay of Bengal branch over the northern plains. III. Part of the Bay of Bengal branch is deflected towards India by the Arakan hills along the coast of Myanmar. IV. The Bay of Bengal branch is turned eastward by the Himalaya and so never reaches Punjab.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Himalaya deflect the Bay branch westward up the Ganga plain, and it does reach Punjab and Haryana, though with much less moisture, so IV is wrong.","difficulty":"hard","source":"UPSC Prelims","questionHi":"दक्षिण-पश्चिम मानसून की दो शाखाओं के बारे में इनमें से कितने कथन सही हैं? I. अरब सागर शाखा बंगाल की खाड़ी शाखा से अधिक प्रबल है। II. अरब सागर शाखा का एक भाग मध्य भारत को पार करके उत्तरी मैदानों के ऊपर बंगाल की खाड़ी शाखा से मिल जाता है। III. बंगाल की खाड़ी शाखा का एक भाग म्यांमार के तट के साथ स्थित अराकान पहाड़ियों द्वारा भारत की ओर मोड़ दिया जाता है। IV. बंगाल की खाड़ी शाखा को हिमालय पूर्व की ओर मोड़ देता है, इसलिए वह कभी पंजाब नहीं पहुँचती।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। हिमालय खाड़ी शाखा को गंगा के मैदान में पश्चिम की ओर मोड़ देता है, और वह पंजाब और हरियाणा तक पहुँचती है, यद्यपि बहुत कम नमी के साथ, अतः IV गलत है।"},
  {"id":"geo-climate-monsoon-135","question":"Which of the following have generally been associated with a WEAKER south-west monsoon over India? I. An El Niño developing in the Pacific  II. A positive Indian Ocean Dipole  III. Unusually extensive Eurasian and Himalayan snow cover in the preceding winter and spring  IV. Strong pre-monsoon heating of the Tibetan plateau","options":["I and III only","I, III and IV only","I only","I, II and III only"],"answer":0,"explanation":"Blanford noticed in the 1880s that heavy Himalayan snow precedes weak monsoons: energy goes into melting snow instead of heating the land. A positive IOD and strong Tibetan heating favour a stronger monsoon.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-से सामान्यतः भारत में कमजोर दक्षिण-पश्चिम मानसून से जुड़े रहे हैं? I. प्रशांत महासागर में अल नीनो का विकसित होना  II. धनात्मक हिंद महासागर द्विध्रुव  III. पिछली सर्दी और वसंत में यूरेशिया और हिमालय का असामान्य रूप से व्यापक हिमावरण  IV. तिब्बत के पठार का प्रबल मानसून-पूर्व तापन","optionsHi":["केवल I और III","केवल I, III और IV","केवल I","केवल I, II और III"],"explanationHi":"ब्लैनफोर्ड ने 1880 के दशक में देखा कि भारी हिमालयी हिमपात के बाद मानसून कमजोर रहता है: ऊर्जा स्थल को गर्म करने के बजाय हिम को पिघलाने में लग जाती है। धनात्मक IOD और तिब्बत का प्रबल तापन अधिक प्रबल मानसून के अनुकूल हैं।"},
  {"id":"geo-climate-monsoon-136","question":"Assertion (A): Western disturbances affect north-west India far more often in winter than in summer. Reason (R): In winter the subtropical westerly jet lies south of the Himalaya and steers these systems towards India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Western disturbances travel embedded in the westerly jet. In summer the jet shifts north of the Tibetan plateau, so these lows are steered away from India, which is why winter rain in Punjab and snow in Kashmir come mainly from them.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"अभिकथन (A): पश्चिमी विक्षोभ उत्तर-पश्चिम भारत को गर्मियों की तुलना में सर्दियों में कहीं अधिक बार प्रभावित करते हैं। कारण (R): सर्दियों में उपोष्णकटिबंधीय पछुआ जेट हिमालय के दक्षिण में स्थित होती है और इन तंत्रों को भारत की ओर निर्देशित करती है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं, किंतु R, A की सही व्याख्या नहीं है","A सही है, किंतु R गलत है","A गलत है, किंतु R सही है"],"explanationHi":"पश्चिमी विक्षोभ पछुआ जेट में समाहित होकर यात्रा करते हैं। गर्मियों में जेट तिब्बत के पठार के उत्तर में चली जाती है, इसलिए ये निम्न दाब तंत्र भारत से दूर निर्देशित हो जाते हैं; इसीलिए पंजाब में शीतकालीन वर्षा और कश्मीर में हिमपात मुख्यतः इन्हीं से होता है।"},
  {"id":"geo-climate-monsoon-137","question":"Under the widely used Oceanic Niño Index (ONI), El Niño conditions are said to exist when:","options":["sea-surface temperature off Peru alone rises 0.5 °C for a single month","the Southern Oscillation Index stays strongly positive for three months","sea-surface temperature in the western Pacific warm pool exceeds 30 °C","the three-month mean SST anomaly in Niño 3.4 is +0.5 °C or more"],"answer":3,"explanation":"The ONI uses the central-equatorial Niño 3.4 box, not the Peru coast (Niño 1+2). El Niño goes with a negative, not positive, Southern Oscillation Index.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"व्यापक रूप से प्रयुक्त महासागरीय नीनो सूचकांक (ONI) के अंतर्गत, अल नीनो की स्थितियाँ तब मानी जाती हैं जब:","optionsHi":["केवल पेरू के निकट समुद्री सतह का तापमान एक ही महीने के लिए 0.5 °C बढ़ जाए","दक्षिणी दोलन सूचकांक तीन महीने तक प्रबल रूप से धनात्मक बना रहे","पश्चिमी प्रशांत के गर्म जल कुंड में समुद्री सतह का तापमान 30 °C से अधिक हो","नीनो 3.4 में तीन महीने के औसत SST विचलन का मान +0.5 °C या उससे अधिक हो"],"explanationHi":"ONI मध्य-विषुवतीय नीनो 3.4 क्षेत्र का उपयोग करता है, पेरू तट (नीनो 1+2) का नहीं। अल नीनो के साथ दक्षिणी दोलन सूचकांक ऋणात्मक होता है, धनात्मक नहीं।"},
  {"id":"geo-climate-monsoon-138","question":"Consider the following statements about the Arabian Sea: I. Its surface temperature typically falls from a peak in May to a minimum in July–August. II. This cooling is caused mainly by strong monsoon winds that drive upwelling along the Somali and Arabian coasts, mix the upper ocean and increase evaporation. III. Partly because of this, cyclones over the Arabian Sea are concentrated in the pre-monsoon and post-monsoon months. Which of the statements given above is/are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":3,"explanation":"The monsoon winds themselves cool the Arabian Sea through upwelling, mixing and evaporation, and also create strong vertical wind shear, so cyclones there cluster in May–June and October–November.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अरब सागर के बारे में निम्नलिखित कथनों पर विचार कीजिए: I. इसकी सतह का तापमान सामान्यतः मई के शिखर से गिरकर जुलाई–अगस्त में न्यूनतम हो जाता है। II. यह शीतलन मुख्यतः प्रबल मानसूनी पवनों के कारण होता है, जो सोमाली और अरब तटों पर उत्स्रवण कराती हैं, ऊपरी महासागर को मिला देती हैं और वाष्पन बढ़ाती हैं। III. आंशिक रूप से इसी कारण, अरब सागर के चक्रवात मानसून-पूर्व और मानसून-पश्चात के महीनों में केंद्रित रहते हैं। ऊपर दिए गए कथनों में से कौन-सा/से सही है/हैं?","optionsHi":["केवल I और II","केवल II और III","केवल I और III","I, II और III"],"explanationHi":"मानसूनी पवनें स्वयं उत्स्रवण, मिश्रण और वाष्पन से अरब सागर को ठंडा करती हैं, और प्रबल ऊर्ध्वाधर पवन अपरूपण भी उत्पन्न करती हैं, इसलिए वहाँ चक्रवात मई–जून और अक्टूबर–नवंबर में केंद्रित रहते हैं।"},
  {"id":"geo-climate-monsoon-139","question":"A station records 210 mm of rain in 24 hours. Under the IMD's terminology for daily rainfall at a station, this is described as:","options":["heavy rainfall","very heavy rainfall","extremely heavy rainfall","a cloudburst"],"answer":2,"explanation":"IMD: heavy 64.5–115.5 mm, very heavy 115.6–204.4 mm, extremely heavy 204.5 mm or more. A cloudburst means about 100 mm or more in an hour over a small area, so a daily total alone does not make one.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"किसी स्टेशन पर 24 घंटे में 210 मिमी वर्षा दर्ज होती है। किसी स्टेशन पर दैनिक वर्षा के लिए IMD की शब्दावली के अंतर्गत इसे क्या कहा जाता है?","optionsHi":["भारी वर्षा","बहुत भारी वर्षा","अत्यंत भारी वर्षा","बादल फटना"],"explanationHi":"IMD: भारी 64.5–115.5 मिमी, बहुत भारी 115.6–204.4 मिमी, अत्यंत भारी 204.5 मिमी या अधिक। बादल फटने का अर्थ किसी छोटे क्षेत्र में एक घंटे में लगभग 100 मिमी या अधिक वर्षा है, इसलिए केवल दैनिक कुल वर्षा से बादल फटना नहीं माना जाता।"},
  {"id":"geo-climate-monsoon-140","question":"Match the traditional Indian season with its months in the Hindu calendar. A. Vasanta  B. Grishma  C. Sharad  D. Shishira; 1. Magha–Phalguna  2. Chaitra–Vaisakha  3. Jyeshtha–Ashadha  4. Ashvin–Kartika","options":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"answer":3,"explanation":"The six ritus run Vasanta (Chaitra–Vaisakha), Grishma (Jyeshtha–Ashadha), Varsha (Shravana–Bhadrapada), Sharad (Ashvin–Kartika), Hemanta (Margashirsha–Pausha) and Shishira (Magha–Phalguna).","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"पारंपरिक भारतीय ऋतु का हिंदू पंचांग के उसके महीनों से मिलान कीजिए। A. वसंत  B. ग्रीष्म  C. शरद  D. शिशिर; 1. माघ–फाल्गुन  2. चैत्र–वैशाख  3. ज्येष्ठ–आषाढ़  4. आश्विन–कार्तिक","optionsHi":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"explanationHi":"छह ऋतुएँ इस क्रम में हैं: वसंत (चैत्र–वैशाख), ग्रीष्म (ज्येष्ठ–आषाढ़), वर्षा (श्रावण–भाद्रपद), शरद (आश्विन–कार्तिक), हेमंत (मार्गशीर्ष–पौष) और शिशिर (माघ–फाल्गुन)।"},
  {"id":"geo-climate-monsoon-141","question":"The north–south difference in temperature across India is large in January but small in July. The best explanation is that:","options":["in January the sea's moderating influence reaches across the whole northern plain","in July the high Sun and longer days offset the north's higher latitude","in July the Himalaya trap warm air over the south and let cold air into the north","the north-east monsoon brings warm air to the north in July"],"answer":1,"explanation":"In summer the high Sun and long days of the north offset its latitude, so the north becomes as hot as or hotter than the south; in winter low sun angle, short days and cold continental air make the north much colder than the tropical south.","difficulty":"hard","source":"SSC CGL Tier 2 · State PSC","questionHi":"भारत में उत्तर–दक्षिण तापमान का अंतर जनवरी में बड़ा और जुलाई में छोटा होता है। इसकी सर्वोत्तम व्याख्या यह है कि:","optionsHi":["जनवरी में समुद्र का संतुलनकारी प्रभाव पूरे उत्तरी मैदान तक पहुँच जाता है","जुलाई में ऊँचा सूर्य और लंबे दिन उत्तर के ऊँचे अक्षांश की भरपाई कर देते हैं","जुलाई में हिमालय दक्षिण में गर्म वायु को रोक लेता है और उत्तर में ठंडी वायु को आने देता है","उत्तर-पूर्वी मानसून जुलाई में उत्तर में गर्म वायु लाता है"],"explanationHi":"गर्मियों में उत्तर का ऊँचा सूर्य और लंबे दिन उसके अक्षांश की भरपाई कर देते हैं, इसलिए उत्तर दक्षिण के बराबर या उससे अधिक गर्म हो जाता है; सर्दियों में सूर्य का निम्न कोण, छोटे दिन और ठंडी महाद्वीपीय वायु उत्तर को उष्णकटिबंधीय दक्षिण से बहुत अधिक ठंडा बना देते हैं।"},
  {"id":"geo-climate-monsoon-142","question":"How many of these statements about monsoon depressions are correct? I. Most of them form over the north Bay of Bengal. II. They usually move west-north-west along the monsoon trough. III. Their heaviest rain usually falls in the south-west sector of the system. IV. Like mature cyclones, they have a calm, cloud-free eye.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct; monsoon depressions are weaker systems without an eye and bring much of central and north India's monsoon rain, concentrated in their south-west sector, so IV is wrong.","difficulty":"hard","source":"UPSC Prelims","questionHi":"मानसून अवदाबों के बारे में इनमें से कितने कथन सही हैं? I. इनमें से अधिकांश उत्तरी बंगाल की खाड़ी में बनते हैं। II. ये प्रायः मानसून द्रोणी के साथ पश्चिम-उत्तर-पश्चिम दिशा में बढ़ते हैं। III. इनकी सबसे भारी वर्षा प्रायः तंत्र के दक्षिण-पश्चिमी भाग में होती है। IV. परिपक्व चक्रवातों की तरह इनमें भी शांत, बादलरहित आँख होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं; मानसून अवदाब आँख रहित कमजोर तंत्र हैं और मध्य तथा उत्तर भारत की अधिकांश मानसूनी वर्षा लाते हैं, जो उनके दक्षिण-पश्चिमी भाग में केंद्रित होती है, अतः IV गलत है।"},
  {"id":"geo-climate-monsoon-143","question":"Station P has a mean annual rainfall of 250 mm with a standard deviation of 100 mm; station Q has a mean of 2,500 mm with a standard deviation of 400 mm. Which statement is correct?","options":["Q's rainfall is more variable, because its standard deviation is four times larger","P's rainfall is more variable: its CV is 40% against 16% for Q","Both are equally variable, since variability depends only on the mean","P's coefficient of variation is 4% and Q's is 16%"],"answer":1,"explanation":"Coefficient of variation = SD/mean: 100/250 = 40% for P and 400/2,500 = 16% for Q. This is why low-rainfall areas like western Rajasthan have the least dependable rain even though wet areas swing more in absolute millimetres.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"स्टेशन P की औसत वार्षिक वर्षा 250 मिमी है और मानक विचलन 100 मिमी; स्टेशन Q का औसत 2,500 मिमी और मानक विचलन 400 मिमी है। कौन-सा कथन सही है?","optionsHi":["Q की वर्षा अधिक परिवर्तनशील है, क्योंकि उसका मानक विचलन चार गुना अधिक है","P की वर्षा अधिक परिवर्तनशील है: उसका विचरण गुणांक 40% है, जबकि Q का 16%","दोनों समान रूप से परिवर्तनशील हैं, क्योंकि परिवर्तिता केवल माध्य पर निर्भर करती है","P का विचरण गुणांक 4% है और Q का 16%"],"explanationHi":"विचरण गुणांक = मानक विचलन/माध्य: P के लिए 100/250 = 40% और Q के लिए 400/2,500 = 16%। इसीलिए पश्चिमी राजस्थान जैसे कम वर्षा वाले क्षेत्रों में वर्षा सबसे कम विश्वसनीय होती है, भले ही आर्द्र क्षेत्रों में मिलीमीटर में उतार-चढ़ाव अधिक हो।"},
  {"id":"geo-climate-monsoon-144","question":"Which of these pairs of pre-monsoon local storm and region is NOT correct?","options":["Blossom showers – Kerala and Karnataka (coffee belt)","Kalbaisakhi – West Bengal","Mango showers – Punjab","Loo – north and north-western plains"],"answer":2,"explanation":"Mango showers are the pre-monsoon showers of Kerala and coastal Karnataka that help ripen mangoes. Punjab gets Loo and dust storms (andhi) in summer, not mango showers.","difficulty":"hard","questionHi":"पूर्व-मानसून स्थानीय तूफान और क्षेत्र के निम्नलिखित युग्मों में से कौन-सा सही नहीं है?","optionsHi":["पुष्प वर्षा – केरल और कर्नाटक (कॉफ़ी पेटी)","काल बैसाखी – पश्चिम बंगाल","आम्र वर्षा – पंजाब","लू – उत्तर और उत्तर-पश्चिमी मैदान"],"explanationHi":"आम्र वर्षा केरल और तटीय कर्नाटक की पूर्व-मानसून बौछारें हैं जो आम पकाने में सहायक हैं। पंजाब में गर्मियों में लू और धूल भरी आँधी (अंधी) आती है, आम्र वर्षा नहीं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-145","question":"The violent pre-monsoon thunderstorms of Assam, accompanied by squally winds and hail, are locally called:","options":["Bardoli Chheerha","Andhi (dust storm)","Mahawat (winter rain)","Loo (hot dry wind)"],"answer":0,"explanation":"In Assam these storms are Bardoli Chheerha (Bordoichila). Loo is the hot dry wind of the north-west plains, andhi a dust storm, and Mahawat the winter rain of north-west India.","difficulty":"moderate","questionHi":"असम में ओलों और तेज़ हवाओं के साथ आने वाले प्रचंड पूर्व-मानसून तूफान स्थानीय रूप से क्या कहलाते हैं?","optionsHi":["बारदोली छीड़ा","अंधी (धूल भरी आँधी)","महावट (शीतकालीन वर्षा)","लू (गर्म शुष्क हवा)"],"explanationHi":"असम में इन तूफानों को बारदोली छीड़ा (बोरदोईचिला) कहते हैं। लू उत्तर-पश्चिमी मैदानों की गर्म शुष्क हवा है, अंधी धूल भरी आँधी है और महावट उत्तर-पश्चिम भारत की शीतकालीन वर्षा है।","source":"State PCS · SSC CGL"},
  {"id":"geo-climate-monsoon-146","question":"The winter rainfall brought to north-western India by western disturbances is locally known as:","options":["Kal Baisakhi","Mahawat","Loo","Andhi"],"answer":1,"explanation":"The light winter showers of Punjab, Haryana and western Uttar Pradesh are called Mahawat and are valuable for the rabi wheat crop. The other three are summer phenomena.","difficulty":"hard","questionHi":"पश्चिमी विक्षोभों से उत्तर-पश्चिमी भारत में होने वाली शीतकालीन वर्षा को स्थानीय रूप से क्या कहा जाता है?","optionsHi":["काल बैसाखी","महावट","लू","अंधी"],"explanationHi":"पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश की हल्की शीतकालीन वर्षा को महावट कहते हैं और यह रबी की गेहूँ फसल के लिए उपयोगी है। अन्य तीनों ग्रीष्मकालीन परिघटनाएँ हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-147","question":"Chillai Kalan, the harshest 40-day winter spell of Kashmir, begins on:","options":["15 January","1 February","1 December","21 December"],"answer":3,"explanation":"Chillai Kalan runs from 21 December to 29 January, followed by the milder Chillai Khurd and Chillai Bachha. Most snowfall and the coldest nights fall in this period.","difficulty":"hard","questionHi":"कश्मीर की सबसे कठोर 40 दिन की शीत अवधि चिल्लई कलां किस तिथि से आरंभ होती है?","optionsHi":["15 जनवरी","1 फ़रवरी","1 दिसंबर","21 दिसंबर"],"explanationHi":"चिल्लई कलां 21 दिसंबर से 29 जनवरी तक चलती है, उसके बाद अपेक्षाकृत हल्की चिल्लई खुर्द और चिल्लई बच्चा आती हैं। अधिकांश हिमपात और सबसे ठंडी रातें इसी अवधि में होती हैं।","source":"State PCS · UPSC Prelims"},
  {"id":"geo-climate-monsoon-148","question":"In the Köppen classification of India, match the type with the region. A. Amw  B. As  C. Aw  D. BWhw; 1. West coast south of Goa  2. Coromandel coast  3. Most of the peninsular plateau  4. Western Rajasthan","options":["A-1, B-2, C-4, D-3","A-1, B-2, C-3, D-4","A-1, B-3, C-2, D-4","A-2, B-1, C-3, D-4"],"answer":1,"explanation":"Amw (monsoon with a short dry season) is on the west coast south of Goa; As (savanna with dry summer) is on the Coromandel coast; Aw covers most of the peninsula; BWhw (hot desert) is western Rajasthan.","difficulty":"very-hard","questionHi":"भारत के कोपेन वर्गीकरण में प्रकार का क्षेत्र से मिलान कीजिए। A. Amw  B. As  C. Aw  D. BWhw; 1. गोवा के दक्षिण का पश्चिमी तट  2. कोरोमंडल तट  3. अधिकांश प्रायद्वीपीय पठार  4. पश्चिमी राजस्थान","optionsHi":["A-1, B-2, C-4, D-3","A-1, B-2, C-3, D-4","A-1, B-3, C-2, D-4","A-2, B-1, C-3, D-4"],"explanationHi":"Amw (छोटे शुष्क मौसम वाला मानसूनी) गोवा के दक्षिण के पश्चिमी तट पर है; As (शुष्क ग्रीष्म वाला सवाना) कोरोमंडल तट पर है; Aw अधिकांश प्रायद्वीप में है; BWhw (उष्ण मरुस्थल) पश्चिमी राजस्थान में है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-149","question":"In the NCERT Köppen map of India, the Dfc type (cold humid winter with a short cool summer) is found in:","options":["Western Rajasthan","Konkan coast","Meghalaya","Arunachal Pradesh"],"answer":3,"explanation":"Dfc, with snow-bearing winters and a short cool summer, is shown over Arunachal Pradesh. Meghalaya is mostly Cwg, western Rajasthan BWhw, and the Konkan coast Amw.","difficulty":"hard","questionHi":"एनसीईआरटी के कोपेन मानचित्र में Dfc प्रकार (ठंडी आर्द्र सर्दी और छोटी ठंडी गर्मी) किस क्षेत्र में पाया जाता है?","optionsHi":["पश्चिमी राजस्थान","कोंकण तट","मेघालय","अरुणाचल प्रदेश"],"explanationHi":"हिमपात वाली सर्दी और छोटी ठंडी गर्मी वाला Dfc अरुणाचल प्रदेश में दर्शाया गया है। मेघालय मुख्यतः Cwg, पश्चिमी राजस्थान BWhw और कोंकण तट Amw है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-150","question":"In Köppen's scheme, the 'C' (warm temperate, mesothermal) group is defined by the mean temperature of the coolest month lying between:","options":["−3 °C and 18 °C","−10 °C and 0 °C","18 °C and 22 °C","0 °C and 10 °C"],"answer":0,"explanation":"Group C has a coolest-month mean between −3 °C and 18 °C. Group A (tropical) has every month at or above 18 °C, and group D has the coolest month below −3 °C.","difficulty":"very-hard","questionHi":"कोपेन की योजना में 'C' (उष्ण-शीतोष्ण, मेसोथर्मल) समूह की परिभाषा सबसे ठंडे महीने के औसत तापमान के किस अंतराल से होती है?","optionsHi":["−3 °C और 18 °C","−10 °C और 0 °C","18 °C और 22 °C","0 °C और 10 °C"],"explanationHi":"समूह C में सबसे ठंडे महीने का औसत −3 °C और 18 °C के बीच होता है। समूह A (उष्णकटिबंधीय) में प्रत्येक माह 18 °C या उससे अधिक रहता है तथा समूह D में सबसे ठंडा महीना −3 °C से नीचे होता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-151","question":"For a station in the plains, the IMD declares a cold wave when the minimum temperature is 10 °C or less and is below normal by at least:","options":["8 °C","2 °C","4.5 °C","6.5 °C"],"answer":2,"explanation":"A cold wave in the plains needs a minimum of 10 °C or lower and a departure of −4.5 °C to −6.4 °C; a departure of −6.5 °C or more makes it a severe cold wave.","difficulty":"hard","questionHi":"मैदानी क्षेत्र के किसी स्टेशन पर IMD शीत लहर तब घोषित करता है जब न्यूनतम तापमान 10 °C या उससे कम हो और सामान्य से कम से कम कितना नीचे हो?","optionsHi":["8 °C","2 °C","4.5 °C","6.5 °C"],"explanationHi":"मैदानों में शीत लहर के लिए न्यूनतम तापमान 10 °C या उससे कम तथा सामान्य से −4.5 °C से −6.4 °C का विचलन चाहिए; −6.5 °C या अधिक विचलन होने पर यह तीव्र शीत लहर कहलाती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-152","question":"In the IMD's rainfall intensity scale, 150 mm of rain in 24 hours is classed as:","options":["Very heavy","Extremely heavy","Heavy","Moderate"],"answer":0,"explanation":"IMD classes 64.5–115.5 mm as heavy, 115.6–204.4 mm as very heavy and 204.5 mm or more as extremely heavy. 150 mm lies in the very heavy band.","difficulty":"hard","questionHi":"IMD के वर्षा तीव्रता पैमाने में 24 घंटे में 150 mm वर्षा किस श्रेणी में आती है?","optionsHi":["बहुत भारी","अत्यंत भारी","भारी","मध्यम"],"explanationHi":"IMD 64.5–115.5 mm को भारी, 115.6–204.4 mm को बहुत भारी और 204.5 mm या अधिक को अत्यंत भारी मानता है। 150 mm बहुत भारी वर्ग में आती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-153","question":"The IMD defines a cloudburst as sudden rainfall of about:","options":["25 mm in 10 minutes over about 1,000 km²","50 mm in 24 hours anywhere in a hill region","100 mm per hour over a small area of about 20–30 km²","204.5 mm in 24 hours over an entire district"],"answer":2,"explanation":"A cloudburst is an extremely intense, localised downpour exceeding 100 mm per hour over roughly 20–30 km², usually from a cumulonimbus in hills. The other options describe broader or milder rainfall.","difficulty":"hard","questionHi":"IMD मेघ-प्रस्फोट (बादल फटना) को लगभग किस प्रकार की अचानक वर्षा के रूप में परिभाषित करता है?","optionsHi":["लगभग 1,000 km² पर 10 मिनट में 25 mm","पर्वतीय क्षेत्र में कहीं भी 24 घंटे में 50 mm","लगभग 20–30 km² के छोटे क्षेत्र पर 100 mm प्रति घंटा","पूरे जिले पर 24 घंटे में 204.5 mm"],"explanationHi":"मेघ-प्रस्फोट लगभग 20–30 km² पर 100 mm प्रति घंटे से अधिक की अत्यंत तीव्र, स्थानीय वर्षा है, जो प्रायः पहाड़ियों में कपासी-वर्षी मेघ से होती है। अन्य विकल्प व्यापक या हल्की वर्षा बताते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-154","question":"For the IMD, a meteorological drought over a region is classed as 'severe' when its seasonal rainfall deficit exceeds:","options":["75 per cent","25 per cent","10 per cent","50 per cent"],"answer":3,"explanation":"Meteorological drought starts when the deficit passes 25 per cent of the long-period average; a deficit of 26–50 per cent is moderate and more than 50 per cent is severe.","difficulty":"hard","questionHi":"IMD के अनुसार किसी क्षेत्र में मौसमी वर्षा की कमी कितने प्रतिशत से अधिक होने पर मौसम-विज्ञानीय सूखा 'गंभीर' श्रेणी का होता है?","optionsHi":["75 प्रतिशत","25 प्रतिशत","10 प्रतिशत","50 प्रतिशत"],"explanationHi":"वर्षा की कमी दीर्घावधि औसत के 25 प्रतिशत से अधिक होने पर मौसम-विज्ञानीय सूखा आरंभ होता है; 26–50 प्रतिशत कमी मध्यम और 50 प्रतिशत से अधिक कमी गंभीर होती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-155","question":"A meteorological sub-division receives seasonal rainfall that is 22 per cent below its long-period average. Under the IMD's sub-division categories, this is:","options":["Normal","Deficient","Excess","Large deficient"],"answer":1,"explanation":"IMD treats −19% to +19% as normal, −20% to −59% as deficient, and −60% or worse as large deficient (scanty). A 22 per cent shortfall is therefore deficient.","difficulty":"very-hard","questionHi":"किसी मौसम-विज्ञानीय उप-मंडल में मौसमी वर्षा उसके दीर्घावधि औसत से 22 प्रतिशत कम होती है। IMD की उप-मंडल श्रेणियों के अनुसार यह है:","optionsHi":["सामान्य","न्यून (अपर्याप्त)","अधिक","अत्यंत न्यून"],"explanationHi":"IMD −19% से +19% को सामान्य, −20% से −59% को न्यून और −60% या उससे कम को अत्यंत न्यून (अल्प) मानता है। इसलिए 22 प्रतिशत की कमी न्यून श्रेणी में आती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-156","question":"The India Meteorological Department (IMD) was established in:","options":["1901","1857","1923","1875"],"answer":3,"explanation":"The IMD was set up in 1875 under the first Meteorological Reporter to the Government of India, H. F. Blanford. The other dates are common distractors from Indian scientific history.","difficulty":"moderate","questionHi":"भारतीय मौसम विज्ञान विभाग (IMD) की स्थापना किस वर्ष हुई थी?","optionsHi":["1901","1857","1923","1875"],"explanationHi":"IMD की स्थापना 1875 में भारत सरकार के प्रथम मौसम रिपोर्टर एच. एफ. ब्लैनफ़ोर्ड के अधीन हुई थी। अन्य वर्ष भारतीय वैज्ञानिक इतिहास से लिए गए सामान्य भ्रामक विकल्प हैं।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-157","question":"India's first dedicated meteorological satellite, launched in 2002 and later renamed in honour of an astronaut, was:","options":["IRS-1A","Kalpana-1","Bhaskara","INSAT-1A"],"answer":1,"explanation":"METSAT, launched in 2002, was renamed Kalpana-1 after Kalpana Chawla. INSAT-1A had weather imaging among other roles, Bhaskara was an experimental earth-observation satellite and IRS-1A was a remote-sensing satellite.","difficulty":"moderate","questionHi":"2002 में प्रक्षेपित और बाद में एक अंतरिक्ष यात्री के सम्मान में नाम बदली गई भारत की पहली समर्पित मौसम-विज्ञानीय उपग्रह कौन-सी थी?","optionsHi":["IRS-1A","कल्पना-1","भास्कर","इन्सैट-1A"],"explanationHi":"2002 में प्रक्षेपित मेटसैट का नाम कल्पना चावला के सम्मान में कल्पना-1 रखा गया। इन्सैट-1A में अन्य कार्यों के साथ मौसम चित्रण भी था, भास्कर प्रायोगिक भू-प्रेक्षण उपग्रह और IRS-1A सुदूर संवेदन उपग्रह था।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-climate-monsoon-158","question":"In the IMD's colour-coded weather warnings, which colour means 'be prepared' for severe weather?","options":["Green","Yellow","Orange","Red"],"answer":2,"explanation":"Green means no action, Yellow 'be aware' (watch), Orange 'be prepared' (alert), and Red 'take action' (warning of extreme weather).","difficulty":"moderate","questionHi":"IMD की रंग-कूटित मौसम चेतावनियों में कौन-सा रंग गंभीर मौसम के लिए 'तैयार रहें' का संकेत देता है?","optionsHi":["हरा","पीला","नारंगी","लाल"],"explanationHi":"हरे का अर्थ कोई कार्रवाई नहीं, पीले का 'सचेत रहें' (निगरानी), नारंगी का 'तैयार रहें' (सतर्कता) और लाल का 'कार्रवाई करें' (चरम मौसम की चेतावनी) है।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-159","question":"The IMD describes fog as 'very dense' when the visibility falls below:","options":["50 m","1,000 m","200 m","500 m"],"answer":0,"explanation":"IMD fog categories are very dense (below 50 m), dense (50–200 m), moderate (201–500 m) and shallow (501–1,000 m). A visibility of 1 km or more is classed as mist or haze.","difficulty":"hard","questionHi":"IMD कोहरे को 'अत्यंत घना' तब कहता है जब दृश्यता कितने से कम हो जाती है?","optionsHi":["50 m","1,000 m","200 m","500 m"],"explanationHi":"IMD की कोहरा श्रेणियाँ हैं: अत्यंत घना (50 m से कम), घना (50–200 m), मध्यम (201–500 m) और उथला (501–1,000 m)। 1 km या अधिक दृश्यता को धुंध या धूमिल मौसम माना जाता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-160","question":"Cyclone activity over the north Indian Ocean peaks in April–June and October–December rather than in July–September mainly because:","options":["the Coriolis force becomes too weak over the Bay of Bengal during the monsoon season","the Himalaya blocks moisture from reaching the Bay of Bengal during the monsoon season","wind shear is weak and sea temperatures are high in the transition months, but strong shear suppresses storms during the monsoon","sea-surface temperatures fall below 26.5 °C during the monsoon, while remaining high in other months"],"answer":2,"explanation":"In the monsoon the strong vertical shear (low-level westerlies under upper easterlies) tears developing storms apart; in the transition months shear is weak and the sea is warm. Sea temperatures stay above 26.5 °C throughout.","difficulty":"very-hard","questionHi":"उत्तरी हिंद महासागर में चक्रवाती गतिविधि जुलाई–सितंबर की बजाय अप्रैल–जून और अक्तूबर–दिसंबर में चरम पर मुख्यतः क्यों होती है?","optionsHi":["मानसून ऋतु में बंगाल की खाड़ी पर कोरिओलिस बल बहुत कमज़ोर हो जाता है","मानसून ऋतु में हिमालय नमी को बंगाल की खाड़ी तक पहुँचने से रोक देता है","संक्रमण के महीनों में पवन अपरूपण कमज़ोर और समुद्री तापमान ऊँचा होता है, जबकि मानसून में तेज़ अपरूपण तूफानों को दबा देता है","मानसून में समुद्र की सतह का तापमान 26.5 °C से नीचे गिर जाता है, जबकि अन्य महीनों में ऊँचा रहता है"],"explanationHi":"मानसून में तेज़ ऊर्ध्वाधर अपरूपण (निचले स्तर की पछुआ हवाएँ और ऊपर पूर्वी हवाएँ) बनते तूफानों को बिखेर देता है; संक्रमण के महीनों में अपरूपण कमज़ोर और समुद्र गर्म होता है। समुद्री तापमान पूरे वर्ष 26.5 °C से ऊपर रहता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-161","question":"Compared with the poles, the tropopause over the equator is:","options":["lower and warmer","higher and warmer","lower and colder","higher and colder"],"answer":3,"explanation":"Strong convection lifts the tropopause to about 18 km at the equator, where it is near −80 °C, against about 8 km and −45 °C over the poles.","difficulty":"hard","questionHi":"ध्रुवों की तुलना में भूमध्य रेखा के ऊपर क्षोभसीमा (ट्रोपोपॉज़) कैसी होती है?","optionsHi":["अधिक नीची और अधिक गर्म","अधिक ऊँची और अधिक गर्म","अधिक नीची और अधिक ठंडी","अधिक ऊँची और अधिक ठंडी"],"explanationHi":"प्रबल संवहन भूमध्य रेखा पर क्षोभसीमा को लगभग 18 km तक उठा देता है, जहाँ तापमान लगभग −80 °C होता है, जबकि ध्रुवों पर यह लगभग 8 km और −45 °C होता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-162","question":"Of every 100 units of insolation reaching the top of the atmosphere, about how many units are absorbed by the Earth's surface in the NCERT heat budget?","options":["35","51","14","65"],"answer":1,"explanation":"Of the 100 units, 35 are reflected back to space (albedo), 14 are absorbed by the atmosphere and 51 reach and are absorbed by the Earth's surface; 65 is the total absorbed by atmosphere plus surface.","difficulty":"hard","questionHi":"एनसीईआरटी के ऊष्मा बजट में वायुमंडल के शीर्ष पर पहुँचने वाली प्रत्येक 100 इकाई सूर्यातप में से लगभग कितनी इकाइयाँ पृथ्वी की सतह द्वारा अवशोषित होती हैं?","optionsHi":["35","51","14","65"],"explanationHi":"100 इकाइयों में से 35 अंतरिक्ष में परावर्तित हो जाती हैं (एल्बिडो), 14 वायुमंडल द्वारा अवशोषित होती हैं और 51 पृथ्वी की सतह तक पहुँचकर अवशोषित होती हैं; 65 वायुमंडल और सतह द्वारा कुल अवशोषित मात्रा है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-163","question":"The sea-level temperature is 28 °C. Assuming the normal lapse rate of 6.5 °C per km, the temperature at the summit of Everest (8,848 m) would be about:","options":["−29.5 °C","−25.1 °C","−57.5 °C","−35.4 °C"],"answer":0,"explanation":"The fall is 6.5 × 8.848 ≈ 57.5 °C, so the temperature is 28 − 57.5 ≈ −29.5 °C. −57.5 °C forgets to start from 28 °C, and −25.1 °C uses 6 °C per km.","difficulty":"moderate","questionHi":"समुद्र तल पर तापमान 28 °C है। 6.5 °C प्रति km की सामान्य ताप ह्रास दर मानकर एवरेस्ट शिखर (8,848 m) पर तापमान लगभग कितना होगा?","optionsHi":["−29.5 °C","−25.1 °C","−57.5 °C","−35.4 °C"],"explanationHi":"गिरावट 6.5 × 8.848 ≈ 57.5 °C है, इसलिए तापमान 28 − 57.5 ≈ −29.5 °C होगा। −57.5 °C में 28 °C से आरंभ करना भूल गया है और −25.1 °C में 6 °C प्रति km लिया गया है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-164","question":"Delhi (220 m) records 38.0 °C. Assuming a normal lapse rate of 6.5 °C per km and no other effects, the expected temperature at a hill station at 2,200 m is about:","options":["12.9 °C","22.2 °C","28.7 °C","25.1 °C"],"answer":3,"explanation":"The height difference is 1,980 m, so the fall is 1.98 × 6.5 ≈ 12.9 °C and the temperature is 38.0 − 12.9 ≈ 25.1 °C. 12.9 °C is only the drop, and 22.2 °C uses 8 °C per km.","difficulty":"hard","questionHi":"दिल्ली (220 m) में तापमान 38.0 °C है। 6.5 °C प्रति km की सामान्य ताप ह्रास दर मानकर और अन्य प्रभावों को छोड़कर, 2,200 m ऊँचाई वाले पर्वतीय स्थल पर अपेक्षित तापमान लगभग कितना होगा?","optionsHi":["12.9 °C","22.2 °C","28.7 °C","25.1 °C"],"explanationHi":"ऊँचाई का अंतर 1,980 m है, इसलिए गिरावट 1.98 × 6.5 ≈ 12.9 °C और तापमान 38.0 − 12.9 ≈ 25.1 °C होगा। 12.9 °C केवल गिरावट है और 22.2 °C में 8 °C प्रति km लिया गया है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-165","question":"Moist air at 25 °C at sea level is forced up a 3,000 m range. Condensation begins at 1,000 m; above that it cools at 5 °C/km. Having lost all its moisture, it descends the leeward side to sea level, warming at 10 °C/km. Its temperature at the leeward foot is:","options":["20 °C","25 °C","35 °C","30 °C"],"answer":2,"explanation":"Up to 1,000 m it cools 10 °C to 15 °C; from 1,000 to 3,000 m it cools 10 °C more to 5 °C. Descending 3,000 m dry it warms 30 °C, reaching 35 °C, 10 °C warmer than at the start.","difficulty":"very-hard","questionHi":"समुद्र तल पर 25 °C की आर्द्र वायु को 3,000 m ऊँची पर्वतमाला पर चढ़ाया जाता है। संघनन 1,000 m पर शुरू होता है; उसके ऊपर वह 5 °C/km की दर से ठंडी होती है। सारी नमी खोकर वह पवन-विमुख ढलान से समुद्र तल तक उतरती है और 10 °C/km की दर से गर्म होती है। पवन-विमुख तलहटी पर उसका तापमान है:","optionsHi":["20 °C","25 °C","35 °C","30 °C"],"explanationHi":"1,000 m तक वह 10 °C घटकर 15 °C हो जाती है; 1,000 से 3,000 m तक 10 °C और घटकर 5 °C होती है। 3,000 m शुष्क उतरने पर 30 °C बढ़कर 35 °C हो जाती है, जो आरंभिक तापमान से 10 °C अधिक है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-166","question":"Using the rule of thumb that cloud base forms about 125 m above the ground for every 1 °C by which the surface temperature exceeds the dew point, a rising parcel at 34 °C with dew point 22 °C will begin forming cloud at about:","options":["2,750 m","1,500 m","4,250 m","750 m"],"answer":1,"explanation":"The spread is 34 − 22 = 12 °C, so cloud base is about 12 × 125 = 1,500 m. 2,750 m multiplies 125 by the dew point and 4,250 by the temperature.","difficulty":"very-hard","questionHi":"यह मानकर कि सतह तापमान के ओसांक से प्रत्येक 1 °C अधिक होने पर बादल का आधार भूमि से लगभग 125 m ऊपर बनता है, 34 °C और ओसांक 22 °C वाला उठता हुआ वायु-पुंज लगभग कितनी ऊँचाई पर बादल बनाना आरंभ करेगा?","optionsHi":["2,750 m","1,500 m","4,250 m","750 m"],"explanationHi":"अंतर 34 − 22 = 12 °C है, इसलिए बादल का आधार लगभग 12 × 125 = 1,500 m होगा। 2,750 m में 125 को ओसांक से और 4,250 m में तापमान से गुणा कर दिया गया है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-167","question":"A station has a mean annual rainfall of 80 cm with a standard deviation of 20 cm. Its coefficient of variation of rainfall is:","options":["25 per cent","4 per cent","40 per cent","16 per cent"],"answer":0,"explanation":"The coefficient of variation is standard deviation divided by the mean, times 100: 20 ÷ 80 × 100 = 25 per cent. Inverting the ratio gives the trap value of 4.","difficulty":"hard","questionHi":"किसी स्टेशन की औसत वार्षिक वर्षा 80 cm और मानक विचलन 20 cm है। उसकी वर्षा का विचरण गुणांक है:","optionsHi":["25 प्रतिशत","4 प्रतिशत","40 प्रतिशत","16 प्रतिशत"],"explanationHi":"विचरण गुणांक = मानक विचलन ÷ माध्य × 100 = 20 ÷ 80 × 100 = 25 प्रतिशत। अनुपात उलटने पर भ्रामक मान 4 आता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-168","question":"As a warm front approaches an observer, the clouds seen overhead typically appear in the sequence:","options":["Stratus, cumulus, cirrus, altocumulus","Nimbostratus, altostratus, cirrostratus, cirrus","Cirrus, cirrostratus, altostratus, nimbostratus","Cumulonimbus, nimbostratus, altostratus, cirrus"],"answer":2,"explanation":"A warm front rises along a gentle slope, so the first signs are high ice-crystal cirrus, thickening to cirrostratus and altostratus, with steady rain from nimbostratus near the front. The reverse order describes the sky after it passes.","difficulty":"very-hard","questionHi":"जब कोई उष्ण वाताग्र किसी प्रेक्षक के निकट आता है, तो ऊपर आकाश में बादल प्रायः किस क्रम में दिखाई देते हैं?","optionsHi":["स्तरी, कपासी, पक्षाभ, मध्य-कपासी","वर्षा-स्तरी, मध्य-स्तरी, पक्षाभ-स्तरी, पक्षाभ","पक्षाभ, पक्षाभ-स्तरी, मध्य-स्तरी, वर्षा-स्तरी","कपासी-वर्षी, वर्षा-स्तरी, मध्य-स्तरी, पक्षाभ"],"explanationHi":"उष्ण वाताग्र हल्के ढाल पर ऊपर चढ़ता है, इसलिए पहले बर्फ़ के कणों वाले ऊँचे पक्षाभ दिखते हैं, फिर वे पक्षाभ-स्तरी और मध्य-स्तरी में बदलते हैं और वाताग्र के निकट वर्षा-स्तरी से लगातार वर्षा होती है। उल्टा क्रम वाताग्र गुज़र जाने के बाद के आकाश का है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-169","question":"An occluded front forms when:","options":["two cold air masses of equal temperature meet and slowly mix","a faster cold front overtakes a warm front and lifts the warm sector off the ground","a cold front and a warm front remain stationary side by side for several days","a warm front overtakes a slower cold front and spreads over the surface"],"answer":1,"explanation":"Cold fronts move faster than warm fronts, so the cold front catches up and squeezes out the warm sector, which is lifted aloft. This marks the mature-to-dying stage of a mid-latitude cyclone.","difficulty":"moderate","questionHi":"अधिविष्ट वाताग्र (ऑक्लूडेड फ्रंट) तब बनता है जब:","optionsHi":["समान तापमान की दो शीत वायुराशियाँ मिलती हैं और धीरे-धीरे मिश्रित हो जाती हैं","तेज़ चलने वाला शीत वाताग्र उष्ण वाताग्र को पकड़ लेता है और उष्ण भाग को भूमि से ऊपर उठा देता है","शीत और उष्ण वाताग्र कई दिनों तक साथ-साथ स्थिर रहते हैं","उष्ण वाताग्र धीमे शीत वाताग्र को पकड़ लेता है और धरातल पर फैल जाता है"],"explanationHi":"शीत वाताग्र उष्ण वाताग्र से तेज़ चलते हैं, इसलिए वे उसे पकड़ लेते हैं और उष्ण भाग को ऊपर उठा देते हैं। यह मध्य-अक्षांशीय चक्रवात की परिपक्व से क्षीण होती अवस्था है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-170","question":"In a mature tropical cyclone, the strongest winds and the heaviest rain are found in the:","options":["eyewall","upper-level outflow region","outermost rain bands","eye"],"answer":0,"explanation":"The eyewall, a ring of towering cumulonimbus around the eye, has the fastest winds and most intense rain. The eye is calm with sinking air and clear sky, and the outer bands are weaker.","difficulty":"hard","questionHi":"परिपक्व उष्णकटिबंधीय चक्रवात में सबसे तेज़ हवाएँ और सबसे भारी वर्षा कहाँ पाई जाती है?","optionsHi":["चक्षु-भित्ति (आईवॉल)","ऊपरी स्तर का बहिर्वाह क्षेत्र","सबसे बाहरी वर्षा पट्टियाँ","चक्षु (आँख)"],"explanationHi":"चक्षु-भित्ति, यानी चक्षु के चारों ओर ऊँचे कपासी-वर्षी बादलों का घेरा, में सबसे तेज़ हवाएँ और सबसे तीव्र वर्षा होती है। चक्षु शांत होता है जिसमें हवा नीचे उतरती है और आकाश साफ़ रहता है, तथा बाहरी पट्टियाँ कमज़ोर होती हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-171","question":"Unlike a mid-latitude (extra-tropical) cyclone, a tropical cyclone:","options":["travels from west to east in the belt of the prevailing westerlies of middle latitudes","strengthens over land because friction piles up air near the centre of the storm","forms along the polar front, with a cold core and sharply marked warm and cold fronts","draws its energy from latent heat released over warm ocean, has a warm core and no fronts"],"answer":3,"explanation":"Tropical cyclones are driven by condensation heat over water of at least 26.5 °C, so they are warm-core and frontless and weaken once over land. Mid-latitude cyclones arise from temperature contrasts along fronts.","difficulty":"hard","questionHi":"मध्य-अक्षांशीय (बहिरुष्णकटिबंधीय) चक्रवात के विपरीत, उष्णकटिबंधीय चक्रवात:","optionsHi":["मध्य अक्षांशों की प्रचलित पछुआ पवनों की पेटी में पश्चिम से पूर्व की ओर चलता है","स्थल पर प्रबल हो जाता है क्योंकि घर्षण तूफान के केंद्र के पास वायु को जमा कर देता है","ध्रुवीय वाताग्र के सहारे बनता है, उसका क्रोड शीत होता है और उष्ण तथा शीत वाताग्र स्पष्ट होते हैं","गर्म समुद्र पर मुक्त हुई गुप्त ऊष्मा से ऊर्जा लेता है, उसका क्रोड उष्ण होता है और उसमें वाताग्र नहीं होते"],"explanationHi":"उष्णकटिबंधीय चक्रवात कम से कम 26.5 °C के जल पर संघनन की ऊष्मा से चलते हैं, इसलिए उष्ण-क्रोड और वाताग्र-रहित होते हैं और स्थल पर पहुँचकर कमज़ोर पड़ते हैं। मध्य-अक्षांशीय चक्रवात वाताग्रों के सहारे तापमान के अंतर से बनते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-172","question":"The cold, dry north-east monsoon winds over India in winter are chiefly caused by the:","options":["high pressure over Central Asia (Siberia–Mongolia)","the subtropical westerly jet stream over the Arabian Sea","strong heating of the Thar desert in the cold season","an intense low-pressure centre over the Bay of Bengal"],"answer":0,"explanation":"A strong, cold high-pressure cell builds over Central Asia in winter, and air flows out of it towards the lower pressure over the Indian Ocean as the dry north-east monsoon. The Bay of Bengal low and Thar heating are summer features.","difficulty":"moderate","questionHi":"शीत ऋतु में भारत पर चलने वाली ठंडी, शुष्क उत्तर-पूर्वी मानसूनी हवाएँ मुख्यतः किसके कारण चलती हैं?","optionsHi":["मध्य एशिया (साइबेरिया–मंगोलिया) पर उच्च दाब","अरब सागर पर उपोष्ण पछुआ जेट धारा","शीत ऋतु में थार मरुस्थल का प्रबल तापन","बंगाल की खाड़ी पर एक तीव्र निम्न दाब केंद्र"],"explanationHi":"शीत ऋतु में मध्य एशिया पर प्रबल, ठंडा उच्च दाब बनता है और उससे हवा हिंद महासागर के निम्न दाब की ओर शुष्क उत्तर-पूर्वी मानसून के रूप में बहती है। बंगाल की खाड़ी का निम्न दाब और थार का तापन ग्रीष्मकालीन लक्षण हैं।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-173","question":"As an unsaturated parcel of air rises, before any condensation occurs, which of these remains constant?","options":["Relative humidity","Temperature","Vapour pressure","Mixing ratio"],"answer":3,"explanation":"The mass of water vapour per kilogram of dry air (mixing ratio, close to specific humidity) is conserved until condensation. Temperature and vapour pressure fall, and relative humidity rises as the air cools.","difficulty":"very-hard","questionHi":"जब कोई असंतृप्त वायु-पुंज ऊपर उठता है और संघनन आरंभ नहीं हुआ होता, तब इनमें से क्या स्थिर रहता है?","optionsHi":["सापेक्ष आर्द्रता","तापमान","वाष्प दाब","मिश्रण अनुपात"],"explanationHi":"प्रति किलोग्राम शुष्क वायु में जलवाष्प की मात्रा (मिश्रण अनुपात, जो विशिष्ट आर्द्रता के निकट है) संघनन होने तक संरक्षित रहती है। तापमान और वाष्प दाब घटते हैं तथा वायु के ठंडी होने पर सापेक्ष आर्द्रता बढ़ती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-174","question":"The tornadoes of 'Tornado Alley' in the Great Plains of the USA are favoured mainly by the meeting of:","options":["cold moist air from the Pacific with warm dry air from the Atlantic","warm moist Gulf of Mexico air with cold dry air from the north and the Rockies","polar easterlies from Greenland with warm air from the Caribbean Sea","hot dry desert air from Mexico with warm moist air from the Pacific"],"answer":1,"explanation":"Warm humid Gulf air meets cold dry air from Canada and the Rockies, with strong wind shear, producing severe supercell thunderstorms. The other air-mass pairings are not the main source in the Great Plains.","difficulty":"moderate","questionHi":"अमेरिका के ग्रेट प्लेन्स के 'टॉरनेडो एली' में बवंडर (टॉरनेडो) मुख्यतः किनके मिलने से उत्पन्न होते हैं?","optionsHi":["प्रशांत की शीत आर्द्र वायु और अटलांटिक की उष्ण शुष्क वायु","मेक्सिको की खाड़ी की उष्ण आर्द्र वायु और उत्तर तथा रॉकी पर्वत की शीत शुष्क वायु","ग्रीनलैंड की ध्रुवीय पूर्वी पवनें और कैरेबियन सागर की गर्म वायु","मेक्सिको की गर्म शुष्क मरुस्थलीय वायु और प्रशांत की उष्ण आर्द्र वायु"],"explanationHi":"खाड़ी की उष्ण आर्द्र वायु कनाडा और रॉकी की शीत शुष्क वायु से प्रबल पवन अपरूपण के साथ मिलती है, जिससे भीषण सुपरसेल तड़ित-झंझा बनते हैं। अन्य वायुराशि युग्म ग्रेट प्लेन्स में मुख्य स्रोत नहीं हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-175","question":"The 'Meiyu' of China and the 'Baiu' of Japan refer to:","options":["the spring dust storms blowing from the Gobi desert","the dry north-westerly winter winds blowing from Siberia","the early-summer rainy season along a quasi-stationary front","the typhoon season of August to October on the east coast"],"answer":2,"explanation":"Meiyu and Baiu ('plum rains') are the June–July rains along a stationary front between warm tropical air and cooler air to the north. The other options describe other East Asian weather features.","difficulty":"hard","questionHi":"चीन का 'मेइयू' और जापान का 'बाइउ' किसे कहते हैं?","optionsHi":["गोबी मरुस्थल से आने वाली वसंत की धूल भरी आँधियाँ","साइबेरिया से आने वाली शुष्क उत्तर-पश्चिमी शीतकालीन हवाएँ","अर्द्ध-स्थिर वाताग्र के सहारे होने वाली प्रारंभिक ग्रीष्मकालीन वर्षा ऋतु","पूर्वी तट पर अगस्त से अक्तूबर का टाइफ़ून मौसम"],"explanationHi":"मेइयू और बाइउ ('प्लम वर्षा') उष्ण उष्णकटिबंधीय वायु और उत्तर की ठंडी वायु के बीच स्थित अर्द्ध-स्थिर वाताग्र के सहारे जून–जुलाई में होने वाली वर्षा हैं। अन्य विकल्प पूर्वी एशिया के दूसरे मौसमी लक्षण बताते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-176","question":"The geostrophic wind blows parallel to the isobars because:","options":["the pressure-gradient force is balanced by the Coriolis force","the Coriolis force is balanced by the centrifugal force","the pressure-gradient force is balanced by gravity","the pressure-gradient force is balanced by surface friction"],"answer":0,"explanation":"Above the friction layer, air accelerates until the Coriolis deflection exactly balances the pressure-gradient force, so it flows along the isobars. Near the ground, friction weakens the Coriolis effect and the wind crosses isobars towards low pressure.","difficulty":"hard","questionHi":"भूविक्षेपी (जियोस्ट्रॉफ़िक) पवन समदाब रेखाओं के समानांतर क्यों बहती है?","optionsHi":["दाब प्रवणता बल कोरिओलिस बल से संतुलित होता है","कोरिओलिस बल अपकेंद्री बल से संतुलित होता है","दाब प्रवणता बल गुरुत्व से संतुलित होता है","दाब प्रवणता बल धरातलीय घर्षण से संतुलित होता है"],"explanationHi":"घर्षण परत के ऊपर वायु तब तक त्वरित होती है जब तक कोरिओलिस विक्षेपण दाब प्रवणता बल को ठीक संतुलित न कर दे, इसलिए वह समदाब रेखाओं के साथ बहती है। भूमि के निकट घर्षण कोरिओलिस प्रभाव को घटा देता है और पवन समदाब रेखाओं को काटकर निम्न दाब की ओर बहती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-177","question":"According to Buys Ballot's law, an observer in the Northern Hemisphere who stands with his back to the wind will have the low-pressure area to his:","options":["right","left","back","front"],"answer":1,"explanation":"In the Northern Hemisphere winds circle anticlockwise around a low, so with your back to the wind the low lies on your left (and on your right in the Southern Hemisphere).","difficulty":"hard","questionHi":"बाइस बैलेट के नियम के अनुसार उत्तरी गोलार्द्ध में हवा की ओर पीठ करके खड़े प्रेक्षक के किस ओर निम्न दाब क्षेत्र होगा?","optionsHi":["दाईं ओर","बाईं ओर","पीछे","सामने"],"explanationHi":"उत्तरी गोलार्द्ध में हवाएँ निम्न दाब के चारों ओर वामावर्त घूमती हैं, इसलिए पवन की ओर पीठ करने पर निम्न दाब बाईं ओर होता है (दक्षिणी गोलार्द्ध में दाईं ओर)।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-178","question":"Of the three circulation cells in each hemisphere, the thermally indirect one is the:","options":["both Hadley and Polar cells","Hadley cell","Ferrel cell","Polar cell"],"answer":2,"explanation":"The Ferrel cell (30° to 60°) carries air poleward at the surface and equatorward aloft, with cold air rising and warm air sinking, so it is driven by the neighbouring cells rather than by heating. Hadley and Polar cells are thermally direct.","difficulty":"hard","questionHi":"प्रत्येक गोलार्द्ध की तीन परिसंचरण कोशिकाओं में से तापीय रूप से अप्रत्यक्ष कोशिका कौन-सी है?","optionsHi":["हैडली और ध्रुवीय दोनों कोशिकाएँ","हैडली कोशिका","फ़ेरेल कोशिका","ध्रुवीय कोशिका"],"explanationHi":"फ़ेरेल कोशिका (30° से 60°) में धरातल पर वायु ध्रुव की ओर और ऊपर विषुवत रेखा की ओर चलती है, ठंडी वायु ऊपर उठती और गर्म वायु नीचे उतरती है, इसलिए वह पड़ोसी कोशिकाओं से चलती है, तापन से नहीं। हैडली और ध्रुवीय कोशिकाएँ तापीय रूप से प्रत्यक्ष हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-179","question":"The 500 hPa pressure level, often used by forecasters, lies at a height of about:","options":["10 km","18 km","1.5 km","5.5 km"],"answer":3,"explanation":"About half of the atmosphere's mass lies below the 500 hPa level, near 5.5 km. The 850 hPa level is near 1.5 km, the 250 hPa jet level near 10 km and 100 hPa near the tropical tropopause at about 16–18 km.","difficulty":"moderate","questionHi":"पूर्वानुमानकर्ताओं द्वारा प्रायः प्रयुक्त 500 hPa दाब स्तर लगभग किस ऊँचाई पर होता है?","optionsHi":["10 km","18 km","1.5 km","5.5 km"],"explanationHi":"वायुमंडल का लगभग आधा द्रव्यमान 500 hPa स्तर के नीचे, लगभग 5.5 km पर, होता है। 850 hPa स्तर लगभग 1.5 km पर, 250 hPa जेट स्तर लगभग 10 km पर और 100 hPa उष्णकटिबंधीय क्षोभसीमा के निकट लगभग 16–18 km पर होता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-180","question":"After nitrogen and oxygen, the third most abundant gas in dry air is:","options":["Carbon dioxide","Helium","Neon","Argon"],"answer":3,"explanation":"Argon makes up about 0.93 per cent of dry air, far more than carbon dioxide (about 0.04 per cent), neon or helium, which are trace gases.","difficulty":"moderate","questionHi":"शुष्क वायु में नाइट्रोजन और ऑक्सीजन के बाद तीसरी सबसे अधिक मात्रा वाली गैस कौन-सी है?","optionsHi":["कार्बन डाइऑक्साइड","हीलियम","नियॉन","आर्गन"],"explanationHi":"आर्गन शुष्क वायु का लगभग 0.93 प्रतिशत है, जो कार्बन डाइऑक्साइड (लगभग 0.04 प्रतिशत), नियॉन या हीलियम से बहुत अधिक है; ये अल्प मात्रा वाली गैसें हैं।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-climate-monsoon-181","question":"Match the instrument with what it measures. A. Pyranometer  B. Ceilometer  C. Campbell–Stokes recorder  D. Nephoscope; 1. Duration of sunshine  2. Height of cloud base  3. Global solar radiation  4. Direction and motion of clouds","options":["A-3, B-2, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4","A-3, B-1, C-2, D-4"],"answer":0,"explanation":"A pyranometer records global solar radiation, a ceilometer the height of cloud base, a Campbell–Stokes recorder burns a trace of sunshine hours, and a nephoscope tracks cloud movement.","difficulty":"hard","questionHi":"उपकरण का उसके द्वारा मापी जाने वाली राशि से मिलान कीजिए। A. पायरेनोमीटर  B. सीलोमीटर  C. कैम्पबेल–स्टोक्स रिकॉर्डर  D. नेफोस्कोप; 1. धूप की अवधि  2. बादल के आधार की ऊँचाई  3. वैश्विक सौर विकिरण  4. बादलों की दिशा और गति","optionsHi":["A-3, B-2, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-3, C-1, D-4","A-3, B-1, C-2, D-4"],"explanationHi":"पायरेनोमीटर वैश्विक सौर विकिरण, सीलोमीटर बादल के आधार की ऊँचाई मापता है, कैम्पबेल–स्टोक्स रिकॉर्डर धूप के घंटों का निशान जलाकर अंकित करता है और नेफोस्कोप बादलों की गति का अनुसरण करता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-182","question":"Natural, unpolluted rainwater is slightly acidic, with a pH of about:","options":["4.2","7.0","5.6","6.8"],"answer":2,"explanation":"Dissolved carbon dioxide forms weak carbonic acid and brings clean rain to about pH 5.6. Rain is called acid rain only when it falls well below this, mainly because of sulphur and nitrogen oxides.","difficulty":"moderate","questionHi":"प्राकृतिक, अप्रदूषित वर्षा-जल हल्का अम्लीय होता है, जिसका pH लगभग कितना होता है?","optionsHi":["4.2","7.0","5.6","6.8"],"explanationHi":"घुली हुई कार्बन डाइऑक्साइड दुर्बल कार्बोनिक अम्ल बनाकर स्वच्छ वर्षा को लगभग pH 5.6 पर ले आती है। वर्षा को अम्लीय वर्षा तभी कहा जाता है जब वह इससे काफ़ी नीचे हो, जो मुख्यतः सल्फर और नाइट्रोजन के ऑक्साइडों से होता है।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-climate-monsoon-183","question":"Thermometers at a weather station are kept in a Stevenson screen, a white louvred box, mainly so that they:","options":["stay at a constant temperature, insulated from all changes in the outside air","are shielded from sun, rain and ground heat while air flows freely around them","measure the temperature of the soil at a depth of five centimetres","are cooled by evaporation from the wet inner walls during hot afternoons"],"answer":1,"explanation":"The white colour reflects sunshine and the louvres let air circulate, so the thermometers read true shade air temperature. An insulated box would lag behind real changes.","difficulty":"hard","questionHi":"मौसम केंद्र पर थर्मामीटरों को सफ़ेद झिरीदार बक्से, स्टीवेन्सन स्क्रीन, में रखा जाता है, मुख्यतः इसलिए कि वे:","optionsHi":["स्थिर तापमान पर रहें और बाहरी वायु के सभी परिवर्तनों से विलग रहें","धूप, वर्षा और भूमि की ऊष्मा से सुरक्षित रहें तथा उनके चारों ओर वायु स्वतंत्र रूप से बहती रहे","पाँच सेंटीमीटर की गहराई पर मृदा का तापमान मापें","गर्म दोपहर में भीतरी गीली दीवारों के वाष्पीकरण से ठंडे रहें"],"explanationHi":"सफ़ेद रंग धूप को परावर्तित करता है और झिरियाँ वायु को बहने देती हैं, इसलिए थर्मामीटर छाया की सही वायु का तापमान पढ़ते हैं। विलग बक्सा वास्तविक परिवर्तनों से पिछड़ जाएगा।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-184","question":"In a standard mercury-in-glass maximum thermometer, the reading stays at the highest temperature because:","options":["a constriction above the bulb stops the mercury from flowing back as it cools","a vacuum above the mercury prevents the thread from contracting after heating","a small magnet holds the mercury thread in place once the peak has been reached","mercury does not contract on cooling, unlike the alcohol used in other thermometers"],"answer":0,"explanation":"The narrow constriction breaks the mercury thread when the bulb cools, leaving the top of the column at the peak value until the thermometer is shaken. Mercury does contract on cooling; the constriction merely traps the column.","difficulty":"hard","questionHi":"एक मानक पारा-काँच अधिकतम तापमापी में पाठ्यांक उच्चतम तापमान पर क्यों टिका रहता है?","optionsHi":["बल्ब के ऊपर एक संकीर्णन ठंडा होने पर पारे को वापस बहने से रोक देता है","पारे के ऊपर निर्वात गर्म होने के बाद धागे को सिकुड़ने नहीं देता","एक छोटा चुंबक शिखर पर पहुँचने के बाद पारे के धागे को अपनी जगह रोके रखता है","अन्य तापमापियों में प्रयुक्त ऐल्कोहॉल के विपरीत पारा ठंडा होने पर सिकुड़ता नहीं है"],"explanationHi":"संकरा संकीर्णन बल्ब के ठंडा होने पर पारे के धागे को तोड़ देता है, जिससे स्तंभ का शीर्ष तब तक शिखर मान पर रहता है जब तक तापमापी को झटका न दिया जाए। पारा ठंडा होने पर सिकुड़ता अवश्य है; संकीर्णन केवल स्तंभ को रोक लेता है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-185","question":"A radiosonde, carried aloft by a balloon, is an instrument that:","options":["records the duration of sunshine by burning a trace through a glass sphere","measures the speed of falling raindrops by means of reflected sound waves","measures the height of the cloud base using a laser beam fired upwards","radios back pressure, temperature and humidity of the upper air"],"answer":3,"explanation":"A radiosonde is a small package lifted by a balloon that transmits pressure, temperature and humidity (and, tracked by radar, wind) through the atmosphere. Cloud-base height is measured by a ceilometer and sunshine by a Campbell–Stokes recorder.","difficulty":"moderate","questionHi":"गुब्बारे द्वारा ऊपर ले जाया जाने वाला रेडियोसोंड कौन-सा उपकरण है?","optionsHi":["काँच के गोले से धूप की अवधि अंकित करने वाला","ध्वनि तरंगों से गिरती बूँदों की चाल मापने वाला","लेज़र किरण से बादल के आधार की ऊँचाई मापने वाला","ऊपरी वायु का दाब, तापमान और आर्द्रता रेडियो द्वारा भेजने वाला"],"explanationHi":"रेडियोसोंड गुब्बारे से ऊपर उठाया जाने वाला छोटा पैकेज है जो वायुमंडल में दाब, तापमान और आर्द्रता (तथा रडार से अनुगमन पर पवन) की सूचना प्रेषित करता है। बादल के आधार की ऊँचाई सीलोमीटर और धूप कैम्पबेल–स्टोक्स रिकॉर्डर मापता है।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-186","question":"The World Meteorological Organization defines a climatological 'normal' as the average of weather elements over a period of:","options":["50 years","30 years","10 years","100 years"],"answer":1,"explanation":"WMO normals are averages over 30 consecutive years, reset every decade (such as 1991–2020). Shorter periods reflect only year-to-year variability, not climate.","difficulty":"moderate","questionHi":"विश्व मौसम विज्ञान संगठन (WMO) जलवायु विज्ञान के 'सामान्य मान' को मौसम तत्वों के कितने वर्षों के औसत के रूप में परिभाषित करता है?","optionsHi":["50 वर्ष","30 वर्ष","10 वर्ष","100 वर्ष"],"explanationHi":"WMO के सामान्य मान लगातार 30 वर्षों के औसत होते हैं और हर दशक में नए सिरे से तय किए जाते हैं (जैसे 1991–2020)। कम अवधि केवल वर्ष-दर-वर्ष परिवर्तनशीलता दर्शाती है, जलवायु नहीं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-187","question":"On the Beaufort wind scale, force 12 denotes:","options":["violent storm","storm","hurricane","strong gale"],"answer":2,"explanation":"The scale runs from 0 (calm) to 12 (hurricane force, over about 118 km/h). Force 9 is a strong gale, 10 a storm and 11 a violent storm.","difficulty":"moderate","questionHi":"ब्यूफ़ोर्ट पवन पैमाने पर बल 12 क्या दर्शाता है?","optionsHi":["प्रचंड तूफान","तूफान","हरिकेन (चक्रवाती तूफान)","तेज़ आँधी"],"explanationHi":"यह पैमाना 0 (शांत) से 12 (हरिकेन बल, लगभग 118 km/h से अधिक) तक चलता है। बल 9 तेज़ आँधी, 10 तूफान और 11 प्रचंड तूफान है।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-climate-monsoon-188","question":"Which statement about the variability of annual rainfall in India is correct?","options":["It is highest in the Western Ghats and the north-east, where rain is heaviest, and lowest in western Rajasthan","It is highest along the Coromandel coast and lowest in the Ganga plain, where the monsoon is weakest","It is almost uniform across the country because the south-west monsoon covers every part of India alike","It is highest in low-rainfall areas such as western Rajasthan and lowest in the Western Ghats and the north-east"],"answer":3,"explanation":"Variability is inversely related to rainfall: dry western Rajasthan and Kachchh show the largest fluctuations from year to year, while the heavy-rain Western Ghats and north-east show the least.","difficulty":"hard","questionHi":"भारत में वार्षिक वर्षा की परिवर्तनशीलता के बारे में कौन-सा कथन सही है?","optionsHi":["यह पश्चिमी घाट और उत्तर-पूर्व में सबसे अधिक और पश्चिमी राजस्थान में सबसे कम है","यह कोरोमंडल तट पर सबसे अधिक और गंगा के मैदान में सबसे कम है","यह पूरे देश में लगभग एकसमान है क्योंकि दक्षिण-पश्चिम मानसून पूरे भारत को ढकता है","यह पश्चिमी राजस्थान जैसे कम वर्षा वाले क्षेत्रों में सबसे अधिक और पश्चिमी घाट तथा उत्तर-पूर्व में सबसे कम है"],"explanationHi":"परिवर्तनशीलता वर्षा के व्युत्क्रमानुपाती है: शुष्क पश्चिमी राजस्थान और कच्छ में वर्ष-दर-वर्ष सबसे अधिक उतार-चढ़ाव होता है, जबकि भारी वर्षा वाले पश्चिमी घाट और उत्तर-पूर्व में सबसे कम।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-189","question":"Match the scientist with the explanation of the monsoon associated with him. A. Halley  B. Flohn  C. Koteswaram  D. Yin; 1. Differential heating of land and sea  2. Seasonal shift of the ITCZ  3. Tropical Easterly Jet  4. Shift of the subtropical westerly jet","options":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-1, B-2, C-4, D-3","A-1, B-3, C-2, D-4"],"answer":0,"explanation":"Halley gave the classical land–sea thermal theory, Flohn linked the monsoon to the seasonal migration of the ITCZ, Koteswaram to the Tropical Easterly Jet, and Yin to the shift of the subtropical westerly jet off the Tibetan plateau.","difficulty":"very-hard","questionHi":"वैज्ञानिक का उससे संबद्ध मानसून की व्याख्या से मिलान कीजिए। A. हैली  B. फ्लोन  C. कोटेश्वरम  D. यिन; 1. स्थल और समुद्र का विभेदी तापन  2. ITCZ का ऋतुवत स्थानांतरण  3. उष्णकटिबंधीय पूर्वी जेट  4. उपोष्ण पछुआ जेट का स्थानांतरण","optionsHi":["A-1, B-2, C-3, D-4","A-2, B-1, C-3, D-4","A-1, B-2, C-4, D-3","A-1, B-3, C-2, D-4"],"explanationHi":"हैली ने स्थल–समुद्र की ऊष्मीय व्याख्या दी, फ्लोन ने मानसून को ITCZ के ऋतुवत प्रवास से, कोटेश्वरम ने उष्णकटिबंधीय पूर्वी जेट से और यिन ने तिब्बत के पठार से उपोष्ण पछुआ जेट के हट जाने से जोड़ा।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-190","question":"A psychrometer shows the same reading, 22 °C, on its wet-bulb and dry-bulb thermometers. The dew point of the air is:","options":["18 °C","11 °C","22 °C","impossible to find without the pressure"],"answer":2,"explanation":"No evaporative cooling means the air is saturated: relative humidity is 100 per cent and the dew point equals the air temperature, 22 °C.","difficulty":"very-hard","questionHi":"एक साइक्रोमीटर के गीले और सूखे बल्ब वाले दोनों तापमापी समान पाठ्यांक, 22 °C, दर्शाते हैं। वायु का ओसांक है:","optionsHi":["18 °C","11 °C","22 °C","दाब जाने बिना ज्ञात करना असंभव है"],"explanationHi":"वाष्पीकरणजन्य शीतलन न होने का अर्थ है कि वायु संतृप्त है: सापेक्ष आर्द्रता 100 प्रतिशत है और ओसांक वायु के तापमान, 22 °C, के बराबर है।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-191","question":"The Saffir–Simpson scale, which rates hurricanes in five categories, is based on the storm's:","options":["central pressure","sustained wind speed","storm-surge height","diameter of the eye"],"answer":1,"explanation":"The Saffir–Simpson hurricane wind scale classifies storms from Category 1 to 5 by sustained wind speed only. Surge and pressure also matter for damage but are not the rating criterion.","difficulty":"moderate","questionHi":"सैफ़िर–सिम्पसन पैमाना, जो हरिकेनों को पाँच श्रेणियों में रखता है, तूफान की किस विशेषता पर आधारित है?","optionsHi":["केंद्रीय दाब","निरंतर पवन चाल","तूफानी लहर की ऊँचाई","चक्षु का व्यास"],"explanationHi":"सैफ़िर–सिम्पसन हरिकेन पवन पैमाना तूफानों को केवल निरंतर पवन चाल के आधार पर श्रेणी 1 से 5 में वर्गीकृत करता है। क्षति के लिए लहर और दाब भी महत्त्वपूर्ण हैं, पर वे वर्गीकरण का आधार नहीं हैं।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-climate-monsoon-192","question":"For a station in a hilly region, the IMD considers a heat wave only when the maximum temperature reaches at least:","options":["40 °C","35 °C","30 °C","45 °C"],"answer":2,"explanation":"IMD thresholds are 40 °C for plains, 37 °C for coastal stations and 30 °C for hilly regions, each with a departure from normal of at least 4.5 °C. The 40 °C and 45 °C options are plains figures.","difficulty":"hard","questionHi":"किसी पर्वतीय क्षेत्र के स्टेशन के लिए IMD लू (ऊष्ण लहर) तभी मानता है जब अधिकतम तापमान कम से कम कितना हो?","optionsHi":["40 °C","35 °C","30 °C","45 °C"],"explanationHi":"IMD की सीमाएँ मैदानों के लिए 40 °C, तटीय स्टेशनों के लिए 37 °C और पर्वतीय क्षेत्रों के लिए 30 °C हैं, प्रत्येक के साथ सामान्य से कम से कम 4.5 °C का विचलन भी चाहिए। 40 °C और 45 °C के विकल्प मैदानों के आँकड़े हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-193","question":"Irrespective of the departure from normal, the IMD declares a 'severe heat wave' for a station in the plains when the actual maximum temperature reaches:","options":["45 °C or more","47 °C or more","49 °C or more","50 °C or more"],"answer":1,"explanation":"IMD uses absolute criteria as well: a maximum of 45 °C or more is a heat wave, and 47 °C or more is a severe heat wave, whatever the departure from normal.","difficulty":"very-hard","questionHi":"सामान्य से विचलन की परवाह किए बिना, मैदानी स्टेशन के लिए IMD 'तीव्र लू' तब घोषित करता है जब वास्तविक अधिकतम तापमान पहुँचता है:","optionsHi":["45 °C या अधिक","47 °C या अधिक","49 °C या अधिक","50 °C या अधिक"],"explanationHi":"IMD निरपेक्ष मानदंड भी अपनाता है: 45 °C या अधिक अधिकतम तापमान लू और 47 °C या अधिक तीव्र लू है, चाहे सामान्य से विचलन कुछ भी हो।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-194","question":"Which of these oceans is unusual because its northern surface currents reverse direction between summer and winter under the monsoon winds?","options":["Indian Ocean","Pacific Ocean","Arctic Ocean","Atlantic Ocean"],"answer":0,"explanation":"Only the northern Indian Ocean is overlain by a seasonally reversing monsoon, so its currents flow clockwise in summer (south-west monsoon drift) and anticlockwise in winter. The other oceans have permanent gyres.","difficulty":"moderate","questionHi":"इनमें से कौन-सा महासागर असामान्य है क्योंकि मानसूनी पवनों के कारण उसकी उत्तरी सतही धाराएँ ग्रीष्म और शीत ऋतु में दिशा बदल लेती हैं?","optionsHi":["हिंद महासागर","प्रशांत महासागर","आर्कटिक महासागर","अटलांटिक महासागर"],"explanationHi":"केवल उत्तरी हिंद महासागर के ऊपर ऋतु के अनुसार दिशा बदलने वाला मानसून होता है, इसलिए उसकी धाराएँ ग्रीष्म में दक्षिणावर्त (दक्षिण-पश्चिम मानसून प्रवाह) और शीत में वामावर्त चलती हैं। अन्य महासागरों में स्थायी चक्र (गायर) हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-195","question":"The atmosphere is said to be 'absolutely unstable' when:","options":["the environmental lapse rate lies between the saturated and dry adiabatic rates","the environmental lapse rate is lower than the saturated adiabatic lapse rate","temperature increases with height from the ground to the cloud base","the environmental lapse rate exceeds the dry adiabatic lapse rate"],"answer":3,"explanation":"If the surrounding air cools with height faster than a rising parcel (ELR above about 10 °C per km), any lifted parcel stays warmer and keeps rising. The other conditions describe stable or conditionally unstable air.","difficulty":"hard","questionHi":"वायुमंडल को 'निरपेक्ष रूप से अस्थिर' तब कहा जाता है जब:","optionsHi":["परिवेशी ताप ह्रास दर संतृप्त और शुष्क रुद्धोष्म दरों के बीच हो","परिवेशी ताप ह्रास दर संतृप्त रुद्धोष्म ताप ह्रास दर से कम हो","भूमि से बादल के आधार तक ऊँचाई के साथ तापमान बढ़ता हो","परिवेशी ताप ह्रास दर शुष्क रुद्धोष्म ताप ह्रास दर से अधिक हो"],"explanationHi":"यदि परिवेश की वायु ऊँचाई के साथ उठते वायु-पुंज से तेज़ ठंडी होती है (ELR लगभग 10 °C प्रति km से अधिक), तो कोई भी उठाया गया पुंज गर्म बना रहता है और उठता रहता है। अन्य स्थितियाँ स्थिर या सप्रतिबंध अस्थिर वायु बताती हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-196","question":"In an atmosphere with an environmental lapse rate of 8 °C per km (dry adiabatic about 10 °C per km, saturated about 5 °C per km), the air is:","options":["neutrally stable","conditionally unstable","absolutely stable","absolutely unstable"],"answer":1,"explanation":"An ELR between the saturated and dry rates makes the air stable for an unsaturated parcel (which cools 10 °C/km) but unstable once the parcel is saturated and cools only about 5 °C/km. That is conditional instability.","difficulty":"very-hard","questionHi":"जिस वायुमंडल में परिवेशी ताप ह्रास दर 8 °C प्रति km हो (शुष्क रुद्धोष्म लगभग 10 °C प्रति km, संतृप्त लगभग 5 °C प्रति km), वहाँ वायु है:","optionsHi":["उदासीन स्थिर","सप्रतिबंध अस्थिर","निरपेक्ष रूप से स्थिर","निरपेक्ष रूप से अस्थिर"],"explanationHi":"संतृप्त और शुष्क दरों के बीच की ELR असंतृप्त पुंज (जो 10 °C/km से ठंडा होता है) के लिए वायु को स्थिर बनाती है, पर पुंज के संतृप्त होने और केवल लगभग 5 °C/km से ठंडा होने पर वह अस्थिर हो जाती है। यही सप्रतिबंध अस्थिरता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-197","question":"The dense winter fog that often covers the Indo-Gangetic plain on calm, clear nights is mainly:","options":["steam fog","advection fog","upslope fog","radiation fog"],"answer":3,"explanation":"On calm, cloudless nights the ground radiates heat, cools the moist air above it to its dew point and forms radiation fog. Advection fog needs warm moist air moving over a cold surface, and upslope fog needs air forced up a slope.","difficulty":"moderate","questionHi":"शांत, साफ़ रातों में प्रायः सिंधु-गंगा के मैदान को ढकने वाला घना शीतकालीन कोहरा मुख्यतः किस प्रकार का होता है?","optionsHi":["वाष्प कोहरा","अभिवहन कोहरा","उर्ध्व-ढाल कोहरा","विकिरण कोहरा"],"explanationHi":"शांत, मेघरहित रातों में भूमि ऊष्मा विकीर्ण करती है, ऊपर की आर्द्र वायु को ओसांक तक ठंडा कर देती है और विकिरण कोहरा बनता है। अभिवहन कोहरे के लिए ठंडी सतह पर गर्म आर्द्र वायु चाहिए और उर्ध्व-ढाल कोहरे के लिए ढाल पर चढ़ाई गई वायु।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-198","question":"A 'black frost' is best described as:","options":["a frost that forms only on dark surfaces such as asphalt roads and burnt fields","a deposit of ice on the underside of leaves when the dew point stays above freezing","freezing air so dry that no white ice deposits form, yet plant tissue freezes and turns dark","frost formed when freezing fog is blown over dark soil by strong night winds"],"answer":2,"explanation":"In a black frost the air temperature falls below freezing but the air is so dry that no hoar frost (white ice crystals) forms; plant tissue is nonetheless frozen and blackens. Hoar frost needs enough moisture for deposition.","difficulty":"hard","questionHi":"'काला पाला' (ब्लैक फ्रॉस्ट) का सर्वोत्तम वर्णन है:","optionsHi":["ऐसा पाला जो केवल डामर की सड़कों और जले खेतों जैसी काली सतहों पर बनता है","ओसांक के हिमांक से ऊपर रहने पर पत्तियों की निचली सतह पर बनने वाला बर्फ़ का निक्षेप","हिमांक से नीचे की इतनी शुष्क वायु कि सफ़ेद बर्फ़ का निक्षेप नहीं बनता, फिर भी पौधों के ऊतक जमकर काले पड़ जाते हैं","रात की तेज़ हवाओं द्वारा जमे कोहरे को काली मिट्टी पर उड़ा ले जाने से बना पाला"],"explanationHi":"काले पाले में वायु का तापमान हिमांक से नीचे गिर जाता है पर वायु इतनी शुष्क होती है कि श्वेत पाला (सफ़ेद बर्फ़ के कण) नहीं बनता; फिर भी पौधों के ऊतक जम जाते हैं और काले पड़ जाते हैं। श्वेत पाले के निक्षेप के लिए पर्याप्त नमी चाहिए।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-199","question":"25 mm of rain falls uniformly over a field of 2 hectares. The volume of water received is:","options":["500 m³","5,000 m³","250 m³","50 m³"],"answer":0,"explanation":"Rainfall of 1 mm over 1 m² is 1 litre. So 25 mm over 20,000 m² is 25 × 20,000 = 5,00,000 litres, which is 500 m³. 5,000 m³ forgets the mm-to-metre conversion.","difficulty":"moderate","questionHi":"2 हेक्टेयर के खेत पर 25 mm वर्षा समान रूप से होती है। प्राप्त जल का आयतन है:","optionsHi":["500 m³","5,000 m³","250 m³","50 m³"],"explanationHi":"1 m² पर 1 mm वर्षा 1 लीटर के बराबर है। अतः 20,000 m² पर 25 mm वर्षा = 25 × 20,000 = 5,00,000 लीटर, यानी 500 m³। 5,000 m³ में mm से मीटर का रूपांतरण छूट गया है।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-200","question":"A tropical cyclone with sustained winds of 100 knots (about 185 km/h) is classed by the IMD as a:","options":["Very severe cyclonic storm","Severe cyclonic storm","Super cyclonic storm","Extremely severe cyclonic storm"],"answer":3,"explanation":"IMD classes 90–119 knots (167–221 km/h) as an extremely severe cyclonic storm. Very severe is 64–89 knots, and a super cyclonic storm needs 120 knots (222 km/h) or more.","difficulty":"very-hard","questionHi":"100 नॉट (लगभग 185 km/h) की निरंतर पवन चाल वाला उष्णकटिबंधीय चक्रवात IMD द्वारा किस श्रेणी में रखा जाता है?","optionsHi":["अति भीषण चक्रवाती तूफान","भीषण चक्रवाती तूफान","सुपर चक्रवाती तूफान","अत्यंत भीषण चक्रवाती तूफान"],"explanationHi":"IMD 90–119 नॉट (167–221 km/h) को अत्यंत भीषण चक्रवाती तूफान मानता है। अति भीषण 64–89 नॉट होता है और सुपर चक्रवाती तूफान के लिए 120 नॉट (222 km/h) या अधिक चाहिए।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-201","question":"The highest air temperature officially recognised by the WMO, 56.7 °C in 1913, was recorded at:","options":["Furnace Creek, Death Valley","Al Aziziyah, Libya (Sahara)","Dallol, Danakil Depression","Dasht-e Lut, Iran (Lut Desert)"],"answer":0,"explanation":"The 1913 reading at Furnace Creek, Death Valley (USA), is the WMO-accepted world record. Libya's Al Aziziyah reading of 58 °C (1922) was invalidated, and Dallol holds the highest average annual temperature, not the record peak.","difficulty":"hard","questionHi":"WMO द्वारा मान्य सर्वोच्च वायु तापमान, 1913 में 56.7 °C, कहाँ दर्ज किया गया था?","optionsHi":["फर्नेस क्रीक, डेथ वैली","अल अज़ीज़िया, लीबिया (सहारा)","दल्लोल, डानाकिल गर्त","दश्त-ए-लूत, ईरान (लूत मरुस्थल)"],"explanationHi":"डेथ वैली (अमेरिका) के फर्नेस क्रीक का 1913 का पाठ्यांक WMO द्वारा स्वीकृत विश्व रिकॉर्ड है। लीबिया के अल अज़ीज़िया का 58 °C (1922) का पाठ्यांक अमान्य कर दिया गया और दल्लोल का रिकॉर्ड सर्वोच्च औसत वार्षिक तापमान का है, शिखर का नहीं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-202","question":"The polar-front theory of the origin of mid-latitude cyclones was developed by:","options":["G. Hadley and the English school","Sir Gilbert Walker and the Indian school","V. Bjerknes and the Bergen school","W. Köppen and the German climatologists"],"answer":2,"explanation":"Vilhelm Bjerknes, his son Jacob and colleagues at Bergen explained temperate cyclones as waves on the polar front around 1918–1920. Köppen classified climates, Hadley explained the trade-wind cell and Walker studied the Southern Oscillation.","difficulty":"moderate","questionHi":"मध्य-अक्षांशीय चक्रवातों की उत्पत्ति के ध्रुवीय वाताग्र सिद्धांत का विकास किसने किया?","optionsHi":["जी. हैडली और अंग्रेज़ी स्कूल","सर गिल्बर्ट वॉकर और भारतीय स्कूल","वी. बर्कनेस और बर्गन स्कूल","डब्ल्यू. कोपेन और जर्मन जलवायुविद"],"explanationHi":"विल्हेल्म बर्कनेस, उनके पुत्र जैकब और बर्गन के सहयोगियों ने लगभग 1918–1920 में शीतोष्ण चक्रवातों को ध्रुवीय वाताग्र पर उठी तरंगों के रूप में समझाया। कोपेन ने जलवायु का वर्गीकरण किया, हैडली ने व्यापारिक पवन कोशिका समझाई और वॉकर ने दक्षिणी दोलन का अध्ययन किया।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-203","question":"Annual insolation at the surface is greatest over the subtropical deserts rather than at the equator mainly because:","options":["the subtropical days are longer than the equatorial days throughout the year","cloud-free, dry air lets far more sunlight reach the ground","the Earth is nearer the Sun in the subtropics than at the equator","the Sun is directly overhead for longer over the subtropics"],"answer":1,"explanation":"Equatorial skies are cloudy and humid, so clouds and vapour reflect and absorb much of the sunlight, whereas subtropical deserts are cloudless and transparent. The Sun is never overhead for long over the subtropics, and distance from the Sun does not vary with latitude.","difficulty":"hard","questionHi":"सतह पर वार्षिक सूर्यातप भूमध्य रेखा की बजाय उपोष्ण मरुस्थलों पर सर्वाधिक क्यों होता है?","optionsHi":["उपोष्ण क्षेत्रों में दिन पूरे वर्ष विषुवतीय दिनों से लंबे होते हैं","मेघरहित, शुष्क वायु के कारण कहीं अधिक सूर्य-प्रकाश भूमि तक पहुँचता है","पृथ्वी उपोष्ण क्षेत्रों में भूमध्य रेखा की तुलना में सूर्य के अधिक निकट होती है","उपोष्ण क्षेत्रों में सूर्य अधिक समय तक सिर के ठीक ऊपर रहता है"],"explanationHi":"विषुवतीय आकाश बादलों और आर्द्रता से भरा रहता है, इसलिए बादल और वाष्प सूर्य-प्रकाश का बड़ा भाग परावर्तित और अवशोषित कर लेते हैं, जबकि उपोष्ण मरुस्थल मेघरहित और पारदर्शी होते हैं। उपोष्ण क्षेत्रों में सूर्य अधिक समय सिर के ऊपर नहीं रहता और सूर्य से दूरी अक्षांश के साथ नहीं बदलती।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-204","question":"The Earth is farthest from the Sun, a position called aphelion, around:","options":["21 June","23 September","3 January","4 July"],"answer":3,"explanation":"Aphelion occurs in early July, about 152 million km from the Sun, while perihelion falls in early January. 21 June is the solstice, which depends on axial tilt rather than distance.","difficulty":"moderate","questionHi":"पृथ्वी सूर्य से सबसे अधिक दूरी पर, जिस स्थिति को अपसौर कहते हैं, लगभग कब होती है?","optionsHi":["21 जून","23 सितंबर","3 जनवरी","4 जुलाई"],"explanationHi":"अपसौर जुलाई के आरंभ में, सूर्य से लगभग 152 मिलियन km दूर होता है, जबकि उपसौर जनवरी के आरंभ में पड़ता है। 21 जून अयनांत है, जो दूरी पर नहीं बल्कि अक्षीय झुकाव पर निर्भर करता है।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-climate-monsoon-205","question":"The persistent temperature inversion that traps smog over Los Angeles is chiefly a:","options":["radiation inversion","subsidence inversion","frontal inversion","advection inversion"],"answer":1,"explanation":"Sinking air in the Pacific subtropical high warms by compression and sits over the cool marine layer, forming a lid. Radiation inversions are nightly and shallow, and frontal ones occur only along fronts.","difficulty":"hard","questionHi":"लॉस एंजिलिस के ऊपर धूम-कोहरे को रोककर रखने वाला स्थायी तापमान व्युत्क्रमण मुख्यतः किस प्रकार का है?","optionsHi":["विकिरण व्युत्क्रमण","अवतलन व्युत्क्रमण","वाताग्री व्युत्क्रमण","अभिवहन व्युत्क्रमण"],"explanationHi":"प्रशांत के उपोष्ण उच्च दाब में नीचे उतरती वायु संपीडन से गर्म होकर ठंडी समुद्री परत के ऊपर ढक्कन-सा बना देती है। विकिरण व्युत्क्रमण रात्रि के और उथले होते हैं तथा वाताग्री व्युत्क्रमण केवल वाताग्रों के सहारे होते हैं।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-206","question":"A large difference between the dry-bulb and wet-bulb readings of a psychrometer indicates that the air has:","options":["a high dew point","a low pressure","low relative humidity","high relative humidity"],"answer":2,"explanation":"The drier the air, the faster water evaporates from the wet bulb and the cooler it gets, so the depression grows. When the air is saturated the two readings are equal.","difficulty":"moderate","questionHi":"साइक्रोमीटर के शुष्क-बल्ब और आर्द्र-बल्ब के पाठ्यांकों में बड़ा अंतर दर्शाता है कि वायु में:","optionsHi":["ओसांक ऊँचा है","दाब कम है","सापेक्ष आर्द्रता कम है","सापेक्ष आर्द्रता अधिक है"],"explanationHi":"वायु जितनी शुष्क होगी, गीले बल्ब से जल उतनी तेज़ी से वाष्पित होगा और वह उतना ठंडा होगा, इसलिए अंतर बढ़ता है। संतृप्त वायु में दोनों पाठ्यांक बराबर होते हैं।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-207","question":"On a day the maximum temperature is 36.4 °C and the minimum is 21.8 °C, the mean daily temperature and the diurnal range are respectively:","options":["29.1 °C and 14.6 °C","29.1 °C and 58.2 °C","58.2 °C and 14.6 °C","14.6 °C and 29.1 °C"],"answer":0,"explanation":"Mean = (36.4 + 21.8) ÷ 2 = 29.1 °C, and diurnal range = 36.4 − 21.8 = 14.6 °C. The other options swap the two or use the sum 58.2 °C.","difficulty":"moderate","questionHi":"किसी दिन अधिकतम तापमान 36.4 °C और न्यूनतम 21.8 °C है। औसत दैनिक तापमान और दैनिक तापांतर क्रमशः हैं:","optionsHi":["29.1 °C और 14.6 °C","29.1 °C और 58.2 °C","58.2 °C और 14.6 °C","14.6 °C और 29.1 °C"],"explanationHi":"माध्य = (36.4 + 21.8) ÷ 2 = 29.1 °C और दैनिक तापांतर = 36.4 − 21.8 = 14.6 °C। अन्य विकल्पों में दोनों को आपस में बदल दिया गया है या योगफल 58.2 °C लिया गया है।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-208","question":"Which method of finding the average rainfall over an area gives each rain gauge a weight proportional to the area nearest to it, found by drawing perpendicular bisectors between gauges?","options":["Thiessen polygon method","Arithmetic mean method","Normal ratio method","Hypsometric method"],"answer":0,"explanation":"The Thiessen method divides the area into polygons around each gauge and weights its rainfall by the polygon area. The arithmetic mean gives all gauges equal weight, and the isohyetal method (not listed) uses contours of equal rainfall.","difficulty":"hard","questionHi":"किसी क्षेत्र की औसत वर्षा ज्ञात करने की कौन-सी विधि प्रत्येक वर्षामापी को उसके निकटतम क्षेत्र के अनुपात में भार देती है, जिसे वर्षामापियों के बीच लंब-समद्विभाजक खींचकर निकाला जाता है?","optionsHi":["थीसेन बहुभुज विधि","समांतर माध्य विधि","सामान्य अनुपात विधि","समोच्चता (हिप्सोमेट्रिक) विधि"],"explanationHi":"थीसेन विधि क्षेत्र को प्रत्येक वर्षामापी के चारों ओर बहुभुजों में बाँटती है और उसकी वर्षा को बहुभुज के क्षेत्रफल से भारित करती है। समांतर माध्य सभी वर्षामापियों को समान भार देता है और समवर्षा रेखा (आइसोहाइटल) विधि (विकल्प में नहीं) समान वर्षा की रेखाओं का उपयोग करती है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-209","question":"A wind rose is a diagram that shows, for a given place:","options":["how wind speed changes with height above the ground at a station","how often winds blow from each direction, often with speeds","the pressure gradient between two neighbouring weather stations","the track followed by a cyclone during its entire life cycle"],"answer":1,"explanation":"A wind rose plots the frequency of winds from each compass direction (and often speed classes) over a period, helping in planning airports and cities. It is not a track chart or a height profile.","difficulty":"moderate","questionHi":"पवन गुलाब (विंड रोज़) किसी स्थान के लिए क्या दर्शाने वाला आरेख है?","optionsHi":["भूमि से ऊँचाई के साथ पवन चाल कैसे बदलती है","प्रत्येक दिशा से कितनी बार हवा चलती है, प्रायः उनकी चाल सहित","दो पड़ोसी स्टेशनों के बीच दाब प्रवणता","चक्रवात द्वारा अपने जीवनकाल में अपनाया गया पथ"],"explanationHi":"पवन गुलाब किसी अवधि में प्रत्येक दिशा से चलने वाली हवाओं की बारंबारता (और प्रायः चाल श्रेणियाँ) दर्शाता है, जो हवाई अड्डों और नगरों की योजना में सहायक है। यह पथ-चार्ट या ऊँचाई-आरेख नहीं है।","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-climate-monsoon-210","question":"The solar constant, the solar energy received per unit area at the top of the atmosphere, is about:","options":["0.137 kW/m²","137 kW/m²","1.37 kW/m²","13.7 kW/m²"],"answer":2,"explanation":"The solar constant is about 1,361–1,370 W/m², that is roughly 1.37 kW/m², on a surface held square to the Sun's rays at the mean Earth–Sun distance. The other values are off by powers of ten.","difficulty":"moderate","questionHi":"सौर स्थिरांक, अर्थात् वायुमंडल के शीर्ष पर प्रति इकाई क्षेत्रफल प्राप्त सौर ऊर्जा, लगभग कितना है?","optionsHi":["0.137 kW/m²","137 kW/m²","1.37 kW/m²","13.7 kW/m²"],"explanationHi":"सौर स्थिरांक लगभग 1,361–1,370 W/m², यानी लगभग 1.37 kW/m², है, जो पृथ्वी–सूर्य की औसत दूरी पर सूर्य की किरणों के लंबवत सतह के लिए है। अन्य मान दस की घातों से भिन्न हैं।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-211","question":"Weather satellites such as INSAT-3D are placed in geostationary orbit mainly because from there they:","options":["stay close to the ground and give the highest-resolution images of single clouds","drift slowly westwards and cover every longitude once a week","pass over the poles and scan the whole Earth once every day in strips","keep a constant view of the same large area, giving continuous cloud imagery"],"answer":3,"explanation":"A geostationary satellite orbits at about 36,000 km above the equator with a period of 24 hours, so it hovers over one region and images it every few minutes. Polar-orbiting satellites are the ones that pass over the poles.","difficulty":"moderate","questionHi":"INSAT-3D जैसे मौसम उपग्रह मुख्यतः भूस्थिर कक्षा में इसलिए रखे जाते हैं क्योंकि वहाँ से वे:","optionsHi":["भूमि के निकट रहते हैं और अलग-अलग बादलों के सर्वोच्च विभेदन वाले चित्र देते हैं","धीरे-धीरे पश्चिम की ओर खिसकते हैं और सप्ताह में एक बार प्रत्येक देशांतर को ढकते हैं","ध्रुवों के ऊपर से गुज़रते हैं और प्रतिदिन एक बार पूरी पृथ्वी को पट्टियों में स्कैन करते हैं","एक ही बड़े क्षेत्र का निरंतर दृश्य बनाए रखते हैं और बादलों के चित्र लगातार देते हैं"],"explanationHi":"भूस्थिर उपग्रह भूमध्य रेखा से लगभग 36,000 km ऊपर 24 घंटे की परिक्रमा अवधि के साथ घूमता है, इसलिए वह एक क्षेत्र के ऊपर स्थिर रहता है और हर कुछ मिनट में उसका चित्र लेता है। ध्रुवों के ऊपर से गुज़रने वाले उपग्रह ध्रुवीय-कक्षीय होते हैं।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-212","question":"A Doppler weather radar is valuable for storm warning because, besides locating rain, it can measure:","options":["the height of the tropopause above the storm from the delay of the reflected pulse","the motion of raindrops towards or away from it, revealing wind patterns inside the storm","the acidity of the rainwater from the strength of the returned microwave signal","the temperature of the sea surface beneath the storm from the shift in radar frequency"],"answer":1,"explanation":"The Doppler shift in the returned microwave signal gives the radial velocity of precipitation, so the radar can detect rotation, wind shear and the wind field of cyclones. It cannot measure sea temperature, tropopause height or rain acidity.","difficulty":"moderate","questionHi":"डॉप्लर मौसम रडार तूफान की चेतावनी के लिए मूल्यवान क्यों है, जबकि वह वर्षा का स्थान बताने के अलावा क्या माप सकता है?","optionsHi":["परावर्तित स्पंद की देरी से तूफान के ऊपर क्षोभसीमा की ऊँचाई","रडार की ओर या उससे दूर बूँदों की गति, जो तूफान के भीतर पवन-प्रतिरूप प्रकट करती है","लौटे सूक्ष्मतरंग संकेत के रंग से वर्षा-जल का pH","रडार की आवृत्ति में बदलाव से तूफान के नीचे समुद्र की सतह का तापमान"],"explanationHi":"लौटे सूक्ष्मतरंग संकेत का डॉप्लर विस्थापन वर्षण का अरीय वेग देता है, इसलिए रडार घूर्णन, पवन अपरूपण और चक्रवातों के पवन-क्षेत्र का पता लगा सकता है। वह समुद्री तापमान, क्षोभसीमा की ऊँचाई या वर्षा की अम्लता नहीं माप सकता।","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-climate-monsoon-213","question":"In the IMD's four-stage cyclone warning system, the 'cyclone warning' is issued about how many hours before the expected landfall?","options":["24 hours","72 hours","12 hours","48 hours"],"answer":0,"explanation":"IMD issues a pre-cyclone watch about 72 hours ahead, a cyclone alert about 48 hours ahead, a cyclone warning about 24 hours ahead and a post-landfall outlook about 12 hours before landfall.","difficulty":"hard","questionHi":"IMD की चार-चरणीय चक्रवात चेतावनी प्रणाली में 'चक्रवात चेतावनी' संभावित स्थल-प्रवेश से लगभग कितने घंटे पहले जारी की जाती है?","optionsHi":["24 घंटे","72 घंटे","12 घंटे","48 घंटे"],"explanationHi":"IMD स्थल-प्रवेश से लगभग 72 घंटे पहले पूर्व-चक्रवात निगरानी, 48 घंटे पहले चक्रवात सतर्कता, 24 घंटे पहले चक्रवात चेतावनी और लगभग 12 घंटे पहले स्थल-प्रवेश-पश्चात दृष्टिकोण जारी करता है।","source":"UPSC Prelims · State PCS"},
  {"id":"geo-climate-monsoon-214","question":"Match the name of a tropical cyclone with the region where it is used. A. Hurricane  B. Typhoon  C. Willy-willy  D. Cyclone; 1. Caribbean and North Atlantic  2. China Sea and western Pacific  3. North-western Australia  4. Bay of Bengal and Arabian Sea","options":["A-2, B-1, C-3, D-4","A-1, B-3, C-2, D-4","A-1, B-2, C-3, D-4","A-1, B-2, C-4, D-3"],"answer":2,"explanation":"Hurricanes occur over the Caribbean and North Atlantic, typhoons over the China Sea and western Pacific, 'willy-willies' off north-western Australia, and 'cyclones' in the Bay of Bengal and Arabian Sea.","difficulty":"moderate","questionHi":"उष्णकटिबंधीय चक्रवात के नाम का उस क्षेत्र से मिलान कीजिए जहाँ वह प्रयुक्त होता है। A. हरिकेन  B. टाइफ़ून  C. विली-विली  D. साइक्लोन; 1. कैरेबियन और उत्तरी अटलांटिक  2. चीन सागर और पश्चिमी प्रशांत  3. उत्तर-पश्चिमी ऑस्ट्रेलिया  4. बंगाल की खाड़ी और अरब सागर","optionsHi":["A-2, B-1, C-3, D-4","A-1, B-3, C-2, D-4","A-1, B-2, C-3, D-4","A-1, B-2, C-4, D-3"],"explanationHi":"हरिकेन कैरेबियन और उत्तरी अटलांटिक में, टाइफ़ून चीन सागर और पश्चिमी प्रशांत में, 'विली-विली' उत्तर-पश्चिमी ऑस्ट्रेलिया के तट पर और 'साइक्लोन' बंगाल की खाड़ी तथा अरब सागर में आते हैं।","source":"SSC CGL · State PCS"},
  {"id":"geo-climate-monsoon-215","question":"Potential evapotranspiration (PET) is best defined as the amount of water that:","options":["is actually lost from a catchment during a year through evaporation and transpiration","remains in the soil after a dry spell, available to the roots of the growing crops","falls as rain but is lost as runoff before it can enter the soil in the catchment","would be lost by evaporation and plant transpiration if soil moisture were always ample"],"answer":3,"explanation":"PET is the atmospheric demand for water: the loss that would occur if moisture supply were unlimited. Actual evapotranspiration is lower in dry soils, and the gap between the two measures water deficit.","difficulty":"hard","questionHi":"संभावित वाष्पोत्सर्जन (PET) की सर्वोत्तम परिभाषा उस जल की मात्रा है जो:","optionsHi":["वर्ष भर में किसी जलग्रहण क्षेत्र से वाष्पीकरण और वाष्पोत्सर्जन द्वारा वास्तव में नष्ट होती है","शुष्क अवधि के बाद मृदा में शेष रहती है और फसलों की जड़ों को उपलब्ध होती है","वर्षा के रूप में गिरती है पर मृदा में प्रवेश करने से पहले अपवाह के रूप में बह जाती है","वाष्पीकरण और पादप वाष्पोत्सर्जन से नष्ट होता, यदि मृदा में सदैव पर्याप्त नमी रहती"],"explanationHi":"PET जल की वायुमंडलीय माँग है: वह हानि जो नमी की आपूर्ति असीमित होने पर होती। शुष्क मृदा में वास्तविक वाष्पोत्सर्जन कम होता है और दोनों का अंतर जल-कमी का माप है।","source":"UPSC Prelims · State PCS"},
];

export default questions;
